/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20020702-5","meetingId":"h14-cm07","date":"2002年7月2日","dateIso":"2002-07-02","committee":"総務委員会","time":"午前１０時０８分～午後３時４３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"土井委員","kind":"質問","question":"あるいは、一定の国家的な意味も含めての考え方が整備されるべきというご意見等々については、理解ができると思うんです。そういう形のものが行われているときに、どのようにお考えなのかを、ちょっと伺っておきたいと思います。","respondent":"西島経理課長","answer":"これは、当然、遵守されているものだろうと、私どもは考えているところです。果たして、そのこととこの公契約条例というものが比較するのかどうなのかというところは、かなり疑問を持っているところです。","id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"こんなものが加味されて、当然、一定レベルを下回るのはあまりにも不当ではないですかということはあってもいいんじゃないかと思うんです。十分研究、検討はしていただかなきゃいけない中身ではないかと思っているんですけれども、何かお考えを。","respondent":"西島経理課長","answer":"区が発注者としての優越性を持ってそういう条件を決めるということは、独占禁止法に触れるおそれが、おそらく出てくるのではなかろうかと思います。区が個々の条例の中でそれを決めるということは、そういう点で問題があるのではなかろうかというのが、今の私どもの考えです。","id":"exchange-002"},{"speaker":"土井委員","kind":"意見","question":"全然話が違うわけで、その意味では、それには当たらないと私は思います。課題、問題はこんなものがありますという形で議論を進めていただけないかと、こういうことを申し上げているつもりなんですとの意見を述べました。","respondent":"西島経理課長","answer":"そうしますと、これは果たして区が制定する条例なんだろうかという点で、疑問が出てまいります。それは別の議論になりますけれども、区の段階でこの条例を制定するのは、かなり疑問があるのではなかろうと考えているところです。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"これって、地方自治法の第２条との関係では違うんじゃないかと思うんですよ。第２条第２項、そこに書いてあるのをちょっと読んでいただけませんか。","respondent":"西島経理課長","answer":"第２条第９項第２号です。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"しかし、区内で働く労働者、実際に働いている人にも、地方自治体の責務としてはあるということだと思うんです。それはどうなんか尋ねました。","respondent":"本間総務部長","answer":"法の解釈はありますけれども、いずれにいたしましても、賃金につきましては、私ども、基本的には労使の問題と理解しています。先ほど経理課長が説明したとおり、そういう意味で問題があるのではないかと言っているわけですので、ひとつよろしくお願いいたします。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"あわせて付帯決議がされているわけですけれども、これについては、どういう見解をお持ちなんでしょうか。指導、監督ということが求められていると思うんですけれども、これについていかがか尋ねました。","respondent":"片田施設担当課長、西島経理課長","answer":"経理課長が説明しましたように、１m3当たりのコンクリートを打つためには人手と材料費がかかる、それに基づいて積算しています。交通誘導員等の人件費なんかも積算の中にきちっと入れた中で、一応、工事の額を決めてあります。６番目に、建設労働者の賃金・労働条件の確保が適切に行われるように努めること」ということで、この付帯決議がついたものです。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問・要望","question":"私が質問したのは単純明快で、先ほど、５０種の設計労務単価の平均が１万９,１０６円とかいう数字を教えていただきましたよね。非常に厳しい水準ですから、品川区内の収入の基準、平均どの程度なのかというのを教えてほしいと求めました。","respondent":"西島経理課長","answer":"中小企業の育成に関しましては、品川区は従来から取り組んです。中小企業者、ＪＶを組んで発注をするというような努力をいたしまして、区内の中小企業業者の育成に努めているところです。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"その実態というのは、調べたことってあるんでしょうか。区としては、こうした陳情を受けて、そういうところは実態調査とかはされないんか尋ねました。","respondent":"西島経理課長","answer":"一定金額以上、工事で言うと４,５００万円以上の下請けを出す場合は、工事施工台帳の設置が義務づけられております。孫請けまで、契約上及ぼすことができるということは、現在の法律の中では難しいと考えているところです。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問","question":"さっきの質問で、ご答弁いただかなかったけれども、区内の平均収入。","respondent":"市岡企画財政課長","answer":"そのことは直接お答えできないんですが、平均年齢４３歳１０カ月で、給与ベース額が４６万４,１４４円。ただ、これは年齢が少し高めですので、これから推測をするということになろうかと思います。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問・要望","question":"ほんとうに現場の人の賃金まできちっと確保できるような行政というんでしょうか、区としての姿勢というんでしょうか、そのことが非常に大事だなと。ですから、ぜひ積極的に取り組んでいただきたいと、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"藤田委員","kind":"質問・要望","question":"今の質疑を通じて国はわかりましたが、東京都はどのような対応をされているのか。もしわかっていれば、お知らせほしいと求めました。","respondent":"西島経理課長","answer":"東京都ですけれども、この条例について、特に制定をするとか、検討をするとかという動きは聞いてございません。そういう考えは持っていないと聞いてあります。","id":"exchange-011"},{"speaker":"藤田委員","kind":"質問・要望","question":"そうすると、こうした陳情が、例えば城南５区で議会に提出されているのか。もしその辺の動きがわかれば、教えてほしいと求めました。","respondent":"西島経理課長","answer":"私どものつかんでいるところでは、城南５区で、既に大田区で陳情が出されたということで、大田区では、不採択になったという報告を聞いています。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問","question":"思いをどうやって我々、なお、品川区が受けとめるかというところが問題なんです。いろいろ条件のことについて配慮しなさいよということがあるわけですから、何をしているのかということをお知らせ願えればありがたいと思います。","respondent":"西島経理課長","answer":"強制はできませんけれども、特別な技能はない無技能者の場合は、公共職業安定所から派遣される人たちを使っていただきたいというお願いをしています。","id":"exchange-013"},{"speaker":"塚本委員","kind":"質問","question":"このままではいけないんだということをこちらも承知していないと、ものは変わっていかないという部分があると思うんです。どんどんしわ寄せが下に行っていることは間違いないわけですから、ある種のよい方向に導くことができないわけですから、そこのところの認識ですかね。","respondent":"西島経理課長","answer":"強制とか何とかということはできませんけれども、適正な賃金をもって雇用するようにという要望なり、契約書に留意事項なりの記載については可能であると考えております。","id":"exchange-014"},{"speaker":"川西副委員長","kind":"提案","question":"公契約だけの保障というのはどうかということが、１回ここで継続をして、もう少し勉強したい。そして、できたら、取り扱いについても、最初の提案も、皆さんお考えいただいて、一たんここで継続にされたらどうか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それから、態度としては、先ほど来出ていますが、公が賃金まで決めていくというところもありますし、指導とかいう点でできることをしていく。おそらく理解をしているはずですから、行政としてできることをしていってもらうということを強く要望して、我々は願意に沿いがたいという態度です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"藤田委員","kind":"意見","question":"区でもし制定する場合は、独占禁止法という話もありましたけれども、これはやっぱり問題を含んでいるかなと思います。したがいまして、区として、賃金を確保する条例を制定するということについては、やはり同意できない、このように考えますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"桜井委員","kind":"質問","question":"もちろん制定に向けての検討ですから、この陳情項目そのものを検討してほしいということですから、もう一歩。ですから、そういう点では、何ができるかということも含めて検討してもらいたいというところでの、趣旨採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"土井委員","kind":"意見","question":"やはり、どのような対応、態度がとれるのかという検討を十分にしていただくということは大変必要なことだろうと思うわけです。ぜひ、趣旨を取り入れるということで、そのようにしていただければありがたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"確認","question":"道具というか、新たにつけ加えなきゃいけないお金が出てくる可能性ってあるじゃないですか、手掘りになったとか。さっきの賃金の話じゃないけど、契約が済んでいるんだから、それも全部ひっくるめてやれと押しつけちゃうものなんか尋ねました。","respondent":"西島経理課長","answer":"特に下を掘るものについては多いんですが、その際には、契約変更の手続をとります。場合によっては期間の変更だけで済むもの、金額の変更まで及ぼすものというケースがございまして、期間の延長だけで済んだです。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"両方とも期間の延長だけですか。要するに、期間が延びただけじゃなくて、プラスの仕事が増えているけど、全部済んだんか尋ねました。","respondent":"西島経理課長、市岡企画財政課長","answer":"すべて、中のやり繰りの中で済んだです。もう１回計上しませんと仕事ができませんので、９月補正予算にその特定財源をつけて、いわば再計上する予定で準備を進めております。","id":"exchange-021"},{"speaker":"川西副委員長","kind":"確認","question":"ちょっと確認だけしておきたいんですけれども、契約議案として出されたものか、ちょっと忘れているものですから。私自身も、議案をいただいているわけですから、結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"続き。この二つは、法で決められて報告をするということになっていて、今の打ち切ったというのは、どういう手続きがこれからされるわけか尋ねました。","respondent":"市岡企画財政課長","answer":"これは予定されていた仕事ですから、平成１４年度の財源がそれだけ残っておりますので、ご議決いただければ直ちに執行するという形になります。私ども執行機関限りでやるのではなくて、あくまで予算のご議決をいただいて、ご承認をいただいて仕事をするという形になります。","id":"exchange-023"},{"speaker":"林（宏）委員","kind":"意見","question":"そうすると、これと一緒に報告すべきじゃないのかな。法にはないんでしょうけれども、決算でしか出てこないということになると、ちょっとおかしいんじゃないかとの意見を述べました。","respondent":"市岡企画財政課長","answer":"私ども平成１４年度で財源が措置されることがわかりましたけれども、いわばあてのない、その場限りの財政運営をするということになります。そのほうが財政民主主義だということに、法律上、なっております。","id":"exchange-024"},{"speaker":"林（宏）委員","kind":"質問","question":"あくまでも３月３１日、平成１３年度の決算書には、繰越明許という決算がされると考えていいんですか。それとも、後から、もうできないとわかったから、３月３１日に戻って、それは打ち切りということにするんか尋ねました。","respondent":"市岡企画財政課長","answer":"平成１３年度は、予定していた予算を議決をいただいたにもかかわらず、できませんでしたという決算上のご報告をするわけです。平成１３、１４を継続してやるというのが繰越の制度ですが、一たん打ち切りにするです。","id":"exchange-025"},{"speaker":"土井委員","kind":"質問","question":"今までのお話を伺うと、要するに３月で決算をした。実際上は、決算のときは、あるいはそれを新たにのせた予算のときにやるんですよと、こういうことでよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"桜井委員","kind":"質問・要望","question":"単費というんでしょうか、一定に基づいて補助金なり、負担金なりが来ますよね。もしわかれば、教えていただきたいと思うんです。","respondent":"市岡企画財政課長","answer":"補助の予定額は２８２万６,０００円で、補助対象になるものに限られておりますので、こういうことです。たまたまこれは補助金が認められたです。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問・要望","question":"きょうは口頭でと言いますけれども、何か文書でそういう協力要請というのはされたんでしょうか。地元の協力に当たっての条件とか、話し合いがされたんか尋ねました。","respondent":"古川総務課長","answer":"２地区のうち１地区については、地区まで確認してございませんけれども、既に協議会においてご説明をし、了解をいただきましたと。私どもの収益金の一定の枠の中で考えている部分と、地元対策ということで、そういった日常的な部分での対応について十分にやっていただく。","id":"exchange-028"}]},{"id":"topic-02","title":"の大井町駅東口ペデストリアンデッキスロープ整備工事（その３）","agenda":"の大井町駅東口ペデストリアンデッキスロープ整備工事（その３）","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"スロープの勾配ですけれども、ここに３％と載ってますが、例えば、通常の車いすなんかは２％ぐらいと記憶しているんですけれども、何か根拠があるんか尋ねました。","respondent":"市岡企画財政課長","answer":"要するに取り付けの区役所通りとの高低差を考えて、３％がやむを得ないということで施工いたしました。非常に摩擦係数の大きいすべりにくいものを対応するとか、３％でも、車いすの方に支障のないような設計になってあります。","id":"exchange-029"},{"speaker":"林（宏）委員","kind":"質問","question":"工事（その３）となっているんですけれども、幾つまで続くのかというのと、その１、その２についての金額と、落札の業者がわかれば説明を求めました。","respondent":"西島経理課長","answer":"一応、その４まで予定しています。〔「何をやるの」と呼ぶ者あり〕きのう、お話が出ました、橋脚の下の街路灯だとか、導水管等の工事を実施する予定です。","id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問","question":"これは偶然でしょうかね。落札の次は後に回るというような構図が、透かすと見えなくもないので、その辺はないですねという念を押したいんですけれども。","respondent":"西島経理課長","answer":"増えてきていますし、引き続き、そういう傾向にいくだろうと考えております。２月なり、４カ月なり指名停止、私どもは考えているところです。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"４ページの写真がありますね。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"藤田委員","kind":"質問・要望","question":"もう一つ関係の部署に伝えていただきたいのは、橋の下はおそらく歩道駐輪が考えられます。この２点、関係の部署に伝えていただきたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"桜井委員","kind":"質問","question":"街路４号というんでしょうか、きのう拝見したあそこの脇、あの街路は都道ですか、区道ですか。前段、区道の街路なんか尋ねました。","respondent":"西島経理課長","answer":"今の質問は、ペデストリアンデッキは都市計画道路街路４号線になります。ほかのところは、ちょっとわかりかねます。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問・要望","question":"やっぱり建設委員会ですか、所管が違いますね。では、要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-03","title":"みずほ銀行のシステム障害","agenda":"みずほ銀行のシステム障害","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"どうもご苦労さまでした。ここに、いろいろやってますよというのはあったけれども、指定金融機関のみずほという意味からも、区としてどういうことをしたんか尋ねました。","respondent":"小野（弘）副収入役","answer":"区の対応のところにありますように、みずほのほうには説明を求める意味での呼び出しをいたしまして、説明を受けてまいりましたけれども。説明をいただくということで、説明を受けるということになっておりまして、新たにもう一度説明を受けるということになっております。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"それは正確に、これしかなかったということなんですか。４００万円ぐらい多く区のほうには入れてくれちゃうというような話になっているから、後で調べたら正確に入っていたということなんですか、これは。","respondent":"小野（弘）副収入役","answer":"旧第一勧業銀行分については、全部引き落としたものとして、契約日に一たん区に入金していただいております。その後、正しいデータが出た段階で精算して、その分については返還しているという手続をとっております。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"財政上、一たん区に入ったお金を簡単に返還するとか、そういうことはできるんですか。大ざっぱに６億２,４００万円強のところを６億２,８００万円ぐらいどんと入れておいて、返しますよという、そんなに簡単な手続でいいんか尋ねました。","respondent":"小野（弘）副収入役","answer":"ですから、区の歳入の中には入れてなかった。雑部金も歳入ですけれども、歳入歳出外現金というところでの扱いをいたしました。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"要するに、お金のやり取りを、そんなにあやふなことでいいわけですか、大ざっぱな概算で。それが、そんなに簡単に返してくれるんなら、すぐに１２月に返してくれればいいんで、そういう理屈は成り立ちませんか。","respondent":"市岡企画財政課長","answer":"その中で、いわば確定前のお金をきちっと決まった段階でお返しするという、こういう手続です。件数は明解ですので、そういう意味では、適正な処理だと考えられます。","id":"exchange-039"},{"speaker":"土井委員","kind":"質問・要望","question":"ほんとうに正しく入るものかどうかというのを見極めた上で、実務的にきちんと運用されているんだということで確認をしていいかというのが一つ。請求をするとかというお話等を伺っておりましたけれども、その経過はどうなっているのか、どうなるのか。","respondent":"小野（弘）副収入役、中尾根企画部長","answer":"システム会社のシステムエンニジアに待機していただいた部分の金額として、５４万８５７３円について、損害賠償の請求をいたしました。４月分のみずほ銀行に係る口座振替の手数料、合わせて１６万９,７２８円、通知をいただいておりま… 一番いい例が、住民税の納付のことを考えていただきたいんですが、特別徴収にしろ、普通徴収にしろ、あれは都民税と区民税と一緒に納めているんです。","id":"exchange-040"},{"speaker":"土井委員","kind":"質問","question":"今、請求をお出しになったということは伺った。１６万円余のものを返してもらったということなんですけれども、５４万円余の請求だけれども、それはどのようになる見通しをお持ちか尋ねました。","respondent":"小野（弘）副収入役","answer":"「大変ご迷惑をおかけいたしましたということで、お客様には十分ご相談させていただきながら、誠心誠意対応します」ということでいただいております。","id":"exchange-041"},{"speaker":"桜井委員","kind":"質問・要望","question":"３番目の区の対応なんですけれども、ここに「報告を求めているが、原因解明には未だ不十分」とありますよね。情報システム課の担当者と区のほうの担当者という説明が若干あったんですけれども、もう少し丁寧に教えていただけますか尋ねました。","respondent":"小野（弘）副収入役","answer":"きちんと図示したもの等で説明をいただきたいとお願いをしているんですけれども、なかなか、そこまでのものがまだ出していただけないということです。","id":"exchange-042"},{"speaker":"桜井委員","kind":"質問・要望","question":"今の冒頭の話だと、区が持っている施設での公共料金という理解なんですか。もう少し、公共料金の中身について、教えていただきたいんですけれども。","respondent":"小野（弘）副収入役","answer":"かかったものについて引かれますと、それぞれのところで、１回１回支出命令を切って支出をしていたです。ただ、５月、６月につきましては正常に、これまでと同様な形で動いております。","id":"exchange-043"}]},{"id":"topic-04","title":"(7) の不在者投票を送致する投票区（所）の指定","agenda":"(7) の不在者投票を送致する投票区（所）の指定","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"これを説明されて、いろいろな単語が出てくるんですけれども、どの時期にやる作業なのかを言ってくれないとわからない。質問の意味はわかりますか。","respondent":"野田口選挙管理委員会事務局長","answer":"説明が不十分ですみません。選挙人にとっては何の影響もなく、ほんとうに管理執行上の問題です。","id":"exchange-044"},{"speaker":"林（宏）委員","kind":"質問","question":"今度は、１カ所になっちゃう。さっき言ったように、第１投票所の投票率というのは、どうやって計算を出して発表されていくんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"投票率につきましては、不在者投票については、指定した投票区、第４０投票所で投票録に記載されることになります。したがって、各それぞれの残りの関係投票区につきましては、投票録に記載されないということです。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"質問","question":"それは投票という行為をされているわけですよね。だけど、投票率に入らないということになってくるわけか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"投票録の記載が、指定投票区の投票録に記載されるようになりますので、個別の投票区ごとの部分については出ませんけれども、全体の投票率のところでそれが反映される、そういう形になります。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問","question":"そのエリアの人々の投票行為が無視されるわけですから。と僕は思いますけれども、いかがか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"その投票区ごとに分けていましたから、そういった意味では、指定投票区以外の投票区につきましては投票率に反映されません。確かに、そういった側面では影響がありますけれども、全体としての投票率については、当然、不在者投票も入るということです。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"意見","question":"例えば、さっきの誕生八幡から５０通の不在者投票があったというカウントはされているわけでしょ。例えば、荏原第三中学校に行く前に、選管にある状態のときにとの意見を述べました。","respondent":"野田口選挙管理委員会事務局長","answer":"実務的にちょっと対応しきれないということから、指定投票区制度を設けて、〔「全部やめたの」と呼ぶ者あり〕だから１カ所に送致するわけです。投票率というのは、投票録に記載して初めて当日有権投票したものプラス不在者投票といった部分の、不在者投票の部分がなくなるです。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問","question":"わかりますけれども、じゃあ、カウントをやめようというのが、これが始まった趣旨なわけですか。パソコンの中に、不在者投票された人は入っちゃっているわけですから、第４投票区とかってカウントはすぐに出てくると思うんですよ。","respondent":"野田口選挙管理委員会事務局長","answer":"一つは、そういったいろいろな選挙制度の変更があって、この制度が設けられました。今、いわゆるコンピュータでデータ上わかるんじゃないかということですが、そういった投票録上の投票率とは別個の統計上のそれについては可能です。","id":"exchange-049"},{"speaker":"土井委員","kind":"質問","question":"それを、今までは４３カ所にばらまいたと、それを何でわざわざ１カ所に持っていくんですか。ということは、箱は、今までは４３個だったのが、４４個になりますよということか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"指定投票区には、不在者投票用の投票箱を２台置く予定です。５０名弱の人を使って、大体朝から夕方までかけて１万６,０００票の不在者投票を、そういった作業を１カ所で行うです。","id":"exchange-050"},{"speaker":"土井委員","kind":"確認","question":"ある意味では正直なんじゃないかなと思ったということで、それでいいと思いますので、確認だけします。それは、どこまで許されて、どこまで可能性があるのかということの追求と、実態的なものは何か進んでいるんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"ただ、渡すときに、もし不受理のものがあれば、現実的にはないですけれども、これは法的に受理できませんという対応をしています。次のステップで国の研究会の中で考えられているのは、自分の住んでいる投票所でなくても、どこでもできるというのが第２段階。","id":"exchange-051"},{"speaker":"土井委員","kind":"質問","question":"前の日には不在者投票した方がわかっているわけですから、次の日に見たら、何ら問題が起こらないわけです。お金もかかることですから、どうなるかわかりませんけれども、意見のみで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"桜井委員","kind":"質問","question":"当日の開票の報告の仕方というんでしょうか。この場合、例えば、指定投票区の荏原第三中学校のところで出されるのは、一緒にするから、そこは問題ないという理解なんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"４３カ所でやっていたのを１カ所でやるということだけで、その１カ所でやったものを開票所に持って行くわけです。開票所に持って行って初めて、みんな一緒になってやりますので、開票事務そのものについては、従前と変わりません。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問","question":"よく、不在者投票がどのぐらいだということを言いますよね。それはまたそれとして報告するという理解なんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"指定投票区の投票管理者が、不在者投票は１万６,０００件ありましたということで、開票所の開票管理者のほうに報告するということになります。","id":"exchange-054"},{"speaker":"桜井委員","kind":"質問","question":"要するに、私が知りたいのは、有権者との関係で、それはどういう形で公表されるのかというところです。そこは、有権者への公表はどうなんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"先ほど、統計上、そういったものが出ないかというようなことでしたが、それは出ます。これまでの投票率の投票録、開票録に基づいた部分と、統計上の部分とちょっと切り分けて、今後、検討してみたいと思っています。","id":"exchange-055"},{"speaker":"桜井委員","kind":"質問","question":"難しいことを聞いているんじゃなくて、だから、不在者投票というのは、どういう形で報告されるんですかということです。今の話だと、ちょっとわからない。","respondent":"野田口選挙管理委員会事務局長","answer":"第４０投票所で１万６,０００件不在者投票がありましたというような形で、公的な文書には載ります。選挙の記録もつくりますけれども、それもそういうふうな形になります。","id":"exchange-056"},{"speaker":"林（宏）委員","kind":"質問","question":"一つだけいいですか。〔「数値に間違いなければ、両方書いたほうがいい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"土井委員","kind":"質問","question":"どうせ直すんですから、１行目の「品川区総合庁舎に」というのを「庁舎内に」にしておいたほうがいいと思います。４行目と同じにしておいてくださいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"桜井委員","kind":"意見","question":"今の助役の指摘も大事だと思いますので、文言はお任せしますけれども。同じ言葉を２回に使うのがどうかなと思いますので、参考までにとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"林（宏）委員","kind":"質問","question":"品川区としては、品川区の人間がここに行ったときに、不利益になるよということを入れたほうがいいんじゃないですかということ。正副委員長で持って行く。","respondent":"伊藤委員長","answer":"この意見書の文章を確定した後のことにつきましては、その取り扱いにつきましては、検討していきたいと考えていますので、よろしくご理解のほどをお願いいたします。","id":"exchange-060"},{"speaker":"桜井委員","kind":"質問","question":"議会でのこうした意見書を出すという点で、願わくば、行政のほうも、例えば区長名で要請されるとかというのはお考えになっているんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"桜井委員","kind":"質問・要望","question":"きのう、３点について申し上げたところなんですけれども、最初の購入の問題から質問をさせてほしいと求めました。基本財産の４億７,０００万円というのは、要するに原資は区民の税金だと思うんですけれども、この考え方は間違いだという理解なんか尋ねました。","respondent":"濱野助役","answer":"財団で独自に資金を充当した３,０００万円、基本財産５億円については、税金がそこなわれたというようなことは当たらないと考えています。それから、管理団体との関係ですが、やはり補助金の使途について、それを監査なり、指導するのが第一義的な介入の仕方と考えています。","id":"exchange-062"},{"speaker":"桜井委員","kind":"質問・要望","question":"今言ったように区の原資というふうに確認しているんですけれども、それでいいのかどうかというのを、もう一度お答えほしいと求めました。そこのところだけ、もう一度確認したいんです。","respondent":"濱野助役","answer":"つまり、財団がその財をもとに資金運用するというのは、財団の使命です。ものによってはリスクであれすることはありますけれども、財団が安全かつ有利な資金運用をするというのは、財団の使命だと考えております。","id":"exchange-063"},{"speaker":"桜井委員","kind":"質問・要望","question":"私が申し上げたのは、運用していくということを否定するわけじゃないんです、もちろん事業をやっていくわけですから。それから、区の関与についても質問しているんですけれども。","respondent":"濱野助役、中尾根企画部長","answer":"さっきの３６ページですけれども、「剰余金は」となっていますね。本来的には事業運営に充てて、それでいろいろやってなおかつの話ですから、それを同一に論ずることは非常に短絡的です。したがって、補助金についても、１年間経ってどういう事業に投入したのか、精算までちゃんとしております。","id":"exchange-064"},{"speaker":"桜井委員","kind":"質問・要望","question":"要するに１億６,０００万円は、いろいろな事例からすると、３５％戻ってくるかどうかわからないという話も一部にはありますよね。遠い目で見れば、それはそれだよとお考えになっているのかどうか、改めてそこはお答えほしいと求めました。","respondent":"濱野助役","answer":"どの程度のものであるかということを考えれば、いわゆる基本財産ではなくて、いわゆる財団の運営について支障があるということではありません。","id":"exchange-065"},{"speaker":"桜井委員","kind":"質問","question":"区長自身が損害を全部払えとかどうとかという問題もあるかもしれないけれども、道義的責任というのはすごく大きいと思うんですよ。これについては、どうなんか尋ねました。","respondent":"濱野助役","answer":"それからもう１点、対応、ないしは対応策としては、財団の規定を整理する。ここが、第１回定例会でいろいろご指摘をいただき、また決議をいただいたことに対するけじめと対応だと考えています。","id":"exchange-066"},{"speaker":"桜井委員","kind":"質問","question":"この１億６,０００万円の損害が出た場合というのは、区は関係ないと、あとは品川文化振興事業団がよろしくやってくれよということなんでしょうか。じゃあ、これで幕引きですかと、これで責任ない、これをもって終わりということなんか尋ねました。","respondent":"濱野助役","answer":"中国債なんかも、果実を得るという性質のものでありますから、その都度対応を取るという筋のものではないということでお話を申し上げたところです。これに対する対応としては、そして取るべき対応策、これをもって一定の対応を取ったという認識です。","id":"exchange-067"},{"speaker":"桜井委員","kind":"確認","question":"だから、そこのところを、私は確認したいんです。非常に不鮮明だという問題と、〔発言する者あり〕だって、責任がいまだはっきりしてないじゃないか尋ねました。","respondent":"濱野助役","answer":"答弁を求められておりませんけれども、今、委員のご発言の中に、理事長が理事印を押したとおっしゃっいましたけれども、それは訂正していただきたい。","id":"exchange-068"},{"speaker":"塚本委員","kind":"意見","question":"今のままだったら見えるけれども、かえって見えなくなってしまうので、そういう心配があります。お答えないんでしょうけれども、そこのところを確かめたいとの意見を述べました。","respondent":"西島経理課長、片田施設担当課長","answer":"金額ですけれども、屋上緑化そのものでは１,９５０万円で予定をしております。私もときどき工事を見ながら、気を使ってまいりたいと考えております。 土についても軽量土とかできるだけ軽いものを使いまして考えてあります。緑化によって雨漏りが起こるということは、一応ないと、私どもは確信しています。","id":"exchange-069"},{"speaker":"塚本委員","kind":"質問","question":"過重の件ですけれども、１００ｔで８８８m2だと、１１０kgぐらいですか。２６０kgというのは、場所によって、マックスを２６０kgに収めようという考え方か尋ねました。","respondent":"片田施設担当課長","answer":"トータルで数値的な見方をしますと、おおむね２６０kgぐらいで、一応収まるかなといったような内容です。したがいまして、３００kgまではもつという計算をしてございましたので、安全上、十分支障がないと判断しています。","id":"exchange-070"},{"speaker":"藤田委員","kind":"提案","question":"予算特別委員会でも、私、屋上ガーデニングについていろいろ提案しました。これだと１ｍちょっとぐらいの塀ですので、その辺、どういう工夫をされているのかとの意見を述べました。","respondent":"西島経理課長、片田施設担当課長","answer":"なかなか適当な保険がないということで、今年度中に、開設までにはもう少し検討を進めてまいりたいと考えております。それから、非常用と時計については、どういう形になるかわかりませんけれども、検討してまいりたいと考えております。建築基準法的な考え方を申しますと、通常の屋上、高さ１.１ｍ以上の高さの塀を設置していただきたいというような表現になっています。","id":"exchange-071"},{"speaker":"藤田委員","kind":"質問・要望","question":"現在の檻みたいな塀の内側に、上れないようなものをずっと張るべきだと思うんですよ。これはそんなにお金がかかるものじゃないと思うんですけれども、ぜひ、検討をしてほしいと求めました。","respondent":"片田施設担当課長","answer":"今、ご意見があったことにつきましては、検討させていただきたいと思います。","id":"exchange-072"},{"speaker":"嶋委員","kind":"質問","question":"１カ月ぐらいで収穫がどんどんされるということなんですが、どういうものがされるのか、ちょっとお聞きをしたい。そういうことをお聞きしたいと思います。","respondent":"西島経理課長、片田施設担当課長","answer":"何か問い合わせがあって団体がお見えになったときには、その都度対応する部分はあろうかと思いますが、常時は難しいかなと考えているところです。実施をした後に、どれだか変わるのかと… 先ほど、ちょっと説明で漏れましたところがございました。まだ検討中ですけれども、ちょっとした展望台みたいなものを設置したいといったような話がございまして、検討しています。","id":"exchange-073"},{"speaker":"嶋委員","kind":"質問・要望","question":"最後に要望なんですが、栄養剤をくださったんで、これは業者のほうに言って無料で配布していただけたらと思います。帰りに、ちょっとお土産をいただくのもいいかなと思っていますので、要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"桜井委員","kind":"質問","question":"１,９５０万円ですか、どうして区内の造園業者とか、あるいはそれにかかわっての建設関係とかを考えられなかったのか。そうなると、やっぱり技術的にも蓄積されていけば、お互いに需要も高まっていくし、そういう点についてはご検討いただかなかったんか尋ねました。","respondent":"西島経理課長","answer":"ここの業者を決めるに当たっては、プロポーザル方式をとって実施をしてまいりました。今まで、プロポーザルの提案説明のときから、できるだけ区内の業者とうまく連携をとってやっていただくというようなことを説明しております。","id":"exchange-075"},{"speaker":"桜井委員","kind":"質問","question":"せっかく庁舎の上をやるわけですから、やっぱりそういう配慮というんですか、ちょっと残念なんです。１,９５０万円ですから、ちょっとさみしいんですけれども、何かその辺の検討というのはいかがでしょうかね。","respondent":"西島経理課長","answer":"やっぱりこれだけの大きな屋上緑化をやった実績というのがありませんので、逆に言うと、漏れ伝わっていているようなこともあります。","id":"exchange-076"},{"speaker":"林（宏）委員","kind":"質問","question":"これで終わりじゃないわけで、これから始まるわけですから、区内のそういう業者が元気が出るようにリードしていってあげる。それはできますよね。","respondent":"西島経理課長","answer":"委員、ご指摘の考えで、今後、進めてまいりたいと、私ども思っております。","id":"exchange-077"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"大体、エレベーターの入り口で教えてくれるわけですから、そういうこともしていっていただきたい。それから、ちらっとさっき出たけれども、たばこがいけないのは十分にわかりましたけれども、飲み食いはどうか尋ねました。","respondent":"西島経理課長","answer":"まだ検討しておりませんけれども、その辺は、これからちょっと詰めさせていただきたいと思います。それから、管理の点ですけれども、オープンしている際には、「本日は、屋上庭園を開場しています」というような表示は、２階、３階にする予定です。","id":"exchange-078"},{"speaker":"川西副委員長","kind":"質問","question":"先ほどの１,９５０万円ですが、これは段差解消とか、施設整備が入っているんでしょうか。一つ伺います。","respondent":"西島経理課長","answer":"入口というんですか、屋上庭園側のスロープについては含まれてあります。庁舎の構造上の問題ですので、そこは私どものほうの小破修理という予算がありますので、その部分でちょっと手入れをすることになります。","id":"exchange-079"},{"speaker":"川西副委員長","kind":"提案","question":"では、今の確認でいくと、そういう庁舎管理部分を除いて、１,９５０万円でできるというようなイメージで完成を待てばいいわけですね。要望ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"藤田委員","kind":"意見","question":"具体的にどういうふうな作業でやって、どういうふうな結果になって、どういう点が問題になったのか。都市はどこかに限らずとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"林（宏）委員","kind":"質問","question":"事業部制をとっている自治体ってほかにないんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"桜井委員","kind":"質問","question":"三重県なんかはやってないんですか。最初に行政評価をやりましたよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"林（宏）委員","kind":"意見","question":"名称は事業部じゃないんだけれども、名前が専務とか部長とか、いわゆる企業の名称を職員につけてやっているというようなことを聞いた。北九州の市長は、行革を非常にあれだからとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"桜井委員","kind":"質問","question":"場所はちょっとまだ調べてないんですけれども、ＮＰＯの関係というのは、ここじゃなくて区民部なんでしょうか。〔「区民生活事業部」と呼ぶ者あり〕住民自治とか、住民参加とかになるとこちらになるんか尋ねました。","respondent":"本間総務部長","answer":"そうすると、所管がないですよね。全てになります。","id":"exchange-085"},{"speaker":"桜井委員","kind":"意見","question":"これから、区民との協働の部分をどういうふうにうまく進めていくのかということが、ちょっと関心があるところなんです。調べますけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1588#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":72575,"voices":242}},{"id":"h14-20020703-13","meetingId":"h14-cm07","date":"2002年7月3日","dateIso":"2002-07-03","committee":"清掃・リサイクル特別委員会","time":"午前１０時０５分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"上山委員","kind":"質問・要望","question":"ちょっと基本的なことで最初にお尋ねしたいんですが、ちょっとあれば教えていただきたいなと思うんですが、ちょっとその辺はどうでしょうか。なければないでいいんですが。","respondent":"山口品川清掃事務所長","answer":"ただ、それが損害賠償にまでなったかというケースは今まではなかろうと思います。今までのケースでいきますと、ないと思います。","id":"exchange-001"},{"speaker":"上山委員","kind":"確認","question":"一応車線変更で安全確認を怠っただとか、今のご説明ではそういうのが二つですか、特に安全確認の問題で。特に年末などの忙しいような時期はどんな感じなんか尋ねました。","respondent":"山口品川清掃事務所長","answer":"一定の範囲では配備をした上で、通常は年末年始の際は作業を、年末年始の増える量をそれなりに想定した上での増車なり増員なりをした形でプールしています。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問・要望","question":"最後に要望なんですけれども、特に毎年であるかわかりませんけれども、予想はされているときがあったと思うんです。これは要望でとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"辻委員","kind":"確認","question":"どっちの後方確認をしたのか、走行しているんだったら、大型ダンプに接触して、そのダンプの、同車ってダンプですよね。直進する車というのは、時々おまわりさんにつかまったりしているんですけれども、この右後方フェンダーというのはどんな形でぶつかったんか尋ねました。","respondent":"山口品川清掃事務所長","answer":"私どものほうの車が速度を落として車線変更を開始をしたところ、こういう格好ですので。左へ寄ろうとしたものですから、後ろから来た後方車のちょうど後ろ側のところを引っかけたと、こういうような接触事故です。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"幾つかお伺いしたいんですが、当然区の持ち出しといいますか、税金を使っているところがあると思うんです。その辺はどうなのかということと、前回の事務事業の説明の中にも、直営のものと比較して違いがあるのかどうかという点をまず。","respondent":"山口品川清掃事務所長、中山清掃リサイクル課長","answer":"これにつきましては相手方が２割の責任割合ということで、３万９,７９１円、こういうことです。私どもには３万９,７９１円、この相殺をした差額の１万６,２０９円が私どもの損害賠償額として相手方に払った、こういうことです。自損部分は、今所長が申し上げた約１９万８,０００円については、これは経費をかけて直営車両を修理をしています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"１４号に関しては出ていますが、相当これ以上の金額が出ているということですから、まだまだ対策が不十分なのではないかなという。そういうことはないということですから、ちょっとその辺も状況を、全体の事故の状況というのをわかればお聞かせほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"加害事故も同様に３件という形になっております。被害事故については、これは報告するという形にはなってございませんけれども、ほぼこの３件ぐらいの被害が出ているということです。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"相手を傷つけてしまうことの対策というのはさらに、今まで強化されていたにもかかわらず起きているということで、より徹底をお願いしたいと存じます。これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"藤原副委員長","kind":"質問","question":"１点お伺いしたいんですけれども、この３件の賠償額というのは、区が区のお金を使って払うんですよね。そうすると、これは損害保険とかで払うのではなくて、区が区の予算で払うわけですよね。","respondent":"山口品川清掃事務所長","answer":"私どものほうの車両につきましては、一応任意保険に加入しておりますので、保険からほとんどは補てんをされる、給付されるという。ただし、保険会社の契約の中で、これは免責３万円がありますので、３万円を差し引いた残りについて補てんをされる、こういう形になります。","id":"exchange-008"},{"speaker":"藤原副委員長","kind":"質問","question":"そうすると、例えばこの１６号だと賠償額が１１万２,９４６円ですよね。これから３万円引いた額が保険会社が払ってくれて、３万円は区が払うということか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"逆に３万円を超えて払っても、区の保険会社への支払いは３万円。今回のケースですと１万６,２０９円を品川区が保険会社のほうに後ほど免責後に払うという形になります。","id":"exchange-009"},{"speaker":"辻委員","kind":"質問","question":"それからもう一つは、１区当たり２億円から３６億円とかいうけれども、例えばこれは品川区だったらどうなるんですか。わかりますか。","respondent":"中山清掃リサイクル課長","answer":"この３区は入っておりますけれども、確かに発言の中でわかる部分も多々あるんですけれども、これは区名はわからない形で今進められております。","id":"exchange-010"},{"speaker":"石田副委員長","kind":"意見","question":"これにはどういう影響があるかということをちょっと。全体的にとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"自区内処理を前提とした地域処理を検討していくというふうに区長会下命を受けて今検討しているわけですけれども、じゃあ自区内処理とは何ぞやと。","id":"exchange-011"},{"speaker":"石田副委員長","kind":"意見","question":"自区内処理をどうとらえるかという話に変わってきているわけですけれども、清掃一部事務組合の解散ということ自体から含めて、もう今年で崩れる。そういう可能性というのはあるのかないのかということだけ一つ説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"これは今申し上げたような地域処理の検討の前提条件に一つ大きな検討する余地が出てきたというのはあるんですけれども、地域処理の検討ですけれども。","id":"exchange-012"},{"speaker":"石田副委員長","kind":"意見","question":"最後にします。今年１年の中でこの委員会の中でそれを勉強しようよということを、方向性というのは非常に大切な年だなと考えていますということだけとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"続きまして、(5)の自治会館（仮称）の建設計画","agenda":"続きまして、(5)の自治会館（仮称）の建設計画","exchanges":[{"speaker":"上山委員","kind":"質問","question":"ちょっと最初に１点お尋ねしたいんですが、１４６億６,５００万円ぐらいだとここに書いてありますが、何かそこら辺がよくわからない。もう一度ちょっとそこら辺の区とのかかわりみたいなのを説明をいただけますか尋ねました。","respondent":"古川総務課長","answer":"この団体がそのままここの入居予定に入ってありますけれども、既に土地の購入についてはこの協会のほうから出される、こういうふうになっております。ですから、区のほうは用地購入建設については持ち出しがない、こういう状況です。","id":"exchange-014"},{"speaker":"上山委員","kind":"質問","question":"その辺ちょっとお尋ねなんですが、平成１８年３月ですか、何かほかに具体的に少しこういう名前で挙がっているんでしょうか。ちょっとこの間の論議を私はよく知らないので申しわけないんですが、もしあれば、ちょっと教えていただけませんか尋ねました。","respondent":"古川総務課長","answer":"先ほど申し上げた平成１２年の基本的な実施計画が前提で実は動いておりまして、先ほど申し上げた基本計画は実際として昨年の４月。そして今回の実施設計ということで、収支計画、これはこれからの中で詰めていくというふうに伺っております。","id":"exchange-015"},{"speaker":"上山委員","kind":"意見","question":"ちょっと最後に１点だけ、国とかそれから東京都も、ほんとうにこういうものをつくってどうなのかなというのが率直な感想ですけれどもね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"要は費用をかける必要があったのかどうかという思いでこの入居状況を見ているんですが、その辺をまず１点、入居がこうだったということのご見解をまずお聞かせをほしいと求めました。","respondent":"古川総務課長","answer":"ＩＴ技術に対応できるような情報通信システムが可能な建物ということで、将来の高速大容量の通信にも対応できるように、二階フロアでの商業テナント。","id":"exchange-017"},{"speaker":"田中委員","kind":"質問","question":"ちょっとまたこの当委員会にかかわるところでお伺いしたいんですが、その１,５００人体制が現在どうで、教えていただけますか。","respondent":"中山清掃リサイクル課長","answer":"この１,５２３人のうち約１,１００人ほどが清掃工場で、この辺の業務はどういう地域処理が形成されるかによって変わってくる。全体の調整機能がどこまであるのかないのかというふうなことにもかかわってくるです。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"ですから、場合によっては３,５００m2ですから相当スペースがあるので、スペースはもう確保されていますから。その解散間際に半年、９カ月先に解散予定なのに、その辺のご見解をお聞かせをください。","respondent":"古川総務課長","answer":"会議室が５００m2ということで、この３,５００m2が一つの数字となって、今与えられている。この清掃一部事務組合を設置し、その２３区の意向がどこまで反映されるか、ここに尽きるのかなというふうに私のほうでは考えております。","id":"exchange-019"},{"speaker":"田中委員","kind":"質問","question":"言われている中で、区長会事務局が３５０m2で議長会の事務局が７７m2ということの、何かそうなったことの議論というのはあったのでしょうか。その点だけちょっと。","respondent":"古川総務課長","answer":"区長会事務局は一応想定で２５人、議長会事務局は１５人ですけれども、この平米をそれぞれが完全に切り分けてではない。有効な使い方が当然なされるだろうというふうに考えております。","id":"exchange-020"},{"speaker":"辻委員","kind":"質問","question":"今の関連でちょっとお伺いしたいんですが、２３区の清掃一部事務組合は今、四谷の国保連ビルに入っている。それはいつまでの契約なんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"年間賃貸料約３億円ぐらい払っております。これは基本的には単年度契約をしておりますから、毎年契約更新をしているものです。","id":"exchange-021"},{"speaker":"辻委員","kind":"質問・要望","question":"もう一つ確認ですが、この総工事費の１４６億円、宝くじと言いましたね。それをこれも同じような単年度みたいに分配してしまうやつは、要するに、このどういう形で１４６億円が出てくるようになっているのか尋ねました。","respondent":"古川総務課長","answer":"その基金が先ほど約６００億円ということで、いわゆる共同取得の扱い、これに対しては例外として基金の取り崩しというのは可能。それから、ここに掲げております総工事費がすべてこの協会のほうから協議会のほうに歳入として入ってくる、こういうことです。","id":"exchange-022"},{"speaker":"辻委員","kind":"提案","question":"だって、さっきの３億円で国保連ビルにそのままいればいいじゃないですか。その辺はどうなんか尋ねました。","respondent":"本間総務部長","answer":"向こう側の説明によりますと、年間に、要するに経費にして約８,０００万円ぐらい安くなりますと。説明を私どもは聞いているところでございまして、それから、一応そういう状況にあるということでひとつご理解のほどをよろしくお願いいたします。","id":"exchange-023"},{"speaker":"辻委員","kind":"質問","question":"そういうような商売を、少し事業部制で、どっちの事業部になるのかわかんないですけれども、金もうけを呼びかけたらどうですか。より今度は２３区のプラスになる金等に使えるようになるようにしたほうが、もう一遍それはちょっとお考えを、いかがなものか尋ねました。","respondent":"本間総務部長","answer":"先ほど来清掃リサイクル課長のほうも説明しましたとおり、長期的に見た場合、委員おっしゃるとおりのことが実際出てまいります。ただいまのご意見、しっかりと受けとめさせていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-024"},{"speaker":"藤原副委員長","kind":"質問","question":"今の辻委員と理事者の質疑を伺って、なぜ清掃一部事務組合は解散されて出ていくにもかかわらず入れるんだと、入るんだと。そういうことを言ってほしいというふうに菅家副委員長が言っていたにもかかわらず、やっぱりこうやって入っちゃうんか尋ねました。","respondent":"松本環境清掃事業部長","answer":"それで、特に清掃一部事務組合の難しい面は、２３区共同で運営をしております。だからその辺のことを含めて、今後私どもは動いてまいりたいというふうに思っております。","id":"exchange-025"},{"speaker":"藤原副委員長","kind":"質問","question":"ほんとうは今さら聞いてはいけない質問なのかもしれませんけれども、清掃一部事務組合というのは、解散するというふうになっていますよね。条文に出ていますけれども、改めて聞きますけれども、２３区の合意が得られなければ、解散はされないんですね。","respondent":"松本環境清掃事業部長","answer":"基本的に自治法上は２３区のすべての同意が必要でない限り規約改正ができない仕組みになってあります。そういう意味で、自治法上の制度ですので、大変働きかけをするにも２３区がやはり納得できる案をつくり上げなければできないだろうと思っています。","id":"exchange-026"},{"speaker":"藤原副委員長","kind":"質問","question":"構想の面で一つお伺いしたいんですけれども、これは屋上は屋上緑化されるんか尋ねました。","respondent":"古川総務課長","answer":"高さが９８メートルのこのところですので、ちょっと通常の屋上緑化は今のところ予定されていないところだと思います。屋上緑化という視点、これはこのビルの基本設計の中に入っている、こういうことです。","id":"exchange-027"},{"speaker":"石田副委員長","kind":"質問・要望","question":"これもちょっと教えていただきたいのと、この乗換階はどういう意味なのか、教えていただきたい。３点お伺いします。","respondent":"中山清掃リサイクル課長、古川総務課長","answer":"１点目の清掃一部事務組合の会議に関する部分でご説明申し上げます。その他も内部的な運営上の会というものは、これは公開するものではないのが主流になってあります。それから、一般職員の場合は東京都は６m2を自治会館では５m2ということで、一定のところでは平均的なものだというふうに伺っております。","id":"exchange-028"},{"speaker":"石田副委員長","kind":"質問","question":"１０、１１とか、非常に珍しいケースじゃないのかなとちょっと思っています。区長もその一員ですけれども、区長会で話すのも公開で、全部表に出していいという話でいいんか尋ねました。","respondent":"松本環境清掃事業部長、古川総務課長","answer":"これは一般の自治体の議会と同じ扱いです。委員会等を含めて公開になってあります。建設の入館人員、あるいはその入居予定団体、それと通常民間テナントのビルの場合の想定の両面からエレベーターのシミュレーションを行った。","id":"exchange-029"},{"speaker":"石田副委員長","kind":"質問・要望","question":"１点だけ要望しておきますけれども、盛り上がってくるのであれば、公開できるように働きかけをしていただきたい。各区の態度を明快にしていただけるように、要望していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-03","title":"次の案件ですが、次に、(6)の品川区廃棄物減量等推進審議会の中間まとめ（答申）","agenda":"次の案件ですが、次に、(6)の品川区廃棄物減量等推進審議会の中間まとめ（答申）","exchanges":[{"speaker":"川西委員","kind":"質問","question":"それから、最近の不燃ごみの量の推移はどのようですか。やっぱりそれではおさまらないんじゃないかという気がして、この答申にどういうふうなお考えか、それだけ。","respondent":"中山清掃リサイクル課長","answer":"それから、不燃ごみの推移ですけれども、２３区全体と品川区共通なんですが、微増です。３点目の事業者の役割の部分は、これは法改正の検討も含めた対応が必要だということで、いろんなチャンネルを使ってやっていきたいなと考えています。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"日本の全体の状況、自治体が回収している店頭回収も含めてですね、こういう状況でいいのかどうかというところをまずぜひとも伺いたいと思います。そういう点でのペットボトル、もう少し具体的に、製造者責任についてどういうふうに考えているのかという見解を伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"事業者の発生抑制等に向けてどのように区として改めて考えていくのかということですけれども、流通、かなり限定的なものになってきているです。あるいは他団体と連携をとってやっていく要請の中で、きちんとやっていくようにという指導はできるだけやっていきたいと考えています。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"テナント３,０００m2以上のというご説明をいただいたんですが、私がちょっと質問した趣旨は、対策をちょっと伺いたかったんです。ですから、このことについて、もう一度お願いいたします。","respondent":"中山清掃リサイクル課長","answer":"非常に悪質なケースは、時としては帰宅されているような時間を見合って指導するようなケースもありますが、なかなか毎回できない。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"地球環境を守るという、そういう点でのとらえ方を持っていただくということが大事ですから、ですから。変えたような大きなところでの働きかけが必要じゃないかなというふうに思ったものですから、その点についてのちょっとご意見を伺いたかったわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"嶋委員","kind":"質問・要望","question":"ですから切ったりしますけれども、果たしてこれは、ラミネート加工というのはどうしたらいいのでしょうか。教えてほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"ただ、検討する余地があるんじゃないかという発言はたしかあったかというふうに思っております。もう排ガス対策はかつてのゼロ２けたぐらい排ガスの混入率が下がるというような形になりますから、もしお悩みであれば、可燃ごみで可能だと思います。","id":"exchange-035"},{"speaker":"嶋委員","kind":"質問・要望","question":"一つ要望なんですけれども、ほんとうに私でもボール紙をばらにして出すときに、結構力が要るんですね。ですから、高齢者の方でも、そういうことをぜひ言ってほしいと求めましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"どうも民間のコンクリートメーカーというんでしょうか、ロードメーカーというんでしょうか、舗装業者というんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"その一つとして、こう集まったものがどうなっていくかを少しクイズ形式で考えてもらおうとか、目に生えるＰＲにかえていこうと努力しております。ただ、今のところぎりぎりですけれども市場では流れておりますから、仕組みとしては順調に全体としては順調です。","id":"exchange-037"},{"speaker":"本間委員","kind":"質問","question":"一つ。それから、その飲み物の空き缶あるいはペットボトル等のいわゆる受け皿となるような入れ物が設置されるべきというか、２点とりあえずお伺いします。","respondent":"中山清掃リサイクル課長","answer":"２点目の、自販機の脇の回収容器等につきましては、これは結論から言えば、義務づけはされておりません。ただ、自販機協会の申し合わせとして、できるだけ周りに回収箱を設置するように自立的に業界の中で申し合わせをしているというところです。","id":"exchange-038"},{"speaker":"本間委員","kind":"質問","question":"なぜかというと、カラスは減っておりませんですから、別のところに集中的に行くようになります。清掃事務所の方は、その辺は非常に難しい部分かもしれませんが、どういうふうに理解したらよろしいのか尋ねました。","respondent":"山口品川清掃事務所長","answer":"一応そこの集積所をお使いいただく世帯の方たちにご説明をして、お話をして、了解をとった上で集積所を設置してまいりました経過があります。そちらの方にお伺いをして、ご説明して、ご理解いただくような努力をしております。","id":"exchange-039"},{"speaker":"本間委員","kind":"質問","question":"結局この中身を見ている中で関連する問題だというふうに思ったものですから、大変すみません、時間をとりませんが、あともう１点だけ。そうしますと、掲示のきちっとないところは指定された集積所ではないという理解でよろしいのか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"今の集積所の設置された経過を考えていくと、当然事務所のほうで看板を設置し、だれが出されるかを極力分析するような形にしていかなければいけないかなというふうに思っております。","id":"exchange-040"}]},{"id":"topic-04","title":"続きまして、第７番目の品川区分別収集計画（平成１５年度～平成１９年度について）","agenda":"続きまして、第７番目の品川区分別収集計画（平成１５年度～平成１９年度について）","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"区民の皆さんがわかりやすい目標というんですか、１年間に約６億９,０００万円節約ができますという具体的な数字が示されているわけですよね。そういうのを積極的に活用してほしいという投げかけができるのかどうか。","respondent":"中山清掃リサイクル課長","answer":"それから３点目としてコストと。今ある手段をきちんとそれこそアピールできる内容も含めた効果的な広報を考えるというのが重要かなと考えていますのでよろしくお願いいたします。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから、こういう面も子どもに限らないで、私なんかもすごく勉強になっているので、ほんとうに活用をできるようにしていただきたい。ほんとうにできるだけ区民の皆さんが受け身ではなくて、自分もやってみる、参加型の啓発の仕方をぜひぜひ追求していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"パンフレットの周知だけだとやっぱり一定の限界があるし、と思うんです。だけれども、またそれについてどういう限界があるのかというようなことが、もしあったらお聞かせほしいと求めました。","respondent":"中山清掃リサイクル課長","answer":"最近学校から施設見学でストックヤードで分別している様子を見たいというふうな声も出てきて、この夏にも見学をするような動きが出てまいりました。したがって、それをまずとらえて、ある種効率的な中でそういった体験の機会も増やしていくような努力はしていきたいと思います。","id":"exchange-043"},{"speaker":"辻委員","kind":"質問","question":"中身をどうなんだという点は、三重の袋でなくてもいいじゃないかという意識をやっていくとすれば、だって出てくるじゃないですか。いかがか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"それから、もう少し具体的な認識、役割が区民の方にあるんだということを認識していただく表現というものは考えていく余地があるかと思いました。","id":"exchange-044"},{"speaker":"石田副委員長","kind":"意見","question":"そのときに、何かのキックバックみたいなものがあれば、子どもたちもそれだけのために集めて勉強するということもあるわけですね。なかなかそういう費用対効果をどうやってやっていくというところが見えないなと思うんだけれども、そこら辺の点をどういうふうに考えているのかなとの意見を述べました。","respondent":"金井環境課長","answer":"そういうことも含めて検討してまいりますので、そういった視点から、これから進めていきたいなというふうに思っております。そういった過程の中で、まだまだもう少し時間が必要かなというふうに思っておりますので、現状ではご理解のほどをいただきたいというふうに思います。","id":"exchange-045"},{"speaker":"石田副委員長","kind":"意見","question":"これを増やすにはどうしたらいいんだというふうに必ず何かお考えがあろうと思うんですね。数字だけが何か先行しているような気がしたので、ちょっとその辺のところがあれかなと思ったんですけれども、もしお考えがあればとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"これはもう１回施設整備から総工費かけて全部広げるとなると、これはほんとうにそれをやっていいのかどうかという検証がまだできていない。","id":"exchange-046"},{"speaker":"田中委員","kind":"意見","question":"今回にかかわらず、区に移管という平成１５年の改正により計画をつくったわけですが、また品川区としての展開をした計画というのをつくるのか。今回は新たな容器包装リサイクル法に基づいている計画で、どんどん追加されるような形での計画ですが、その辺の考え方を説明を求めました。","respondent":"中山清掃リサイクル課長","answer":"先ほど環境課長が申し上げた環境基本計画というものも、こういったものが当然この基本計画との整合がとれていなきゃいけないということはあります。いわゆる法に義務づけがあるなしにかかわらず、一定の統一性、整合性を図っていきたいと考えています。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"清掃事業は一体体系としてどうなっているのかというのが、整合性の問題もそうなんですけれども、ちょっとお伺いさせていただきました。ですから、そういう意味では、体系を見据えた上でのわかりやすい事業を進めていただきたいなと要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"藤原副委員長","kind":"質問","question":"一つだけお伺いしたいんですけれども、ステープラーの針とこの紙のでやっているのの差といいますか、何か根拠があるんか尋ねました。","respondent":"中山清掃リサイクル課長、土井委員長","answer":"５枚程度の厚さが、従来のステープラーといいますか、金具によるとじ込みになっているということはご了解いただきたいと思います。できるだけ針を使わない資料を私としては心がけていきたいと考えています。では、以上で本日予定いたしましたすべての案件が終了をいたしました。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63037,"voices":119}},{"id":"h14-20020704-14","meetingId":"h14-cm07","date":"2002年7月4日","dateIso":"2002-07-04","committee":"行財政改革特別委員会","time":"午前１０時０４分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"例えば、一つの仕事を３人でやるとか、現業ですから当然ありますね。それから、当然仕事の内容が機械化、省力化されていくことがあるはずですから、その考慮しつつ定数を考えているかということが一つ。","respondent":"桑村人事課長","answer":"ただ、地域での陳情対応ですとか、最低直営で何人いないと実際上そのような対応ができないのという発想を切り替えて定数を作ったものです。もちろん、ごみ等につきましても処理をするということになろうかと思います。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"十分カバーできるはずなんですけれども、そういう方向性といいましょうか、考え方はどうでしょうかということが一つ。それが果たしてどうなのかということを教えていただきたい。","respondent":"桑村人事課長","answer":"条件につきましてはこれからですけれども、十分検討に値すると考えています。作業の定数がなぜ陳情対応ですとか、これからの作業職の方につきましては、チームで地域についての対応というのを主力にしようと。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問・要望","question":"公園の具体的なトイレの清掃とか云々の民間はどうでしょうかということについてのお答えがありませんので、最後にお答えをほしいと求めました。これだけのマイナスがあったというほうが説得力があるんじゃないかという気がしますので、それを後で教えてくださいということを要望しておきます。","respondent":"桑村人事課長","answer":"先ほど公園の清掃については、委託の現状をお示ししましたけれども、今現在２１０カ所のうち８７カ所を委託を進めているものです。今後につきましても、所管課のほうにも書いてありますけれども、順次委託を拡大していくという方向になろうかと思ってあります。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ただ、再任用、再雇用の人数が増えている。再任用、再雇用を雇ったけれども、結果的に人件費が減ったことがわかる資料を後で教えてくださいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"定数に対しての現員ということで、それに対しての対比が出ていないというのは、ちょっと意識が違うのかなと思ってしまうんです。定数が２５名に対して現員が８５名、プラス６０名ということで、その辺のところは金額的に説明はできるんか尋ねました。","respondent":"桑村人事課長","answer":"私どものやったという数字自体がおかしかったということになろうかと思いますので、そういう発想でやっているものです。その意味で再雇用、再任用の方の賃金については一定ですので、人件費の節減効果というのはかなり大きいというふうに思ってあります。","id":"exchange-005"},{"speaker":"本多委員","kind":"確認","question":"１ページ目のその他のところで、平成１４年は定数１ということで、先ほど経理課の６０歳のメール係ということで、来年は定数が０になっていくということなんですが、０になってもやはり現員は変わらないということでいいんでしょうか、その確認だけお願いいたします。","respondent":"桑村人事課長","answer":"今のところ、定数も現員も０にするという予定で進めてあります。","id":"exchange-006"},{"speaker":"本多委員","kind":"意見","question":"どうしても民間の発想でいくと、やはり新卒の方をバランスよく採用していくというような、そういった発想の転換をお願いしておきたいと思いますとの意見を述べました。","respondent":"本間総務部長","answer":"現業職員に対する考え方ですが、今るる人事課長から説明したような状況もありますので、新規採用職員の現業職については採用しないという考え方です。","id":"exchange-007"},{"speaker":"金高委員","kind":"意見","question":"今後の方向として、残された６０名をほかに異動するというわけですけれども、移す場所が逆に過員になると思うんです。その部門が本当に現在過員なのかどうか、異動を検討するということですけれども、その辺はどういうふうに考えているかお聞かせ願いたいんですとの意見を述べました。","respondent":"桑村人事課長","answer":"そのときの異動等の考え方ですけれども、あるいは保育園でしたら学校のほうへ異動できないかという投げかけを進めてまいりました。その意味で、それ以上に一定の退職が見込める部分がありますので、そういったことも考慮しながら進めていきたいと考えています。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"例えば、例えば職員がやったときのコストと委託をしたときのコストを計算をして、その上で委託をしていくということなんでしょうか。高木の剪定もそうだと思いますけれども、この辺の考え方を聞かせてほしいと求めました。","respondent":"桑村人事課長","answer":"詳しい資料を今持ってございませんけれども、基本的に所管課で今まで同じような業務を委託する場合は、大体半分程度になるだろうと思ってあります。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"職員がやったときから見れば半分ぐらいになるのではないかと、総枠での話なんでしょうか、それとも清掃とか剪定とか個別の考え方なんか尋ねました。","respondent":"桑村人事課長","answer":"そういう意味では、総枠の考え方にならざるを得ないのかなと思っています。一定のサービス水準を維持するときに、民間の方にお願いしたらどのぐらいになるだろうかということで比較したものと考えています。","id":"exchange-010"},{"speaker":"原委員","kind":"質問","question":"２４名、２５名が適正かどうかというのは、果たしてそこで現業が賄えるかどうか。そことの対比からして、仕事そのものが十分補えているのかどうか危惧しているところですけれども、その辺はどうなんか尋ねました。","respondent":"桑村人事課長","answer":"検討がかかる部分があろうかと思いますけれども、ただ一つの考え方はこの方向で間違いないだろうと思ってあります。民間の方とのつなぎがうまくできるだろうかとか、工夫しながら進めていくということで、所管課と十分連携を取ってまいりたいと思います。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"これから年齢的なものもあるからというお話だけれども、民間委託が八十数名の中で可能な部署というか仕事というか可能性はあるんでしょうか。その辺の工夫についてお考えがあれば説明を求めました。","respondent":"本間総務部長","answer":"私どもが考えておりますのは、この縛りが解けた段階では、そういう方面への配置転換も積極的に進めていきたいと考えています。そういう方策を講じて一日でも早く過員を減らすべく、引き続いて努力をしていきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問・要望","question":"何点か確認で教えてほしいと求めました。おそらくいつまでにはどうするんだというようなお考えがあるやに受け取れるので、その辺の確認をと思いましてお尋ねをしているわけです。","respondent":"本間総務部長","answer":"先ほど来ご説明しているような退職まで、要するに過員が減っていけば、その分を委託に順次変えていくという考えです。まだこの場では申し上げられませんが、できるだけ早く実現したいと考えているということで、ひとつご理解のほどをお願いいたします。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"さっき現業職員の件で、特に質問ではないけれども要望という中で。その辺の考え方をもう１回説明を求めました。","respondent":"本間総務部長","answer":"このような過員がたくさん出ているような状況の中では、新規の採用は考えておりませんということで、退職不補充をかけてやっていきますと。いろいろなものを考えながら対応していきたいということで、今現在はそういう意味から言いましても、現業職の新規採用は考えていないです。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"もう１点確認をお願いしておきたいというか、残りは１８園ですから、すべて３７園調理業務代行委託になるんですという理解をしていいんですか。もう一つ、ここで聞いていいのかどうかわからないので、今回二葉幼稚園につぼみ保育園ですか、要するに３８番目の保育園ができる。","respondent":"桑村人事課長","answer":"９園と思っていますけれども、これはまた別途の検討等あるいは予算等を伴いますので、別途のことがあろうかと思います。それから、つぼみ保育園につきましては、調理代行の予定です。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"つぼみ保育園も入れて３８園で調理業務代行していくとなると、こういう場合の代行業者は区内の業者ですか、あるいは区外の業者ですか。こういう時期ですから、できれば区内業者に委託化していくというんですか、関連ということで教えてほしいと求めました。","respondent":"桑村人事課長","answer":"業者の住所ですけれども、ここに書いてあるところでは区内の業者はありませんので、それについては主管課のほうに十分伝えたいと思います。今後、増えていくときにどのような数の業者がやっているのかどうか、私も詳しいことは知りませんので、その程度にします。","id":"exchange-016"},{"speaker":"伊藤委員","kind":"質問","question":"庁内イントラネットができているわけですから、なぜできないのか。電子行政とか言われているわけですから、例えばＥメールで送って、そんなことは考えられないのでしょうかということを説明を求めました。","respondent":"桑村人事課長、市岡企画財政課長","answer":"それから、またＩＳＯの関係等もございまして進めているわけですけれども、今現在やっておりますメールの配送自体は委託にしています。仕分けについて１人の方にお願いをしているということで、そういった業務に従事しているものです。あくまで職員配置については区が自主的に決めるもので、財調の算定についての職員数というのは、一番標準的な区を想定してつくっているものです。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"事務系の定数とか現員も当然あるわけですから、どうしても作業というのはわかりやすいですね。パソコンが入ってきて、これは要望ですけれどもそういうところもどこかで教えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤田副委員長","kind":"質問","question":"平成１３年に組織改正をして、三つの土木出張所、二つの公園出張所を統合して、三つの土木事務所にしたということです。４人に分けたという内訳はどういう役割といいますか、どういうふうになっているのか、まずそれをお聞きしたいと思います。","respondent":"桑村人事課長","answer":"一つは緊急時の対応等に、１事務所１班だけではかなり厳しいんじゃないだろうかということが発想です。その意味で、２班８名程度は必要だろうというところで決めたものです。","id":"exchange-019"},{"speaker":"藤田副委員長","kind":"質問","question":"今後２１０カ所の公園といっても、広い公園はほとんどあるわけないわけです。委託もしましょうという時代の流れの中で、私が思っている考えについて、どうお考えになっているかお伺いしたいと思います。","respondent":"桑村人事課長、市岡企画財政課長","answer":"ただ委員がおっしゃったように、それを一つの集中でできないだろうかというのも一つの考え方だろうと思います。８名の方が一定のエリアを巡回しながら点検をし、あるいは民間の方につなぐというような作業をして… 例えば、事務所に統合するときも、これまで各土木事務所でやっていた設計とか工事の発注業務を、本庁に一本化をして一元的な仕事の仕方をする。","id":"exchange-020"},{"speaker":"藤田副委員長","kind":"質問・要望","question":"２２キロ平方しかないわけですから、毎日車でどんどん回っても１日回れば次の日は大体わかるわけです。陳情だとか要望についても、当然どこにいても受けられるわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"給食調理のほうでお聞きしたいんですけれども、４ページの改善した点の２で、その前段で「関心が薄かったが」と言っています。職員意識の判断の仕方というのを、ここに書かれている問題で教えていただければと思うんです。","respondent":"桑村人事課長","answer":"私も詳しいことがわかりませんので、聞いている範囲でお答え申し上げたいと思います。ここに書いてありますように、保育士の給食調理業務についての関心が非常に高くなったということが、保育課の中で集約されていると聞いてあります。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"例えば直営の保育園ですと、お互いに職員なわけです。当然のことながら、今まで職員同士のつながりが業種が違うことで薄かったのかと取れちゃうんですけれども、そこをお願いしたいと思いますとの意見を述べました。","respondent":"桑村人事課長","answer":"ここに書いてある以上のことは申し上げることはできませんけれども、例えば３人のチームで見れば、各園の中で相当話されているはずです。調理というものの重要性について喚起されたということが、保育課の中で集約していると取られているものです。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけ、「園児の喫食量が増加につながった」という、この辺は基準があるんですか。０歳児はどれぐらいだとか、１歳児はどれぐらいだとか、こういう基準があって増加したとかという部分あるんか尋ねました。","respondent":"古川総務課長","answer":"０歳児から５歳児まで幅広い年齢を預かっておりますので、各保育園でそれを勘案してプラスしたり、そういう形では実施しています。そういった部分で、その結果ですが保育士本来の能力がかなりこの部分で高まってきていると、このように私は理解しております。","id":"exchange-024"},{"speaker":"鶴委員","kind":"質問","question":"私も３月の予算特別委員会の段階で言及しようと思っていたんですが、Ａさんが言った、最近の組合のとらえ方というのはどうなんですか。私たちは前から考える余地はあるんじゃないかと見ているんですが、どういうふうにとらえていらっしゃるのか尋ねました。","respondent":"本間総務部長","answer":"まさに委員ご指摘のとおり同じ考えで私どもも実施しているわけでございまして、それは明確に伝えてあります。それはあえて受けしますが、我々は発言する場ではきちんとこちらの考え方は相手に申しているということは、ひとつご理解いただきたいと思います。","id":"exchange-025"},{"speaker":"鶴委員","kind":"意見","question":"ずっと時代を経ることに２５名の定数で現員は８５名、こういう点から見ますと、給食調理代行方式でいい方向に行っていると思うんです。いろんな非難する人をいるかもしれないけれども、しっかりとした考え方に立って、どういうふうにとらえていらっしゃるんでしょうとの意見を述べました。","respondent":"中尾根企画部長","answer":"学校給食の問題についても、そういう意味からしますと、いずれこの問題についてはきちんとした検討が必要になってくるという認識は持ってあります。教育全体での給食のあり方は十分検討していかなければならない課題だと、このように受け止めているということをご報告します。","id":"exchange-026"},{"speaker":"鶴委員","kind":"質問","question":"企画部から見たらどうですか、教育委員会はどういうところに位置しているの。あれは保育園部門でやっていることだから、私たちに関係のないことだというふうに教育委員会は思っていないと思うんですが、正しくはどうなんか尋ねました。","respondent":"中尾根企画部長","answer":"ただし、今後さらにどうあればいいのかという検討の時期には来ているんだろうと、少なくとも企画部門ではそのように受け止めてあります。","id":"exchange-027"},{"speaker":"鶴委員","kind":"質問・要望","question":"論議があったかと思うんですけれども、過員をどういうふうに減らしていくのかという計画は、ちゃんとできているんですか。いつまでは過員を認めていただきたいと、そういう展望はどうなっているんですか、計画というのは。","respondent":"本間総務部長","answer":"それに比しての退職予定者数を見ましても、ひとつご理解をいただきたいと思います。ただ、過員についてはできるだけ速やかに解消するという姿勢で臨んでおりますので、ひとつご理解のほどをよろしくお願いいたします。","id":"exchange-028"},{"speaker":"鶴委員","kind":"質問・要望","question":"あんまり多い過員なんて、いつまだでも解消するのですかということになるじゃないですか。区長を擁護しているとか、とんでもないことを言う連中がいるから、どういう考え方で対処していけばいいか尋ねました。","respondent":"本間総務部長","answer":"では、当面定数は６０名をプラスしたもので１００名近い定数で置いておきましょうと言った場合に、そういう姿勢だけは取りたくない。ご指摘のとおり多くの過員が出てありますが、今のいろいろなご指摘は肝に銘じておきますので、ひとつご理解のほどをよろしくお願いいたします。","id":"exchange-029"},{"speaker":"宮崎副委員長","kind":"確認","question":"何点か確認しておきたいんですけれども、説明がよくわからなかったんですけれども、喫食量というのはどういうふうにして出すんですか。何か食に関する教育ということだと思うんですけれども、具体的にどういう変化があったのか、ここのところをまずお聞きしたいと思います。","respondent":"桑村人事課長","answer":"私自身細かいことはよく知り得ておりませんので、喫食量というのは、０歳児が何グラムというのがあるんだろうと思います。園児への教育ということなんですけれども、給食を出すときに園児への働きかけというのが充実ができたということで、保育課で取りまとめたものです。","id":"exchange-030"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"喫食量の算定の仕方は、どういう計算をするのか、後でわかったら教えていただきたい。もう一つ、企画部のほうから教育委員会に対して学校給食の問題で問題提起をするということなんですか、そこのところを確認しておきたいと思うんです。","respondent":"中尾根企画部長","answer":"今日、行財政改革特別委員会でこのような話があったということは、きちんと責任を持ってお伝えしておくという範囲です。","id":"exchange-031"},{"speaker":"宮崎副委員長","kind":"質問","question":"その前の段階で、企画部長は私見ということでお述べになりました。そのことも含めて話すわけか尋ねました。","respondent":"中尾根企画部長","answer":"私見はあくまでも私見ですから、今後の流れの中で、私の私見が取り上げられるようなときが来れば、そういうことになりますが、報告と私自身が意見を持っていることと同時に混同して伝えるというわけではありませんので、きちんと分けて進めていきたいということです。","id":"exchange-032"},{"speaker":"宮崎副委員長","kind":"質問","question":"３番の年代別現員数の表で、作業Ｉのところで２０代が１名ということですと、遠からずこの２０代のところは０になっていくのかなと思うんです。ここのところはどういうふうにお考えなのか、どういう年齢構成が必要なのか、そこのところはどうか尋ねました。","respondent":"桑村人事課長","answer":"業務の見直しの中で過員がこれだけいる現状、また保育園等についてはさらに調理の代行を進めていくような状況の中で、共通しての認識です。効率性を持って、若い職員より仕事ができると判断していますので、その形で進めていきたいと思ってあります。","id":"exchange-033"},{"speaker":"宮崎副委員長","kind":"意見","question":"定数と現員との関係で過員が６０名いるわけなんですけれども、この体制でどういう仕事をやっているのかというのがよく見えないんですね。それによってどういう跳ね返りがあるのか、その辺の柔軟性というか、その辺のところはどういうふうにお考えなのか聞かせてほしいと求めました。","respondent":"桑村人事課長","answer":"その中で、こういう仕事について今後正規職員で対応するのが適切であろうという方向性を出したものです。それについては、それについて現員を合わせる努力をなるべく早くしたいというのが、今の気持ちです。","id":"exchange-034"},{"speaker":"宮崎副委員長","kind":"質問","question":"２４名になったらどの仕事をどういうふうにするのか、ここのところがわかるような資料をいただければ、ここのところをお願いしたいと思います。各事業部と人事課はどういう関係で、実際にどこが責任を持って決めるんだろうと、そこのところはどうか尋ねました。","respondent":"桑村人事課長","answer":"今回２５名につきましても、今後の作業職の定数については、これが適切だろうという判断をして行ったものです。内部的な意味での事業部との絡みですが、それと人事課のほうで協議をするという方向に切り替えていきたいということで考えているところです。","id":"exchange-035"},{"speaker":"宮崎副委員長","kind":"意見","question":"ここのところは区はどういう考えでやっているのかというのが疑問だったので聞いたんですけれども、やっぱり現場の仕事がどういうふうに進んでいくのかということをうまく取り入れていただくという方向で、わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5712#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":36689,"voices":81}},{"id":"h14-20020705-16","meetingId":"h14-cm07","date":"2002年7月5日","dateIso":"2002-07-05","committee":"街づくり特別委員会","time":"午前１０時０６分～午後０時３０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"ソニーが単独開発をやるというのは、これはこれで権利ですから否定するつもりはないんですけれども、最大の問題は中地区だと思うんです。全体の地権者と、その中で賛成の意向を示していない世帯というのはどれぐらいあるのか、あるいはないのかお尋ねします。","respondent":"南雲都市開発課長","answer":"零細な権利者の方への対応ですが、現在、開発者のほうにも零細権利者への配慮ということを区からも要望いたしているという状況です。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"こうした場合に、全体地区計画の網をかけて、私は乗らないというふうに言ったら、最終的にはどうなるんですか。そして、実際にここに入ってくるデベロッパーなり、参加組合員なりが、現状決まっていれば説明をしてほしいんです。","respondent":"南雲都市開発課長","answer":"先ほどの資料の３ページをお開きいただきたいんですけれども、組合の設立、完成も同じ時期ぐらいになるというふうに考えております。３点目につきましては、これについても現在の参加組合員についてもなるべく早く達成できるように進められているという状況です。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"得ていないんじゃないですか。オーバルコートだって何だってみんな借りているじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問","question":"１０年前は９８人だというふうに言っているんですけれども、８５人の権利者の内訳を知りたいんです。土地所有者、借地者、家屋の所有者、家屋を借りている方を説明を求めました。","respondent":"南雲都市開発課長","answer":"それから、８５人といいますのは、土地所有、借地の方でございまして、内訳としては、土地所有が２０名、借地の方が６５名です。居住している方としては概ね３００人程度ということで、日々変わっているということで、概ね３００人ぐらいです。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問","question":"１０年前は４４０人ということで、この変化というのをどういうふうに見ていったらいいんでしょうか。その１０年間の推移というのをどういうふうにお考えになっているか尋ねました。","respondent":"南雲都市開発課長","answer":"Ａ地区の延べ床面積のところでは１０分の５６ということになっておりまして、５６０％というふうになっております。ここは従前は準工業の３００％でありましたので、空地の面積、道路などの整備の内容を勘案して５６０％に上げていくというものです。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問","question":"この開発に期待を持っているとすれば、少なくとも踏みとどまってそこで生きていこうというふうに、普通は人間というのは考えるんじゃないですか。この増えた要因というのは何か尋ねました。","respondent":"南雲都市開発課長","answer":"本当に見込みですが、こういうものを勘案しまして、これまでよりも補助金の率としては上がっております。容積のアップば再開発地区計画の中で、空地を生み出すこと、公共施設を整備すること、そういう面を勘案して、それとの見合いで上げていくです。","id":"exchange-006"},{"speaker":"桜井委員","kind":"意見","question":"権利者の中で９割近くが賛同しているということの背景には、例えば６５人のうちフジタ関係で持っていらっしゃるのが５８名ということですね。そのことだけ指摘しておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"船波委員","kind":"質問","question":"南地区のところには、現在ある大崎在宅サービスセンターがくるのではないかと思いますけれども、この地区が業務棟になってしまったときには、介護支援センターはどうなるんか尋ねました。","respondent":"南雲都市開発課長","answer":"その部分には区の在宅支援センターも含めて、そういうような機能も入ることは可能な設計を今検討しておりますので、施設の計画としては入ることも可能な建築を検討しております。","id":"exchange-008"},{"speaker":"船波委員","kind":"意見","question":"入ることも可能なというのは、検討ということには、可能だから、そこに決める予定なのかどうか、その辺が大事だと思うんですけれどもとの意見を述べました。","respondent":"南雲都市開発課長、市岡企画財政課長","answer":"所管が違うということで、そういう表現になってしまったんですが、開発を行う考え方としては、低層部分に入るということを想定しているです。 ３ページのスケジュール表でいきますと、南地区で言いますと、平成１６年度の権利変換計画は中ごろに示しているところにあります。どういう形で、どういう内容で権利変換をするかというのは、これから検討をするです。","id":"exchange-009"},{"speaker":"北野委員","kind":"質問","question":"高度の第三種とありますけれども、外されたということは、どこまで高さ制限になっていくのかというところを伺いたいんです。可能というか、問題もあると思うんですけれども、外されたときに、どこまでの高さというのが可能になるのかというところをお伺いしたいんです。","respondent":"南雲都市開発課長","answer":"ただ、この地区は羽田空港の航空法で高さが１３０ｍから１４０ｍぐらい以上は建たないような制限がありますので、ここで実際のところは高さの上限は抑えられております。","id":"exchange-010"},{"speaker":"北野委員","kind":"質問","question":"１３０ｍから１４０ｍということですけれども、建物の階数としては、高さというものがありますけれども、概ね何階とかになるんですか。そういったときに、高さというところの制限は何階ぐらいになっているんか尋ねました。","respondent":"南雲都市開発課長","answer":"住宅の場合は１層の階高が小さいということで、階数としては多くなりますが、業務の場合はもう少し階数としては少なくなります。先ほどの航空法の１３０ｍから１４０ｍ、これが上限ということで、今後具体的な内容は決まってくるです。","id":"exchange-011"},{"speaker":"北野委員","kind":"意見","question":"景観ガイドラインをつくるということでもありますけれども、住むときのまちの景観というところではどうかなというのがあります。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その方でも今度の３３階建てのマンションの中で権利変換ができないという方は全くいないというふうに考えていいのかどうかということを一つお聞きし…お店もあると思うんですけれども、そういうお店の営業というところではどうなってしまうのかということについて教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"木造の住宅で借地ということで、今の権利変換の案としては、一番零細な方でも今と同じ面積を新しいビルで確保できるということを考えております。こういうところの中に営業を継続される方については入っていただくということで、現在個々の方と調整を行っているという状況です。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"借地で十数坪ということですけれども、借地の場合だと、２階建てとかというふうな形で建てられていますよね。自ずと床面積のほうが多い状況になっていると思うんですけれども、それとも住んでいる床の面積で変換になるのか、そこのところをお願いいたしますとの意見を述べました。","respondent":"南雲都市開発課長","answer":"権利変換では土地、建物の金額と、新しい床の金額で置き替えるんですけれども、今言っております同じ面積といいますのは、今お住まいの住宅の床面積と同じ面積は確保できるというのを基準に調整を進めているです。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５５億円の補助金というところで、これまでの制度で５５億円という根拠が、どういうことで補助金が出ているのかということについて教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"共同で使うもの、こういうものが必要になってきますので、こういう部分の躯体も含めて補助対象というふうになってきます。公園とか道路などを整備する場合にも、もろもろの施設の整備の費用についても補助の対象になります。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建物に関しての共同とか、エレベーター、階段、受水槽、そういうふうなところでの補助金というのは、今回の住宅棟に対して５５億円というふうな、そういう考え方なんか尋ねました。","respondent":"南雲都市開発課長","answer":"住宅と業務と全部合わせて、それぞれ共同施設については補助対象になります。補助の率としては住宅のほうが高くなりますが、全部の棟が入っておりまして、全部合わせてというふうになります。","id":"exchange-016"},{"speaker":"桜井委員","kind":"質問・要望","question":"もう一度教えていただきたいんですけれども、借りている方がどうなのかということを、復習の意味で教えてください。不動建設、この方々の権利内容というんでしょうか、今業務棟、賃貸住宅、分譲住宅と棟が三つありますね。","respondent":"南雲都市開発課長、岩野まちづくり事業部次長","answer":"それから、参加組合の予定者の権利ですが、大林組については６６０m2を所有しております。大林組と日本舗道の２社が参加組合の予定者ということでございまして… 大林組と日本舗道が参加組合員予定者ということでございまして、従後の保留床の概ね７割と３割を取得するというような形で検討をしています。","id":"exchange-017"},{"speaker":"桜井委員","kind":"確認","question":"ここで言うと何平米かもう一度確認したいのと、業務施設は５,５９６m2ですけれども、工業施設というのが入っていますよね。これもみんな大林組なのかどうか、そこの確認。","respondent":"南雲都市開発課長","answer":"この中で、１街区（Ａ－１地区）というのが業務棟と賃貸住宅でございまして、２街区（Ｂ地区）が分譲住宅です。保留床の金額のうち両者の取得する床が７割と３割の比率になるということで、一番北側のところですけれども、オフィス棟のほうが大林組です。","id":"exchange-018"},{"speaker":"桜井委員","kind":"確認","question":"もう一度確認です。３割のところですけれども、業務の大林組が７割、３割が日本舗道だという理解でいいのかどうかということをもう一度確認したいんです。","respondent":"南雲都市開発課長","answer":"これは保留床全体の総額のうち、それぞれが取得する部分の比率で言ったものです。これもまだ建物の施設もはっきりしておりませんので、金額も出てこないということで、今のところの想定で、そのくらいの比率で今後取得していくです。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"５１.３％は、延べ床に対する割合なんでしょうか、土地なのか、よくわからないので教えてほしいんです。それと、これらの工業関係施設は開発の中に取り込む余地があるのかどうなのか説明を求めました。","respondent":"南雲都市開発課長","answer":"全体で３９で、工業施設２０棟で５０％だということで、これは細かい倉庫のようなものも含まれておりまして、こういう数字になっております。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"１件のみが継続するかどうか検討をしているんだけれども、それは開発地域の中では受け皿は設けるんですか、設けないんですか。ヒートアイランドの面から見た場合にどうかという点でお尋ねしたいんですが、これが建った後の昼間人口、夜間人口の予測はどうなんか尋ねました。","respondent":"南雲都市開発課長","answer":"操業を継続される場合には継続可能な代替地をあっ旋するということで、現在この経営者の方と今後のことについて協議を行っているという段階です。","id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"ものづくりは衰退の一途で、最後の１件も代替地というから、ここから出ていかざるを得ない。今、昼間人口と夜間人口の、建った後の見通しはあったんだけれども、現況はどうなのかというのを聞いたんですが、答弁がなかったんですとの意見を述べました。","respondent":"南雲都市開発課長","answer":"これは確認をいたします。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"こういった開発がされるがために便利になったからとか、そういった理由で土地の値段というのは上がってきているものなんでしょうか。そういった変化というのがもし分かれば知りたいんです。","respondent":"南雲都市開発課長","answer":"例えばオーバルコートというのが去年できまして、それに伴って、幹線道路まで整備しました。そうしますと、実際これまでよりも広い道路に面するようになったということで、地価としては上がることが考えられるです。","id":"exchange-023"},{"speaker":"船波委員","kind":"質問","question":"今具体的に出たオーバルコートのそばというのは今後上がることは考えられるというお答えだったと思いますけれども、オーバルコートのそば以外のところで、今までどういうふうな変化をしてきたかというような、数年の状況の変化というのは調査しているんか尋ねました。","respondent":"南雲都市開発課長","answer":"地区更新計画というのが定まっておりまして、また具体的な民間業者の取引価格というのはなかなか知ることが難しいということがあります。ただ、そういう点では従来の道路が細くて密集していた頃に比べますと、取引の金額としてはある程度上がっているということも考えております。","id":"exchange-024"},{"speaker":"沢田委員","kind":"提案","question":"現状との関係ではどうなのかということを教えてほしい。これプラス従来の補助制度ということなんか尋ねました。","respondent":"南雲都市開発課長","answer":"都市計画の場合にははっきりした数字はないんですけれども、概ね９割程度の合意が必要というようなことが今までは行われておりました。これはこれでありますので、法定再開発で開発を行う場合には、これまでと同様の補助金が再開発組合などに出されるです。","id":"exchange-025"},{"speaker":"沢田委員","kind":"意見","question":"これは都市計画ですけれども、先ほどの中地区の場合に、全員合意を目指すと言っているけれども、実態的には３分の２あればいいんだということに、地区計画は地区計画て決まってきますけれども、そういう流れを促進しはしないかということが一つ心配ですとの意見を述べました。","respondent":"南雲都市開発課長","answer":"３分の２といいますのは、３分の２が集まっていれば、そう大きく変わることはないというふうに考えております。","id":"exchange-026"},{"speaker":"北野委員","kind":"質問","question":"そうしたときには、かかった網かけの部分というのはどうなってしまうんでしょうか。こちらの緊急性のほうでの網かけの部分との整合性というんですか、その後どういう、再開発だけの部分で残っていくわけか尋ねました。","respondent":"南雲都市開発課長","answer":"短期間に開発を進めて、都市再生特別地区の都市計画の整備につきましては１０年間、現在あります都市計画が適用されるようになるです。","id":"exchange-027"},{"speaker":"桜井委員","kind":"質問","question":"大崎の関係で言うと、６０haが再生特別措置法の対象になったというふうに言ったんでしょうか、なるというふうに言ったんでしょうか。そういう視野に入れての都市再生法の申請というんでしょうか、決定に至ったのか、そのところを聞きたいんです。","respondent":"南雲都市開発課長","answer":"６月１日の街づくり特別委員会では図面をお示しをしているんですが、その範囲が６０haです。こういう新しい制度でやればより良いまちになるというような考え方をまとめた資料などもつくりまして、それから、今回の指定を受けたです。","id":"exchange-028"},{"speaker":"桜井委員","kind":"確認","question":"ということは、この流れとしては地方自治体が案を申し出するわけですから、品川区の中にこういう設置をしたんでしょうか、するんでしょうか。とすれば、どこが責任を持ってやるんか尋ねました。","respondent":"南雲都市開発課長","answer":"都市再生緊急整備協議会というものを設置するということで、はっきりしておりませんが、そういう協議会で協議していくという方向であるです。","id":"exchange-029"},{"speaker":"桜井委員","kind":"確認","question":"そういう意味で、区長の判断で都のほうに、いいよというふうに言ったという、そういう理解でいいのかどうか、そこだけちょっと確認したいんです。そしてこの協議会そのものがどういう性格を持つのかわかりませんけれども、大変大きな問題を含んでいるというふうに、これは指摘しておきたいんです。","respondent":"南雲都市開発課長","answer":"これは、地方公共団体の意見を聞いて都市再生本部が定めるということになっておりまして、都市再生本部から区長あてに意見照会がきております。それに対して区として異論がないということで、意思決定を行いまして、その返答をしているです。","id":"exchange-030"},{"speaker":"北野委員","kind":"提案","question":"指定があれば、有効であるというところで、またどこの地区にもこれはできるようなことを提案という可能性はあるんですか。ちょっと先のことで答えにくいかと思うんですが、お伺いいたしますとの意見を述べました。","respondent":"南雲都市開発課長","answer":"今回の指定はこれだけということではなくて、第１弾ということで、今後第２弾、第３弾、追加で指定されていくというふうに考えます。区としても、この制度の適用が効果的であるというところがあれば、今後は追加の指定を働きかけていくというふうになると思います。","id":"exchange-031"},{"speaker":"北野委員","kind":"質問・要望","question":"この制度というのはいろいろ問題があるということは、桜井委員からも指摘していましたので、土地の有効というところもありますけれども、そこに住む品川区の住民ということを第一に考えていただきたいということは、意見としてお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"船波委員","kind":"質問","question":"この中では、幾つか仮称であるものがありますけれども、それについては内容がどういうものであるかというのは、審議会でまとめたものでもあるんか尋ねました。","respondent":"伊佐都市計画課長","answer":"ですから、今後の動向を注視しながら、新しい制度を今後どういう形で適用していくかというのは今後検討するという流れになってあります。地域の合意形成のもとに進めていくための制度、それをまた行政が支援してくれるような制度を構築したいというのがこの趣旨です。","id":"exchange-033"},{"speaker":"船波委員","kind":"質問","question":"ご説明でわからないところをお伺いしたいんですけれども、４ページの一番上の行ですけれども、どういうふうに関係するのか。","respondent":"伊佐都市計画課長","answer":"こういうケースは、再開発地区計画などでボーナスを与える際に環境配慮の住宅等、建築物を誘導していこうという趣旨です。","id":"exchange-034"},{"speaker":"船波委員","kind":"質問","question":"もう一点だけ、読んだだけでは全然わからないところがあるもので。今お伺いしたところの下の５の３の二つ目の点のところですけれども、建築基準法と密接に影響することが、どう関連しているのか。","respondent":"伊佐都市計画課長","answer":"これはもちろん幾つかありますが、地区計画を担保することによって、建て替えの支障になっているものを緩和する。今回戸越一丁目地区などで導入した地区計画もこれのちょっと先取りしたような制度というふうになっております。","id":"exchange-035"},{"speaker":"三上委員","kind":"質問","question":"この概要版というのは、きちっとした答申というのが出されているはずです。都市計画を将来に対してどうするのかということが皆さんが関心のあるところですから、次にまた質疑するような機会を設けるほうが、どうか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから、確かめておきたいのは、５ページの最後の枠組みの中で、都市計画審議会の中で特別の諮問が出たから、こういうことをしたんですねと。簡単でいいですから、そのことを教えてほしいのと、こういう種類のことは都市計画審議会が折に触れてやるのかどうかを説明を求めました。","respondent":"伊佐都市計画課長","answer":"前回も用途地域の見直しのときには、土地利用の基本方針が定めらられております。そういった形で都市計画審議会の審議というのは、概ね用途地域の見直しのタイミングで、土地利用の方針が考えられていくというものです。","id":"exchange-037"},{"speaker":"沢田委員","kind":"提案","question":"都市計画を民間事業者が提案できて、３分の２でごりごりやっていく。３分の２でもって提案すれば、まちづくり問題に対して物凄い規制緩和で、これは非常に重要な問題がこの中にはらんでいるというふうに私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、品川区の土地の有り様がどういうふうに変わってくるのか、そういうものを資料として提供してほしいと求めました。後段は要望です。","respondent":"伊佐都市計画課長","answer":"概ね１年かけて区のほうで原案をつくり、住民の方に説明し、都に提出する。先ほどの環状７号線の内側の中高層密度という話も、これは実は前回の土地利用方針でも、そういった基本的な密度構成の考え方は踏襲されてあります。","id":"exchange-039"},{"speaker":"桜井委員","kind":"意見","question":"確かに大崎については、さらにそれを加えていますから、より高度化になっていくから、それは区の意向としてはマッチしているかもしれない。だから、もう少しそこは今度の委員会のときでも私どもも具体的に意見を出して審議したいなと思いますとの意見を述べました。","respondent":"山路委員長","answer":"ご意見がいろいろ出ましたが、三上委員の、答申の本文を提出していただいて議論したいという、これは報告できますよね。今日は概要ということで意見が出ましたので、次回におきまして正副委員長で検討して、対応していきたいと思います。","id":"exchange-040"},{"speaker":"須藤副委員長","kind":"質問","question":"ここに人口フレームと書いてあって、２０１０年でピーク、その後減少というのが、品川区として考えた場合には、この人口フレームの考え方は、品川区で考えている第三次長期基本計画と流れ方はどうか尋ねました。","respondent":"中尾根企画部長","answer":"それは増減の方向を示す部分があるので、時期的にずれているというのが基本的に違っております。次回、もしそういうことで本格的にやるんでしたら、そのときに品川区での今後の人口の捉え方を同時にやらせていただきたいと思います。","id":"exchange-041"},{"speaker":"須藤副委員長","kind":"意見","question":"桜井委員からもいろいろまた出てくるけれども、こんなベースで云々という話でなくなって、ある程度参考という形だろうというようなもので見ていかないと、ここ全部がというような考え方は、さっき言った。","respondent":"南雲都市開発課長","answer":"先ほどの東口第３地区の昼間人口、夜間人口ですが、夜間人口は１５０人、昼間人口が概ね２５０人という状況です。","id":"exchange-042"},{"speaker":"沢田委員","kind":"意見","question":"放出性エネルギーがどうなるのか、ヒートアイランド現象の、環境という点からしてどうなのかというまちづくりを聞きたかったんです。今日は時間がないので、これで結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6236#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":40185,"voices":108}},{"id":"h14-20020723-6","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"区民委員会","time":"午後１時１０分～午後２時３３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"そうすると、それに各議員が出動するとか、そういうことがあるんでしょうか。どのように対応を考えているんか尋ねました。","respondent":"久保田防災課長","answer":"地区防災計画上は、特に議員としての特別な活動という形での取り込んでいるというような考え方はありません。したがいまして、地域の一員として、それぞれの会場のほうに参加していただければと、こういうふうに考えております。","id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"７号、床上浸水２件ですか、それはどの辺になるんでしょうか。その原因はどんなものか尋ねました。","respondent":"久保田防災課長","answer":"その影響で、この床上浸水が２件出たです。これは下水道局のほうが対策に当たりまして、その日のうちにその盛り上がった部分については対応しているというような状況でございました。","id":"exchange-002"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、満潮ではなかったけれども、局地的にどっと降ったので、下水がはけなかったということに対することか尋ねました。","respondent":"久保田防災課長","answer":"水自体ははけたんですが、要するに空気の圧縮によって下水のマンホールが上がると。どうしてもそういうような状況が何個か出てくるような状況なんですけれども、今回もそれに当たったです。","id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"あの大雨のときに５チャンネルで流れるので、目黒川の警戒態勢がどうなっているのかというのがわかるので、無線が大雨のときには聞きにくい。その辺は前にもそれぞれ個別に点検を入れて、改善するところは改善するというような話があったと思うんですけれども、その辺はどんなぐあいか尋ねました。","respondent":"久保田防災課長","answer":"それから町会によっては町会会館に設置しているところもありますけれども、そういう形で聞き取っていただくというふうになっております。","id":"exchange-004"},{"speaker":"本田委員","kind":"意見","question":"個別の場所は、今ここでは申し上げませんけれども、そういうところがありますので、一般の方は大雨の中で何か言っているんだけれども聞こえないと。どういうことなんだろうというようなことがありますので、十分その辺は調整をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういうご努力は本当に評価できると思うんですけれども、この定員というのはどういう前提といいますか、希望者から実際に受けられるという方を選ぶというのは抽せんか何かで選ぶということなんか尋ねました。","respondent":"市川産業振興課長","answer":"それで、決め方については、決定方法については、コンピュータを使った抽せん方法でやってあります。昨年申し込んで、残念ながら昨年落ちた子については優先的に受講をさせるような、そういう仕組みをとってあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうところでは、ぜひこの希望者の方が全員受けられるような形での定員を増やしていただくということは現実問題としてご検討いただけないかと思うんですが、その点ではどうか尋ねました。","respondent":"市川産業振興課長","answer":"私どもも気持ちとしてはそういう気持ちを持ってあります。それらの希望にかなった方法等を考えておりますので、今後ともそういう気持ちに沿って進めさせていただきたいというふうに考えてあります。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問","question":"何らかの形で通年でこういうようなものづくりに興味を示されるような考え方というものもやっぱりやっていってもらいたいなという気持ちはあるんです…科学部というのがあるかどうかわかりませんけれども、こういうのはどうだという可能性がないのか、そこらあたりについて伺います。","respondent":"市川産業振興課長","answer":"三年、品川区出身の中学生、品川区の中学を出身して都立高専に入っていく子が数が現実増えてあります。今ご提案のあったような何か連携事業、共催事業ができるかできないか、都立高専のスタッフのほうとちょっと検討させていただきたいと思います。","id":"exchange-008"},{"speaker":"三上委員","kind":"意見","question":"一番問題になるのはやはりお金の部分ということもあるので、そこらあたり、やはり多少奮発してでも考えていってあげてほしいなと思います。そういうことを踏まえた上での品川区の誠意ある取り組みを考えてもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"オプション設定で親子工場見学ツアーが実施されて、９４組ということですが、これは今学校のほうで授業での工場見学というのは行っているんですか。この前お会いした方たちの中で、やはり工場見学がなくなっているような話をちょっと聞いていたので、そこら辺はどうかということで。","respondent":"市川産業振興課長","answer":"地域のいろいろな事業所に子どもたちが、商店街から一般の企業から町工場から、いろんな事業所に子どもたちが入っていってあります。その中に製造業の事業所も入っているようなことを聞いてあります。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"町のことを学ぶ授業やなんかで、確かに工場に行くというのがあったかというふうに記憶しているんですけれども、この９４組というのとロボット講座のほうというのは、割合同じような方の申し込みになっているんか尋ねました。","respondent":"市川産業振興課長","answer":"この９４組の大半の方はロボット講座の受講希望の方だったんですが、このうちの十四、五組については、ロボット講座は落ちても工場見学だけは行きたいという申し込みがございました。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この見学ツアーは、実施プランを練り直しているという、団体コースを。できる限り皆さんできればなと対応をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"当然、その後のごみとかという問題は主催者側が全部整理してやるのか、極端な話、床だってかなり汚れる、ごみの残りとか、点検関係はどうなるのか尋ねました。","respondent":"上山区民生活事業部副参事","answer":"大ホールですと１,０００近い客席数になりますので、お弁当になりますと、かなりのごみの量になります。認めている部分につきましても、そういう形でご利用いただいておりましたので、ごみについては原則お持ち帰りいただくというふうに考えております。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問","question":"今、町会の回覧というふうにおっしゃったんですけれども、要するに個人の方にはこの１枚ずつ手元に残るという形のものとしては渡さなかったんか尋ねました。","respondent":"冨田戸籍住民課長","answer":"これは町会回覧用のチラシということでお願いすることにしています。コード通知という形で郵便はがきで８月上旬にお送りする予定ですけれども、それをフォローするような形で回覧用にチラシを作成したものです。","id":"exchange-014"},{"speaker":"三上委員","kind":"質問","question":"せっかくですから、だから回覧にしたって、１枚ずつとってくださいと。品川区はきっちりやりますということを、それをお知らせするのであれば、なぜそういうような形で私はできないのかなと思うんですよ。","respondent":"太川区民生活事業部長","answer":"課長のほうでちょっと説明をさせていただきましたけれども、各個人、少なくとも世帯あてというのも一つのやり方だというふうに考えております。全戸に、そういう組み合わせの中でご理解いただければというふうに考えてありますので、よろしくお願いしたいと思います。","id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"そういう人たちは目を通さずに終わる可能性というのは何％あるんですか。それはだからどこらあたりで何％ぐらい見ているんか尋ねました。","respondent":"太川区民生活事業部長","answer":"たしか広報のほうで、世論調査等で広報紙をどのくらい見ていますかという部分では、たしか九十数％の方が広報紙のほうはご覧になっているというふうに判断しています。","id":"exchange-016"},{"speaker":"三上委員","kind":"意見","question":"それで、現実に私のところなんですが、この中で１週間ぐらいの間に私のマンションの中だって、会長が回覧回したんですよ。どうせやるなら、うるさくまたうるさく、ああうるさいなというお言葉をちょうだいしなくなるんじゃないかなと思うんですけれどもとの意見を述べました。","respondent":"太川区民生活事業部長","answer":"広報紙ということで考えてありますので、それでこちらの回覧と先ほど申しましたような形で周知していただければというふうに考えてありますので、ご理解のほどをよろしくお願いしたいと思います。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは回覧で回すということですけれども、回覧板の回らないアパートだとか、マンションとかというのも結構あるんじゃないかと思うんですけれども、そういうところというのは、どれぐらいの世帯、回覧板の回らないところがあるというのは把握されているんか尋ねました。","respondent":"長田地域活動課長","answer":"断られれば、もうそれで結構ですという形で私どものほうではお願いをしています。ただ、その数がどのくらいあるかという話になると、これは膨大な調査になりますので、数についてはちょっと把握してございません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"街を歩いても、この住基ネットが今になってすごくいろんな方からどうなるのというような感じ、いろいろな声が寄せられるんですよね。そういうふうなところからすると、やっぱりこういうお知らせというふうなものに関しては、そういうところに関していかがか尋ねました。","respondent":"冨田戸籍住民課長","answer":"区のほうにおきましても、先ほど来申し上げているとおり、広報しながわあるいはケーブルテレビ等を通じてやる予定です。一応考え得るもの、今申し上げたような状況ですので、ご理解いただきたいと考えています。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"不安があるというふうに答えている方が８５％だったですか、８６％、そういうふうな答えがされているんですよね。実際に行われるというふうなところでは、住民合意ということに関しては、区としてはどう考えられているんか尋ねました。","respondent":"冨田戸籍住民課長","answer":"今日まで３年経過しているわけですけれども、その間いろいろシステム上の問題とか、制度上の問題だとか、いろいろ検討してきております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"では、品川区としては、今回の住基ネットの始動に関しては、さまざまいろいろマスコミでは問題が指摘されているけれども、そういうことに対しては、特に問題はなく推進できるという、推進していくべきだという、そういうふうな立場だというふうなことか尋ねました。","respondent":"太川区民生活事業部長","answer":"それから運用面等につきましては十分対応できる、この法令に従いまして、準備を着々と進めてスタートしていきたいというふうに考えてあります。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"もう一つお聞きしたいんですけれども、その実際に説明をどういうふうにされたのか、ちょっと聞かせてください。","respondent":"太川区民生活事業部長","answer":"そういう形で私どものほうからこの制度の説明、それと８月の施行等につきまして、またご意見もちょうだいしてまいりたいというふうに考えてあります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ説明についてはできる限りやってほしいと求めましたし、この中に示していただけたらなというふうに思います。それと、そういう広い方を対象にするような説明会をぜひ開いていただけたらと思うんですが、その辺のところについてはちょっと。","respondent":"太川区民生活事業部長","answer":"いろんな具体的な形での説明会というのは現在のところは考えてございませんが、やはり広報広聴課の中にもそういうシステムがありますので、その辺との兼ね合いの部分でちょっと検討してみたいと考えています。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"福島県の矢祭町というんでしょうか、実際問題懸念されるというふうな、そういうふうな状況というのがあるんだと思うんですね。そういうところについては十分検討いただいて、必要なときには国に対しても物を言っていくというふうな姿勢でぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"本多副委員長","kind":"質問・要望","question":"２３区共通の要望事項を国と都あてに作成をしていくということなんですが、都への要望をつくりまして、１１月に提出という予定になっております。それで、この辺の要望事項については、また品川区の区民委員会としてもそういった意見を出し合ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問","question":"そんなもんですかね。テレビなんかでもやるから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこら辺はどういう組み合わせなのか。だから、当然中に入っていて、ここまで行って、中に入ってくるかなということでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"最終的に次回決めるということですから、それは委員長のほうに申し出ていただくということでいいんじゃないでしょうか。その後から項目的に最大な項目とかというような、これはやっぱり正副でちょっと検討していただいて、まとめていかれるなり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"三上委員","kind":"質問","question":"状況によっては、現地をよく見させてもらうという考え方のもとでの一つの方向性というようなものを考えていただければいいんじゃないかと思います。ただお話だけ伺うということがあるんじゃなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、市役所の方じゃなかったんです。参考になったとかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"うちは戸越銀座の銀六ですから、実際に年中来るんですよ。我々が行くのも本当によくしなくちゃなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その中で向こうで話を聞くということをやっぱりペーパーベースだけではなくて。見るというような形をぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2336#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":24405,"voices":106}},{"id":"h14-20020723-7","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"厚生委員会","time":"午後１時０８分～午後３時１９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件整理しています。","topics":[{"id":"topic-01","title":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","agenda":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"聞かせていただきたいんですが、公害健康被害補償法と、この間の動きをもうちょっと詳しく教えてほしいと求めました。こっちのほうは逆に増えているようなことを聞くんですけれども、この動きが分かったら、ここ何年間かの数字を教えてほしいと求めました。","respondent":"田中健康課長","answer":"昭和５０年から申請を受け付けたという、新しい事業という形でスタートしてございまして、最初の年は４３人申請がございました。それが４年前の数字ですと１,２８３人、本年度１,３８０人というところまで、数字的には推移しております。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"２年前、５年間ぐらいとか、そこら辺が分かればと思うんです。減ったり、この動きというのがどういうふうになっているかというのが、そこのところを聞いているんですとの意見を述べました。","respondent":"田中健康課長","answer":"次が１０歳から１４歳で４４４名、次が０歳から４歳で１８９名、１５歳以上が７９名です。発症時が３歳とか４歳ということになりますので、５歳から９歳がそういう形での医療費の公費助成を受けているというふうに考えられるかと思います。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"都の制度は１８歳未満なものですから、子どものところが集中するというか、数的にはそういうふうになるのは当然だと思うんです。今ご説明があった年度との関係で、公害健康被害補償法のほうは患者数がどういうふうに変わっているかというのは分かりますか。","respondent":"田中健康課長","answer":"認定の方の推移ですが、平成１０年度末で１,３２８名、平成１１年度末で１,３０２名、平成１２年度末で１,１６６名、平成１３年度末で１,１２６名という数字です。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"意見","question":"私が想像するには、減っている原因はそういうところかどうかという認識が何かあれば聞かせてほしいと求めました。ＳＯ２だと思うんですけれども、そこら辺のところが分かりましたら、お願いしたいと思いますとの意見を述べました。","respondent":"田中健康課長","answer":"死亡の方は、平成１０年度が２１名、平成１１年度が２９名、平成１２年度が１４名という数字を把握しています。ここのところの推移を表でいただいておりますが、平成３年からの１０年間の統計で見ますと、ほぼ横ばいという形というふうに聞いてあります。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"意見","question":"中原口が０.０７９ｐｐｍ、０.０７９ｐｐｍ、あるいは０.０７２ｐｐｍというのは全都的にもかなり高い数値かなというふうに思うんです。先ほど基準を若干超えているというふうなご説明だったんですけれども、ここら辺はどういうふうな認識を持っておられるのかとの意見を述べました。","respondent":"田中健康課長","answer":"申し訳ありませんが、認識という点では、こちらは若干超えているんだというふうな表現を聞いてあります。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"一つお伺いしたいのは、大気汚染と、この病気との関係を行政のほうはどういうふうな認識を持っておられるのか。一つは東京都の認識がどういうふうになっているのか、区のほうではどういうふうに認識をされているのか、そこのところはどうか尋ねました。","respondent":"田中健康課長","answer":"それの対策につきまして、特別区長会のほうでも国・都への要望をということで進めてあります。大気汚染に基づく公害について、行政側としましては、対策をきちっと講じてほしいという旨の国・都への要望は上げているところです。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"今のは区のほうの認識ですよね。国・都、いわゆる行政側のところはどういうふうなところかというのが分かったらお願いいたしますとの意見を述べました。","respondent":"田中健康課長","answer":"自動車公害につきましては、あるいは新しい経済的手法としてのロードプライシングの導入というような形を現在進めているというふうに聞いてあります。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"それに対して、今度は東京でも裁判があるんだけれども、どうだという質問に対して答えたのが最初だったかなというふうに思うんです。この間の名古屋南部等、司法の判断の流れがどういうふうな感じできているのかというのは、どんなご認識か尋ねました。","respondent":"田中健康課長","answer":"基本的には平成１２年１月に尼崎公害訴訟の神戸地裁の判決が出たのが、因果関係が認められた初めての部分かなというふうに思ってあります。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"意見","question":"ところが、その後の研究成果といいますか、そのところはどういうふうに捉えておりますか。その後の医学的な研究等が当然あったかと思うんですけれども、そこら辺はどういうふうに認識されておりますかとの意見を述べました。","respondent":"田中健康課長","answer":"あくまで裁判の部分というのは、司法のほうが判断した内容でございまして、局所的な部分の因果関係というふうに私どもは受け止めてあります。今のところ、国も、私どものほうとしても認識していないというのが一つの問題かと思います。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問・要望","question":"東京都、あるいは品川区長も入った区長会が因果関係があるんだという認識のもとに要望したり、行政を進めているわけです。東京都および品川区も含めた、そういうところとの矛盾もあるんだというふうに思うんですけれども、そこら辺のところはどうか尋ねました。","respondent":"田中健康課長","answer":"国の先ほどの答申の結果を覆すようなところまでの論理構成、あるいは要望は、今のところ東京都特別区のほうではしていないという状況かというふうに私どもは受け止めてあります。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問","question":"もっと聞きたいのもあるんですけれども、意見で、扱いも含めたのでよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"金高委員","kind":"質問","question":"２点ばかりお聞きしたいんですけれども、それ以後認定されていないけれども、実際に大気汚染によるとみられる方々が発病した数があるのかどうか。この請願が出たのが平成１３年ですから、実際には平成１２年だろうと思いますけれども、分かっている範囲でお示し願いたいんです。","respondent":"田中健康課長","answer":"それから、先ほどもご紹介申し上げましたが、浮遊粒子状物質等の減少のためのいろいろな規制を条例の中に盛り込んで実施をしようです。２０台以上の駐車場の設置者にはアイドリングストップのための看板設置の義務ですとか、いろいろと策を講じているというふうに認識しています。","id":"exchange-012"},{"speaker":"金高委員","kind":"質問・要望","question":"救済措置を求めるというふうになっておりますけれども、内容的には、公害というものはもっと先々に通じてくるのではないかという気がいたします。ただ、一つだけ言えるのは、各自治体において大きく取り組んでおるということだけは、今までの説明で十分理解できたつもりでおります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"１番目の、どのくらいの費用負担になるのか、１番目についてはお考えを教えていただきたい。そういうこと自体に対しては、その辺が解決されても同じような考え方を持つのかどうか、お知らせ願いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問","question":"私への質問ですが、今後財源がどういうふうになるかというところは試算しておりませんけれども、それに戻すという考えです。もう一つの、自動車メーカーと燃料メーカーというところの、燃料メーカーのほうも同じ責任があるかどうかということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"２番目についても、新たにというような認定された場合には、今度はどうなんでしょうか。そうした場合でも同じような趣旨になってくるんですかという、３点の質問です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"意見","question":"一方で、そういうある技術を使っていればもっと防げたはずだと。最新の技術を患者救済のために使っていくかどうか、そういうところの姿勢なども今後の考え方に反映してくるというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"辻副委員長","kind":"確認","question":"尼崎公害と名古屋南部の公害の判決ですが、訴訟そのものというのは、どういう訴訟だったんでしょうか。画期的な判断ということですけれども、「公害差し止めを命ずる」というのはどういう内容か教えていただけますか。","respondent":"田中健康課長","answer":"５０ｍ以内という局所的にという前提が付きますが、因果関係が認められるので、大気汚染物質の排出による損害賠償の責任を負うという判断が出たです。国および企業のほうは、大気汚染と健康被害の因果関係を認めておらないというふうに、コメントとして聞いてあります。","id":"exchange-018"},{"speaker":"辻副委員長","kind":"質問・要望","question":"だから、財源を求めてやれということなんでしょうが、これは法的にこういう形で自治体ができるのか。２つ目は、まず１番目の財源負担ということについて、自治体にこういう形というのは可能なのかどうか。","respondent":"田中健康課長","answer":"大気汚染の原因となる物質を排出する施設を設置する事業者、国のほうが財政負担をいたしまして、予防基金という形で財源をつくってあります。東京都はいろいろ難病等につきましても医療費助成をしておりますが、それと同じような中身で都単独の考え方で行っているです。","id":"exchange-019"},{"speaker":"辻副委員長","kind":"質問・要望","question":"今回の新しい１番目に対して、その原資というものを燃料メーカー、自動車メーカーに求めることはできるのかどうか。ところが、一自治体の中でこれを追いかけていったときに可能なのかどうかという、こういうものについてちょっと知りたいんです。","respondent":"田中健康課長","answer":"あるいは燃料メーカー等が相談に応じて財源を出してくれれば、これは制度としてつくることは、条例でも可能かと思います。東京都段階でこの辺の判断を、相手方がおることを含めて考えますと、非常に難しい部分かなというふうに考えてあります。","id":"exchange-020"},{"speaker":"辻副委員長","kind":"質問・要望","question":"２つ目のほうで、この問題で、現状としての段階でどういう動きがあるのか確認しておきたいんです。国のほうはＮＯ２とか、考え方というのは、現状の段階ではどこまで話になっているんか尋ねました。","respondent":"田中健康課長","answer":"大気汚染物質の排出原因者にその補填を求めることは、民事責任を踏まえた本制度の趣旨を逸脱するという考え方がこの答申では示されております。","id":"exchange-021"},{"speaker":"辻副委員長","kind":"質問","question":"今回、東京裁判が結審したといいますが、この争点になったのは、先ほど言った尼崎とか名古屋南部と同じですか。その辺、２点お願いします。","respondent":"田中健康課長","answer":"今回、東京地裁に起こされております東京訴訟の従来と一番違う点といいますのは、自動車メーカーの責任を初めて問うという中身で聞いてあります。","id":"exchange-022"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ただ単にメーカーに求めてはどうだということではなくて、そういう対抗線をどうするかという生き方の問題、これだけ車社会の中にあっての問題。ここまで直接突っ込んだ形での論議というのはまだ結論として出ているわけではないものですから、当面。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほどの質問にも私は若干触れたんですけれども、窒素酸化物を抑える技術がなかったのかというと、そうじゃないんですよね。そういう点では、ぜひ品川区議会では採択していただければというふうに思って、この点は私からも皆さんにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"金高委員","kind":"質問","question":"結審が終わったのは昨年１２月１８日という説明でありましたし、１０月２９日に判決が出るということですから、それを踏まえて、また審査をしてもいいのではないかという気がいたしますので、継続できればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"先ほどちょっと質問をしたところのように、数字的にも出ていない、いろいろな問題点があるところをとり切れないというような思いがあります。結果は、責任問題というのは、東京の判決で出てくるだろうけれども、内容的には疑問視するところがあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"あえて言いたいと思います。継続が多数のようですから、それはしようがないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"４０歳および５０歳の対象人数は何人でしょうか。３点お伺いします。","respondent":"田中健康課長","answer":"４０歳、５０歳については、こちらを採用する形になります。都のほうからも補助が出ますし、指導事業の部分は都の単独補助でございまして、３分の２ほど改善指導の補助を見込んです。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"何点か伺います。そうすると、４０歳と５０歳はこっちのほうになるということか尋ねました。","respondent":"田中健康課長","answer":"委員ご指摘のとおり、４０歳、５０歳の方についてはこちらで検診をしていただく。残りの５歳刻みの方については、従来の成人歯科検診という形になります。","id":"exchange-029"},{"speaker":"宮崎委員","kind":"質問","question":"親知らずを入れないと２８本ということになるかと思うんですけれども、４０歳と５０歳の場合は、そういうところというのは分かりますか。あるいは２０歳台からというふうにいわれているんですけれども、どうせやるんだったら、教えてほしいと求めました。","respondent":"田中健康課長","answer":"国のほうが４０歳、５０歳に合わせて、ここが一つの重点というふうに一般的に認識がされているんだなというふうに私どもとしては考えてあります。事業としては、今までの成人歯科の部分をより国の制度の趣旨に合わせた内容で切り替えるというふうに考えてあります。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"質問","question":"どうせやる事業ですから、こういう状況なので、こういうふうに考えているというふうなことになるといいなという感想を持ちました。４カ月後の検診で一フロー終わるということになろうかと思うんですけれども、３回目ですか、それとも１回ごとか尋ねました。","respondent":"田中健康課長","answer":"検診ならびに１回、２回、３回それぞれです。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"これが今年度で４カ月のところということになるから１１月３０日までということですね。１回１回やるんだったら、特にこれで１１月３０日とか決めなくてもいいんじゃないかという気がするんですけれども、どうなんか尋ねました。","respondent":"田中健康課長","answer":"３回目までを一サイクルとして、３回目まで、４カ月間のうちに受けていただきたいです。そうなりますと、いろいろ単価の問題等が生じますので、こういう形にさせていただいたという内容です。","id":"exchange-032"},{"speaker":"宮崎委員","kind":"意見","question":"私が聞いたのは、今年度が１１月末までで、３回で一クールで、３月末までに終わらせるということでこういうふうになっていると思うんです。２回、４カ月後に３回目の指導を受けるということが守られていけば、１１月３０日というのがどんな意味があるんだろうと思ったんですとの意見を述べました。","respondent":"田中健康課長","answer":"この期間までに第３回を一つの基礎ベースとして完了してほしいということが基本の中身になってあります。１２月になりますと、翌年の４月に改善指導の３回目というふうになってしまいますので、このような形にするという内容です。","id":"exchange-033"},{"speaker":"宮崎委員","kind":"意見","question":"ちょっとかみ合わないんですけれども、私は、３月３１日までに一クール終わらせてくれという、その事情がよくわからないんです。診療報酬との関係であれば、これはこれで診療報酬も参考にするけれども、費用は別に契約するわけですよねとの意見を述べました。","respondent":"田中健康課長","answer":"当然平成１４年度の診療報酬をまたベースに、平成１５年度の６月から始める事業としての契約をするわけですから、そこに矛盾が生じます。もう１点は、東京都のほうもこの３回を年度内にして、そういう内容としての事業というふうに組んです。","id":"exchange-034"},{"speaker":"築舘委員","kind":"質問・要望","question":"私も５０歳なものですから、これを受ける資格はあると思うんです。先ほど９,２００人いらっしゃるということで、そのうち３２０人程度だというのが最初から分かるんか尋ねました。","respondent":"田中健康課長","answer":"４０歳、５０歳の、期待はしています。あくまで積算した仮定の数字というふうにご理解いただきたいと思います。","id":"exchange-035"},{"speaker":"築舘委員","kind":"意見","question":"検診を受けるだろうと想定した数、それで今までのことを推測してということですけれども、検診をしないと後の指導はできないということですね。ある程度指導をしてもらうと治るのかどうかという、こういう実績というか、そういうのはありますかとの意見を述べました。","respondent":"田中健康課長","answer":"例えば私も今回説明会の席上でびっくりしたんですが、１日１回１０分間磨くという、それをすることで随分効果が違うそうです。３回と追っていって、３回目には何らかの効果が出るようにというふうに、先生方のほうでも努力していただけるというふうにお話ししています。","id":"exchange-036"},{"speaker":"築舘委員","kind":"質問・要望","question":"１０分間というようなことですので、そういう生活習慣をしっかりとつければ予防という形でうまくいくということだと思うんです。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いしたいんですが、実施場所ですけれども、検診した場所と、指導を受ける歯医者が何で同じにならないといけなかったのか、理由なり根拠があれば教えていただけますか。","respondent":"田中健康課長","answer":"１回目の指導が、検診の結果をお知らせいただくその回というふうに考えてあります。これは各歯科医師の先生方に一任していただきますので、同じ機関で、その検診を踏まえた指導をしていただくという内容で構成しています。","id":"exchange-038"}]},{"id":"topic-02","title":"部長にお残りいただいて、議題としてまいりたいと思いますので、後ほどにさせていただきまして、次の、その他のほうに移らせていただきます。 その他の１番…","agenda":"部長にお残りいただいて、議題としてまいりたいと思いますので、後ほどにさせていただきまして、次の、その他のほうに移らせていただきます。 その他の１番…","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"特に黒丸のついているところがこの５年間同じだということなものですから、非常に大事な中身ばかりだなというふうに思うんです。ですから、委員長会のところではここのところを引き続いて要望をしていただくようにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"須藤委員","kind":"意見","question":"先ほどお話があったように、８月１４日までにということなので、今宮崎委員の言うように、非常に大切なところもいろいろあるので、ここの委員会で今精査していくというのは大変だと思うので、正副委員長にお任せして、調整をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-03","title":"先ほど先送りをさせていただきました３番、行政視察","agenda":"先ほど先送りをさせていただきました３番、行政視察","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"両方ともそれぞれというような、委員長の言葉なので、部長から、ここはこうだよとかというようなご意見をいただければ、我々も決めやすいと思うので、いかがか尋ねました。","respondent":"小沼福祉事業部長","answer":"新しいものに取り組んでいるということでは、皆さんは非常に感銘を受けられて、好感を得て帰ってきているというような状況です。どちらがどちらがということでは申し上げにくいところですけれども、概要としましては、今申し上げたようなところです。","id":"exchange-041"},{"speaker":"山路委員","kind":"質問","question":"例えば北海道の場合で、北海道の旭川の健康プラザを調べたいという場合は、理事者は２人になるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"辻副委員長","kind":"意見","question":"コンピュータでインターネットを使って、あの当時でも進んでいたんですけれども、今はどういう状況になっているか。授産施設の中の内容が、ＩＴでソフトをつくったり、グラフィックをやったりしていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須藤委員","kind":"提案","question":"それはピシッと厚生委員会としての姿勢を見せていかないといけないと思うので、私どもは一つ提案をさせていただきました。ほかの方も一つ提案されたと思うので、提案されていない方がいらっしゃったら、提案をしていだいて、考え方を出してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"宮崎委員","kind":"提案","question":"ここというところが提案できなかったんですけれども、障害者福祉のところ、どっちも見てみたいという感じですから。この二つのところで、ほかにこういうところが特徴だというところは、部長のところでありますかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"金高委員","kind":"意見","question":"前に公明党のほうから岩見沢市のことを聞いたことがありますし、今部長のお話のとおり、知的障害者の方のそういったところも近くにあるのであれば、身障者の方と知的障害者の方の福祉センターということがドッキングできるのであれば、北海道のほうでもいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"須藤委員","kind":"提案","question":"ですから、正副委員長にお願いをして、委員会としてそれをピシッとみんなで提案してきたんだという形をとっていただければいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3026#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":31706,"voices":122}},{"id":"h14-20020723-8","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"建設委員会","time":"午後１時０９分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"船波委員","kind":"質問","question":"ＩＣカードが導入されて、ＪＲのＳｕｉｃａですけれども、今見てきた駅の券売機のところではパスネットが発売されていて、今はパスネットの利用が主力なんですけれども、全線開通された後には、ＪＲのＩＣカードのＳｕｉｃａでも乗れるし、パスネットでも乗れるという状況になるんか尋ねました。","respondent":"伊佐都市計画課長","answer":"パスネットも使えるように、どちらか一方が使えなくなるということではないようにしていきたいと考えております。Ｓｕｉｃａの利用についても、具体的な詳しい報告を受けておりません。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"意見","question":"ちょっと時系列的に、いつどういう話があったのでこういう新しい案が示されたのか、お知らせほしいと求めました。","respondent":"中島街路事業担当課長","answer":"平成１２年のバリアフリー法施行、あるいは東京都福祉のまちづくり条例の改正以降、検討をしてきてあります。エレベーターの設置について具体的に検討していくということが出されまして、それを受けて、実際につけるかどうかという具体的な検討をしてきたです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"この方たちの声ってどこまで届いているのかなというのを、まず１点、お伺いしたい。住民の方々との位置づけと、７年も話し合われているこの問題の認識について、改めてお伺いしたいと思います。","respondent":"中島街路事業担当課長","answer":"今年の５月９日に、ご理解をいただいたりする状況ではあまりなかったと、私ども認識しています。そのときに、事業者として、「安全管理等を検討しなきゃならないということがあります」とお答えしています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"ここのところの認識を、品川区も都と同じように持っていらっしゃるのかどうか、その辺を伺いたいと思います。地域の方々に対して不誠実なところから始まったところに、長くこじれている原因があると私は思っているんですが、その辺の認識をお伺いいたします。","respondent":"中島街路事業担当課長","answer":"１点目の、苦渋の選択という表現もしていますし、そういう認識を持っているものと考えています。地域住民の反対の方も含めて、約３０回の説明会、話し合いをさせていただいてあります。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大部分の方は理解をしてくれているということですが、大部分というその辺のとらえ方の根拠というのは一体何なんでしょうか。そこに住んでいらっしゃる住民の方々の安全というところをとらえた場合に、どうなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"現在、事業者として検討してきて、ここまでのものができていると認識しています。少なくともこの間、私が反対派の方の説明会に何回か参加させていただいていますし、大体１０名前後の方が参加されているです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"使っても人だけにして、そういうことをきちんとやってほしい、関係機関に働きかけてほしいということでした。一つは危険性への認識と、関係機関への検討内容とか、到達点を教えてほしいと求めました。","respondent":"中島街路事業担当課長","answer":"それを無視するとかいうことではなくて、あくまでもただ話し合いの場であるということで、私どもは認識しています。例えば８月、９月になって、引き続き話し合いが行われるものと認識しています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺はきちんと、この間の経緯とか、住民要望を伝えていただけるのでしょうか。だから、この道路がないと代替案は成立しないのかどうか、その点を確認しておきます。","respondent":"中島街路事業担当課長","answer":"あるいは、近隣の住民にご理解をいただいた上で、車を通すようにしていきたいと考えています。そういったことも含めて、現在、交通管理者である警察と協議をしています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"付替道路のスロープと、こちら側の階段と、エレベーターが鉢合わせする状況で、ここは何ｍぐらいあるんですか。今の不可欠な道路と言われて、私はとても心配で、このまま収められないという思いなんです。","respondent":"中島街路事業担当課長","answer":"こうすることによって、こちらにたまっている人の安全を確保するとか、さまざまな対策は可能だと考えています。安全対策も含めて、今、詳細設計で検討しています。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後です。尊重して、受けとめていただきたいなと思って、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"２基ついて１億円ですか、当然、橋桁を通る形でしょうから、全体の工事費というのはもっと大きなものになるんだと思います。これらの何点かすべての代替案は、総事業費としては、幾らぐらいかかるものなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"今度、エレベーターを設置したことによって、おそらく４億円前後がこの代替施設の費用になるのではないかなと思ってあります。もう少し正確な数字が出ましたら、また改めて当委員会で報告します。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"この辺の８００億円という枠を超えないのか、要するに、今回の新たな１億４,０００万円をどこから捻出されてくるのか。これだけの予備費みたいなものがあるのかどうかというのがわからないんですけれども、その辺をちょっと教えていただけますか。","respondent":"中島街路事業担当課長","answer":"先般もご報告いたしましたけれども、こちらの連続立体事業につきまして、４年程度の事業延伸ということを東京都が考えているところです。そうった意味では、再計算というか、計算がどうなっていくのかというのは見守っていきたいと考えています。","id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"２４時間の防犯体制とかといって相当なものになっていくと思うんですけれども、これからの管理上の問題で、実際に区が年間に支出しなければならないものが出てくるのかどうかとの意見を述べました。","respondent":"中島街路事業担当課長","answer":"こちらにつきましては、先般申しましたように、目黒区が管理するということになってありますので、管理費につきましては、目黒区のほうで支出するという形になるです。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問","question":"線形の問題をお聞きしたいんですけれども、大江戸線なんかは１０００分の５０とか、通常の車両で１０００分の４５とかいうのがあるみたいです。もし、リニアモーターカーにしたみたいな数字を持っていたら、ちょっと教えてほしいと求めました。","respondent":"中島街路事業担当課長","answer":"東京急行電鉄(株)の３社が走っているわけですけれども、細かい計算まではしていませんけれども、おそらく１,０００億円単位の話になるだろうと。ほかの例えば埼玉高速鉄道とか、現実的には不可能ではないかというような見解を、東京急行電鉄(株)側は申しています。","id":"exchange-013"},{"speaker":"菊地委員","kind":"確認","question":"は鉄道ですから、１０年でまさか路線を変えるわけではないでしょうから、そういう特認事項が設けられているんだと思うんです。安全性というのが錦の美旗みたいな感じになっちゃうんだけれども、そこだけで、住民に説明をすることにも無理というのがあるんじゃないでしょうかね。","respondent":"中島街路事業担当課長","answer":"東京急行電鉄(株)としては、１０００分の３５までをぎりぎりの線形として、今回の連立事業全体の中では計算しているです。再々申し上げてありますけれども、東京急行電鉄(株)としては絶対に１０００分の３５を超える勾配で鉄道を運行するという考えはないです。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"ということは、１０００分の３５を超えるものというのは、安全上問題があるということなんか尋ねました。","respondent":"中島街路事業担当課長","answer":"少なくとも、鉄道事業者の責任として、東京急行電鉄(株)は１０００分の３５を超える勾配では運行しないというのが東京急行電鉄(株)側の考えです。","id":"exchange-015"},{"speaker":"林（和）副委員長","kind":"質問","question":"一応、２案を正副委員長で考えたわけですけれども、このうちで理事者のほうでどうなんですかね。行くとすれば、どっちかに決めなきゃいけないと思うんですけれども、そちらの考えはどうか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"私も、今回、正式には初めて目を通させていただきましたので、ちょっと今すぐにはなかなか言いにくいんですが。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"じゃあ北のほうはどうですかなんて、違った方面で、違ったところを違った視点から見るのもいいのかなという気がしたということで申し上げたのです。前回、申し上げた北ということにこだわっているわけではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"林（和）副委員長","kind":"意見","question":"さっきの話だと、次の回までにというようなことだったら、では、資料を一応持ち帰って、よく検討して、次のときに結論を出せばいいかなと思ったんだけれども、今、それじゃあおそいということですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"田中委員から北海道はどうだという話があって、温暖化をどう進めていくのかというのが、今としては大切なのかなという気がしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"本間委員","kind":"質問","question":"そういう部分をちょっと探し出して、やっていただければ、わかりやすいんじゃないですか。ただ、緑化対策だけではちょっと、選びの違いというか、選びにくいですね。","respondent":"北野委員長","answer":"緑化中心になってしまったんですけれども、まちづくりということでは、こちらのほうで検討させていただいたんです。田中委員は北海道を提案されたから、北海道ですね。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"ちょっと１点だけ、理事者にお伺いしたいんですが、そういう意味ではちょっと難しいのか。政令指定都市だからこそできること、また、品川区ではそこまではちょっとできないようなことってあるのか尋ねました。","respondent":"中谷まちづくり事業部長","answer":"大きな都市計画の考え方に基づいて、各区の考え方は各区でまとめるというような形にもなっていますから、基本的に違ってこないです。ですから、緑化なんかについてはあまり変わりない。","id":"exchange-021"},{"speaker":"田中委員","kind":"意見","question":"大きな問題としてベースに考えるのなら、確かにヒートアイランド現象が札幌市内にもあるとは思いますが、直接比較をするとなると関西なのかなと。2)のところに、そういう面からすると、適切な見方はできないのかなという思いも少し持ちましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"本間委員","kind":"意見","question":"今、品川区人口３２万人の地方自治体と比較的似通った財政規模の地方自治体が、必ずしも一緒でなくてもいいわけですけれども。これは意見ですけどとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"船波委員","kind":"質問","question":"品川区もこれから景観ガイドラインを作成するわけですから、何らかの調査をしたいと思うので、景観条例のある北海道。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"全体としては関西のほうがいいなと思っているんで、景観条例に係わるようなところで、西のほうでどこかないですかね。たまたま函館ということで、ひかれてしまったんですが、もうちょっと広げて考えていただけないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"林（和）副委員長","kind":"質問","question":"じゃあ、岡山市のほうはどうなんですか、倉敷市とか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"堺委員","kind":"質問","question":"そういうのはさっきね。１案でよろしいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"本間委員","kind":"意見","question":"和歌山県だとか、鳥取県の自治体の市長が意欲的に取り組んでいるというお話をさせていただいた部分で、お調べになったところはないんですね。そこまではとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"本間委員","kind":"意見","question":"具体的な目標設定値を出して、各傘下の地方自治体にきちっと出す。結構、例えば四日市がどうだとかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"本間委員","kind":"質問","question":"だから、その温暖化対策の中に必ず緑化とか、そういうことも出てくるわけですから。どこの地方自治体もやっているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"堺委員","kind":"質問","question":"１案、２案という形に絞り込んでいただいたわけですから、１からやり直しになってしまう。どっちかで、正副委員長に一任するか、ここで決めるか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"林（和）副委員長","kind":"質問","question":"どうですかね。この雰囲気を見ると、そのほかの方々は、どっちかと言えば、大阪のほうがいいんじゃないかという雰囲気に聞こえるんですよね。","respondent":"北野委員長","answer":"ここでは諮ることはできませんが、ちょっと検討させていただきたいと思いますので、よろしくお願いいたします。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3730#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":24997,"voices":135}},{"id":"h14-20020723-9","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"文教委員会","time":"午後１時１０分～午後４時０８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"小中一貫校の学級数等","agenda":"小中一貫校の学級数等","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"平成１８年度一貫校開校までと開校後と二つに分けて考えるべきだと思うんですが、そのほかに２クラス増やすという考え方でいいのかどうか。それを超えた場合には抽選だという考えでいいのか教えてほしいんです。","respondent":"谷田部学務課長","answer":"第二日野小学校の移転先は検討中ですので、１学級ずつですので、平成１７年度までは各学年１学級ずつで学校を運営していきたいです。ですから、受入れ枠という制度が中学校１８校すべてに組み込まれているということでご理解いただきたいと思います。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"小学校は受入れ枠は現状では設けていないけれども、新たに設けると先ほど言いましたけれども、それも４０名なんでしょうか。右側の図で４０名というと１クラスですから受入れ枠ですけれども、三名かな、その分はブロック内からの学校選択の部分ということになるんか尋ねました。","respondent":"谷田部学務課長","answer":"それから小中一貫校を前提しての入学希望が伴われるのかどうかということもリサーチしながら枠を設けていきたいと思ってあります。１０人から１５人の範囲だとびったり４０人におさまりますが、その辺は十分検討の上、枠を設けていきたいという考えです。","id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"受入れ枠は４０人というのは中学校で、小中一貫校の１年生については１５人とか２０人というレベルだということなんですか、ちょっとわからないんですが。","respondent":"谷田部学務課長","answer":"１学級しか設けられませんので、その期間はそこに住んでいる子どもの数をベースにして受入れ枠を考えていきたいです。平成１８年度になります３学級になりますから、２学級分以上の枠は設けられるということになります。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"３クラスですから１２０名で目いっぱいだと、あと９５名の空きが出ますね。９５名のうちに日野中学校学区域、あるいは区内全域からどれぐらい枠として見ているのかというところを聞いているんです。","respondent":"谷田部学務課長","answer":"現行の制度からお話しますと、第二日野小学校が通学区域を前提にして学校選択制をやっていますので、そこに住んでいる方がまず優先されます。少なくとも第二日野小学校の通学区域外からは２学級分プラスアルファ分の枠はありますということで、今のところ考えてあります。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"２５名でいけば、枠の９５名は空くんだけれども、一貫校があるんだからここでも地域の子どもを優先してほしいという声が出てくると思うんです。日野中学校区域の子どもが９５名の枠のうち一定のものがあるのか、なければないでいいですけれども、そこのところがわからないのでとの意見を述べました。","respondent":"谷田部学務課長","answer":"私は現行制度の中でのご説明をさせていただきました。学校選択制の仕組みをもう一度洗い直す、制度そのものをどうするかということは、今後検討していかなければならない課題だと思ってあります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"意見","question":"全区募集をするというのだったら、何もそこから残る９５名をグループの中の学校で割るということではなくて、どうも話はそうではないようです。その辺でコメントがあればお答え願いたい思いますとの意見を述べました。","respondent":"谷田部学務課長","answer":"１点目の当初のお話ですけれども、２月以降この間地元でいろいろご説明させていただきまして、いろいろご意見をいただきました。第三日野小学校が１００名、第四日野小学校が６６名ということで、そういう危惧は当てはまらないと考えています。","id":"exchange-006"},{"speaker":"原委員","kind":"確認","question":"確認なんですけれども、中学校の７年生ですが、当面中学校は５学級とするということで、当面というのはどこの範囲でそういう話をされているのか、そこの確認をしたい。","respondent":"谷田部学務課長","answer":"ですから、今のところ学級数としては小学校が各学年３学級、中学校は各学年４学級が学校の標準規模からいって適切であるということが原則です。","id":"exchange-007"},{"speaker":"原委員","kind":"確認","question":"そういう意味では現状の中で当てはめた数字でいえば５学級になる可能性はあるから、その可能性の中でやっていきますということなんですが、そういった説明は開設準備ニュースの中でもちゃんとした形でやっているのかどうか確認したいと思います。","respondent":"谷田部学務課長","answer":"学校規模については、普通学級は小学校各学年３学級、中学校は当面５学級とします。日野中学校の心身学級も移行します」ということで、ご案内をさせていただいたところです。","id":"exchange-008"},{"speaker":"原委員","kind":"意見","question":"ということは、今ご説明をされたようなことでされているのかどうかということなんですが、文字で書いてあるのはわかるんですけれども。要するに、後になってずっと５学級と言ったじゃないかと、ずっと５学級に取るかもしれないよということだけで来る可能性もあると思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"高星委員","kind":"確認","question":"その前に、この資料は委員会資料なんでしょうか。その部分について、今原委員がそのことについて確認をしたいんだという話も出ているんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高星委員","kind":"質問","question":"小中一貫校開設準備ニュースNo.２というのは、各議員の書棚に置かれていたんです。この部分について中身ではなくて大きなところでお聞きしたいんですがよろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高星委員","kind":"質問・要望","question":"事務局のどなたが責任を持つんですかとなると、学務課でもないし指導課でもないし、その辺のところがわからないのでお聞きしたいというのが一つです。もう３学期なんだから今年はもうありませんよというスタンスでいくのか、その辺のところをお聞かせほしいと求めました。","respondent":"富田教育改革担当課長、谷田部学務課長","answer":"３課が一緒に開設準備を進めております関係上、３課の名前を並べるのを省略させていただきまして、教育委員会事務局とさせていただいているものです。今後、全町会のほうにも町会回覧のような形でお配りさせていただきたいということで… 学校教育法施行令の中に、当該就学予定者の就学すべき小学校または中学校を指定しなければならない」という規定があります。","id":"exchange-012"},{"speaker":"高星委員","kind":"質問・要望","question":"そうすると小学校の場合はブロックの中においての学校選択の自由ということは、その辺の整合性をもう一度確認の意味で教えてほしいと求めました。それと最初の「小中一貫校の学級数などが決まりました」と、これはどのレベルで決めているのかということを教えてほしいと求めました。","respondent":"谷田部学務課長","answer":"やってありますので、受入れ枠については枠を設けざるを得ないだろうということで、これから検討をしていきたいと思ってあります。７月９日の教育委員会におきまして、各検討委員会等の報告を取りまとめた結果をご提案申し上げまして、そこで了承を得られたとなっています。","id":"exchange-013"},{"speaker":"高星委員","kind":"意見","question":"そうすると、逆に言ったら今から第二日野小学校に行っていれば、将来も安定して行けるんだということになれば、極端なことを言ったら、今から住所を親戚の家とか、例えばそこでお店をやっていればそこに移すとかということもあり得るということなのかどういうことなのかとの意見を述べました。","respondent":"谷田部学務課長","answer":"それ以外の通学区域外の方につきましては、枠の中で枠を越えた場合は抽選になる。これは基本的には可能ですので、よろしくお願いいたします。","id":"exchange-014"},{"speaker":"高星委員","kind":"質問・要望","question":"とにかくそういうことも含めて、過分に保護者に混乱をさせないように、その辺のところはある程度ちゃんとしてほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田委員","kind":"質問・要望","question":"４年間なり待ってもらって、中学校からどうぞ入ってくださいということであるならば、現実にほかで受入れ枠を設けている小学校はないと思うんです。それが２年から受けられるか、２年から３年以降でも受けたいと思っている父兄がいるのであれば、その経緯を教えていただきたいなと思います。","respondent":"谷田部学務課長","answer":"平成１５年度から１７年度、建設中の制約条件の中で、その学級数を基本に建設期間中はいかざるを得ないだろうという制約条件の中で決めたことです。平成１８年度には小中一貫校が完成いたしますので、その時点では学校標準規模の学級数で運営していくです。","id":"exchange-016"},{"speaker":"石田委員","kind":"意見","question":"三つの校舎の余裕がおけないという限定を決めて１クラスと決めたとしか、二つ、三つの校舎の余裕を考えられる教室がつくれないのか。その辺の論議がないままに１クラスという決めてきたのかどうかというところが、その辺のところをもう一度お答え願いたいとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"したがって、最小確保できるものというものが一つ条件として出てまいります。実際、ほかの学校の改築の場合でも、やはり安全なところで１クラスと見ておくのが妥当ではないかと考えた次第です。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問・要望","question":"１クラスで見るということは、そこで４年間も５年間も空白をもたせるよりは、三つの余裕を持って受入れてあげる。三つの余裕はできると思うし、そのほうが優先されるべきだなと思っているので、これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中島委員","kind":"確認","question":"私の勘違いなのか確認をしたいんですが、小中一貫校というのはカリキュラムの上では普通の６３制とは違う形態を取ると思ったんですが、どうか尋ねました。","respondent":"青木指導課長","answer":"カリキュラムの件については、今検討しています。平成１８年度までにはスタートを切れるようなカリキュラムの作成をしていくということでご理解いただきたいと思います。","id":"exchange-019"},{"speaker":"中島委員","kind":"質問","question":"私の記憶では５年生から６年生に変わるぐらいからの移行のほうが、中学校にならないと途中からは入れないということなんでしょうか、その辺をどう補っていくのか。","respondent":"谷田部学務課長","answer":"小学校は６年間とするとなっていますが、小学校６年を終わった上でないと中学校に進学できないという制約条件があります。ですから、６年生が終わった後に入る。","id":"exchange-020"},{"speaker":"中島委員","kind":"質問","question":"そうであるならば、中学１年生のときにほかから入ってきた生徒に対して、補う部分のカリキュラムというのはこれから考えていくのか尋ねました。","respondent":"青木指導課長","answer":"７年生は外部から来た子どもと小学校からずっと上がってをきた子どもが一緒になりますので、カリキュラムの検討というのは十二分に配慮していきたいと考えております。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"それを当面だからリサーチするからずっと５クラスでもいいかという話にはならないと思うんです。そこのところをもうちょっとしっかり検討をしていただかないと、特色ある学校にはならないのではないかと思うんですけれども、いかがか尋ねました。","respondent":"指田教育次長","answer":"当面のところの考え方なんですが、今の時点で当面を５年にするのか、６年にするのがいいのかということは、正直言ってなかなか難しいと思っています。したがいまして、もう少しクラスを増やしてという選択枠を設けてというところも全く考えないわけではありませんけれども。","id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"そういう意味で、当面についてはなるべく早い時期にある形をつくったほうがいいと思うんです。このまま流すべきではないし、特色のあるものをつくっていくということが大事であると認識したほうがよいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"石田委員","kind":"確認","question":"その中で、これはバランスを考えてやるべき問題の事業なのかどうかというのは、どうお考えなのか１点。それなのに、何でバランスを考えなければいけないんか尋ねました。","respondent":"指田教育次長","answer":"当面の間は５学級にしましょうというような考え方で、筋から言えば石田委員が言われたのが私も筋だと思っています。ただ、それで突き抜けられない今の現状の中から、今回取った措置だということで、ぜひともご理解をいただきたいという次第です。","id":"exchange-024"},{"speaker":"沢田委員","kind":"質問・要望","question":"だから、出せるものでいいですから、出していただきたい。これは要望で結構です。","respondent":"青木指導課長、鷹倉庶務課長","answer":"７年目のカリキュラムについては、クラス分けをするとかいろいろなコースをつくるというようなことを今検討している。英語のことが出てきておりますけれども… 今、まちづくり事業部次長から云々という話がございました。少なくとも私ども教育委員会から用地の関係、まだ不確定な段階にございましたので、具体的な名称を使っていることはないと考えています。","id":"exchange-025"},{"speaker":"沢田委員","kind":"質問・要望","question":"カリキュラムは今日やっていないですから」と呼ぶ者あり〕だから、７年生に上がったときに、その問題をどうするのかという問題で聞いているんです。単純な思い違いであるならば、それはそれでいいですけれども、私は確認して今日臨んでいますので、そのことだけを言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"原委員","kind":"質問・要望","question":"例えばその他のその他で結構だから、そういったところでお話をするというのが本筋だろうと思うんです。それをどうするかちゃんとはっきりさせなければならない場ですから、そういう仕分けをちゃんとしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"高星委員","kind":"質問・要望","question":"第二日野小学校に隣接する土地をいつ買うかの話ですから、そこで決まってしまうと思いますので、私は要望したいと考えています。小中一貫校ができたときに、こっちのほうにも十分に手間や金をかけてくれなければ困るということでの要望書を出しているという話を聞きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"ですから、あるいは別の項を設けるなりして、その中でまた土地の話も含めてちゃんと形を取ったほうがいいんじゃないですか。今回は報告を受けておいて、新たにそういった報告も踏まえた資料をそろえて、新たにちゃんと皆さんで論議する部分も必要だと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"沢田委員","kind":"意見","question":"中学校で５学級に膨らみましたと、中学校に上がったときに、学級数の問題と一体不可分ものとして疑問が出されているわけなんです。それについては別途のところで、学級数の問題というのは一体不可分の問題であるということだけご理解いただければありがたいと思いますとの意見を述べました。","respondent":"鶴委員長","answer":"ただ、必要であればその他の項目だってあるから、そのところで論議をなさったほうがいいのではないかというご提言であろうと思うのです。","id":"exchange-030"},{"speaker":"中島委員","kind":"質問","question":"１点誤解があったので、５年生からカリキュラムの都合で移行すると、学級数に応じた質問をしたつもりなんです。その後に補足ができるのかという余分な質問をいたしまたけれども、そういうことですので一応弁解します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"佐藤委員","kind":"質問","question":"小中一貫校に関しては今後も報告事項がたくさんあるわけでしょうから、どういう報告を理事者のほうでお考えなのか、そういう大まかなところをお聞きしておいたほうがよろしいんじゃないかと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"佐藤委員","kind":"質問・要望","question":"例えばカリキュラムの話が質問として出た、それまでお待ちいただきたい」という形で質疑応答していかないと、その辺の答弁の仕方では結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"上山副委員長","kind":"質問・要望","question":"確認させていただきたいんですが、平成１８年度は小学校１年生は３クラスで始まって、順調にいけば５年で６年生まで３クラス。日野中学校の通学区域の児童が希望する場合は、中学校から一貫校に入学できるようにとの要望を踏まえ、当面中学校は５学級とする」となっていますね。","respondent":"指田教育次長","answer":"中学校で一定程度選択の幅を広げたいということで４クラスにしていこうと、こういう考え方で当初スタートしたわけです。それが平成１８年度スタートした後、一、二年の間で考えていきますということを先ほどからお話を申し上げている段階です。","id":"exchange-034"},{"speaker":"上山副委員長","kind":"質問","question":"小学校は３クラス、中学校は４クラスなんだという形で、かなりのスパンを考えていらっしゃるのかということをお聞きしたい。今、決まっていないんだというのなら構わないんですが、その辺をお尋ねしたい。","respondent":"指田教育次長","answer":"今、そこまでの将来方向は、上山副委員長が言われたように、何十年先のことまではお答えできません。平成１８年の当分の間ということを見極めることで、不十分な話になってしまいますので、その点はご理解ください。","id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"ぶり返す話をさせていただいて、中学校は何で４クラスにしたんですか。それだったら中学校おかしいかなと思うので、理由があるからそうしたんでしょうけれども。","respondent":"谷田部学務課長","answer":"指導課長でしたか、小中一貫校で３クラスの４クラスというふうに考えさせていただいたというようなお答えをさせていただきました。一応、そういう考えで３クラスの４クラスということでご理解願いたいと思います。","id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"そうしたら、その１クラスをどうするかという話も必ずある話ですよね。９年で一つの単位をつくった以上、何で最後の中学校だけ４クラスにしたのと、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鶴委員長","kind":"確認","question":"ほかになければ、私のほうから２点ほど確認を。ということは、受入れ枠というのは大体最大１クラス４０名の受入れ枠とか、あるいはそれを上回るような受入れ枠なんか尋ねました。","respondent":"谷田部学務課長","answer":"先ほども平成１５年、１６年、１７年の子どもの見込み数を申し上げましたので、それをベースにして４０人学級で相差を調べますと、大体１０人から１５人の範囲内となっていますので、そのぐらいの枠を各年度ごとも受けざるを得ないだろうと思ってあります。","id":"exchange-038"}]},{"id":"topic-02","title":"すまいるスクールの開校","agenda":"すまいるスクールの開校","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"そんなこともあったので、そういった粗相の絶対にないようにお願いしたいと思います。中身は大変すばらしいことなので、気をつけてやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"石田委員","kind":"意見","question":"今度、すまいるスクールも土曜日にということになってくると、地域のクラブチームが校庭を使っているところがあるはずなんです。その辺のところは必ず土曜日のあり方が９月以降に出てくると思うんですが、その辺の土曜日の扱いはどういうふうにお考えなのかとの意見を述べました。","respondent":"富田教育改革担当課長","answer":"９月開校予定の３校を含む４校の範囲内になってしまいますけれども、基本的な考え方としまして、あるいは体育館使用をお願いしたいということでお話をさせていただいて要るところです。","id":"exchange-040"},{"speaker":"石田委員","kind":"質問・要望","question":"最終的には申し込みは校長先生のところに行くわけですから、校長先生に９月以降もそういう形でどこまで携わるかというのを教えていただきたい。今後そういうことがあった場合、どこまでどういうふうに分けるのかなというところを教えていただきたいと思うんだけれども。","respondent":"青木指導課長","answer":"中学校の部活動等で私もいろいろと関係していますので、内容についてはよく理解しているところです。校長に相談をこちらから持ちかけるような場面もありますので、そのあたりは臨機応変に対応していきたいと、現在のところは考えております。","id":"exchange-041"},{"speaker":"原委員","kind":"確認","question":"確認なんですけれども、実施場所のご説明をいただきました。宮前小学校が本校舎ということで、独立性はちょっと欠けているのかなと思うんだけれども、この辺の使い勝手の説明をしていただけます。","respondent":"富田教育改革担当課長","answer":"２階に１室ありますが、ランチルームの１室を活用いたしまして、学年ごとの勉強会を行いたいと考えております。指導員が１名つきまして、フロアが違っていても混乱なくできるだろうということで、以上のような形で４室使っていく予定にしております。","id":"exchange-042"},{"speaker":"沢田委員","kind":"確認","question":"最終的にこの委員会で委員長会に持ち上げるという確認はなくて、正副委員長お任せするというのでいいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-03","title":"改めて行政視察","agenda":"改めて行政視察","exchanges":[{"speaker":"石田委員","kind":"意見","question":"逆に、こちらから品川区の議員として文部科学省はどういう形のものをねらって来ているかということを、委員会としてもう一度訪ねるとか。これが本来の行政視察のあり方なのかというところを一度問うべき時期でもあるんじゃないのかなと気がしますので、その辺のお考えというかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"原委員","kind":"提案","question":"その日数は２日でも３日でもあるわけですから、その中でプラン２１をもう１回皆さんで討議しましょうとか、疑問を投げさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"高星委員","kind":"意見","question":"あえてこんなことを過去１５年もやっているんだけれども、やっぱりどこに行ってもどこかにどの部分だけは頭に残っているというのがあるんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"沢田委員","kind":"意見","question":"これまで委員会の視察は恒例化していて、予算も組んでいて、予算の範囲内で大体２泊３日で行くというやり方がいいかどうかという問題の投げかけは。だから、その辺の説明をわかる範囲でしてもらうほうが先決かなという気がするんですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"沢田委員","kind":"質問","question":"これは構わないですよ。そういう案の上で出てきているわけですから、だけどその上でも前回それぞれ皆さんが……。","respondent":"鶴委員長","answer":"説明することはやぶさかではありませんが、先ほどこの件については最終的に正副委員長に一任をいただけると、お諮りしたときにご異議なしということであったと、今回の第１案にしますということです。","id":"exchange-048"},{"speaker":"石田委員","kind":"質問・要望","question":"確認だけしたいんですが、その点で１点ご確認をいただきたいのは、委員長から行く行かないということは議運のマターじゃないかと。その中で出てきたものですから、そういう方向性で行くというのも一つの道ではないですかというお話なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"原委員","kind":"質問・要望","question":"文教委員会としてこういう形の話があったよ」ということも、一つ行動を起こしていただきたいなと思うんです。やっぱり、そういう発想が出てきているわけで、その辺のところをご理解いただきながらまとめていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"中島委員","kind":"提案","question":"ただ、ちょっと興味を持ったのは、石田委員のご提案をもうちょっと詳しく教えていただきたいなと。具体的にどういうふうにしたらいいのかなとわからなかったので、もう一度お伺いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"石田委員","kind":"提案","question":"本来であれば委員会が先行して提案をして、荏原第五中学校で動いていくわけですから、非常に大切な役目があるんじゃないかな。先ほど委員長がおっしゃったように、そういう形の文教委員会としての行政視察という位置付けをしてもよろしいのではないですかという提案でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"中島委員","kind":"質問","question":"行政視察という形を取るのであれば、いろんな勉強会をどこかのホテルでやるとか、そういう形も取れると思うんです。ですから、一概にこれはというのではなくて、検討の中に今のご意見も取り入れるべきかなと思うんですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"佐藤委員","kind":"意見","question":"いい案があったんですが、やっぱり相手の自治体が「そういうことはご協力できません」ということがあってできなかったこともあるんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"中島委員","kind":"提案","question":"石田委員の提案はもっと前に出ていれば、また議論の余地もあったかなと思うんですけれども、今回の視察に関しては自分としても見たいものがあります。","respondent":"事務局","answer":"随行理事者、同行書記のあり方が中心でしたが、これをきっかけに見直しの議論は継続しているという理解だと思うんです。議長が議運のほうに、「こういうテーマが常任・議運・特別委員長会でありました」という形で議運に諮問するということは手法として考えられます。","id":"exchange-055"},{"speaker":"沢田委員","kind":"質問","question":"１泊で当面やるよりも、宿泊しないでも委員会の最中でやろうと思えばできることですから、それはそれでやればいいんだと思うんです。少しでも品川区の教育行政に委員会の活動が役立つような勉強会や調査をやれば、そうバッティングしないのではないかなという気がしますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"原委員","kind":"質問・要望","question":"今、このことで皆さんでいろいろ議論をしたわけですかから、それはちょっと生かしてほしいなと思うんです。これは要望です。","respondent":"鶴委員長","answer":"議長に相談して、より積極的にいろんなところを見に行ったりする、文部科学省の例について石田委員のお話がありました。そういうふうにして皆さんのご意見というのは、より積極的に生かしていきたいと考えておりますので、よろしくお願いをしたいと思います。","id":"exchange-057"},{"speaker":"石田委員","kind":"提案","question":"私は提案をさせていただいた理由もありまして、本当に百聞は一見にしかずというのは非常に思っております。私個人的には参考になる視察になると考えていますので、その点もつけ加えさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4446#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":45032,"voices":130}},{"id":"h14-20020723-5","meetingId":"h14-cm07","date":"2002年7月23日","dateIso":"2002-07-23","committee":"総務委員会","time":"午後３時０３分～午後５時４１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"の１番、東京法務局品川出張所移転計画","agenda":"の１番、東京法務局品川出張所移転計画","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"それは文書になっているんでしょうか。もしできたら、どういう文書で、その答申の内容と具体的な平成１６年３月と記述しているものを示していただければと思うんですけれども。","respondent":"西島経理課長","answer":"その点については先ほど説明しましたように、それが出て来次第、またお配りしたいと考えています。原則として一つの広域市町村に一つの登記所、平成１７年度頃までに１,００３カ所の半分程度までの縮減を図るということが述べられております。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"さっき説明があった平成１６年３月というのは、実際に原文も見たことがないということなんでしょうか。東京法務局長の方針で平成１６年３月ということなんでしょう。","respondent":"西島経理課長","answer":"正式な文書はいただいていません。平成１５年２月という案だったんですが、平成１６年３月までの１年間でよく検討してということだと思うんですがか、延びたです。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問","question":"一回説明に来たんだろうけれども、これでは表敬訪問とあまり変わらない中身だと言ってもいいようなものですから、これでは話にならない中身です。１年間説得期間を設けたという程度の形だと、その辺はどのように受止めて、どう対処するのか。","respondent":"本間総務部長","answer":"私ども正式に説明に来ないのをどうだこうだと言っている状況ではないので、当然法務局のほうでも区内の関係団体にきちんと対応しているかどうか。","id":"exchange-003"},{"speaker":"土井委員","kind":"質問・要望","question":"さまざまな条件を整えるなり、あるいは理解を得るための代替のものを考えるなりという形でこれから進むんですよという理解でよろしいんですか。それとも、要望書や意見書という形で出したのは撤回を求めるわけでから、それとの兼ね合いの中身の話をするんか尋ねました。","respondent":"本間総務部長","answer":"そういう姿勢で今後話し合いは進めてまいりますが、法務局では非常に議会の動きだとか、区側の動きをすべてよく知ってあります。例えば、当然姿勢は意見書ならびに要望書に書かれていることをバックに、今後協議を進めていきたいと私どもは考えているところです。","id":"exchange-004"}]},{"id":"topic-02","title":"のペイオフ解禁後の動向","agenda":"のペイオフ解禁後の動向","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"表現が延期というのがいいのかどうかわからないですけれども、要するに来年４月からペイオフ解禁というのはいかがなものかというところは、地方自治体からの要望として出ていないんか尋ねました。","respondent":"中尾根企画部長","answer":"特に２３区の場合は、今回も全国市長会に出す２３区の区長の要望事項ということで一旦取りまとめた分ですけれども、通常出していないんじゃないかと。","id":"exchange-005"},{"speaker":"桜井委員","kind":"質問・要望","question":"そういうところまで議会で論議するのがふさわしいかどうかというのがあるかもしれませんけれども、結構ペイオフ問題というのは世論にもなっています。そういうのはこういう要望だけで一定程度よしというのか、もう少しほかの形での働きかけというのは考えられるんか尋ねました。","respondent":"中尾根企画部長","answer":"私ども自治体としてそのことについてとやかく申し上げるところではございません。公金という性格そのものについてどうなのかという要望ということでご理解いただきたい。","id":"exchange-006"}]},{"id":"topic-03","title":"では２の行政視察についてですが、先にその他を行います。 (1) の海外調査団への調査依頼","agenda":"では２の行政視察についてですが、先にその他を行います。 (1) の海外調査団への調査依頼","exchanges":[{"speaker":"林（宏）委員","kind":"意見","question":"それから、選挙制度についても、国あるいは州と各自治体がどういうふうに違うのか、あるいは同じなのか。国全体のシステムの中で、地方の自治体がどういうふうに機能して組織されて動いているのかということを調べてきてほしいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"なかんずく運営の基礎は税ですから、それからアメリカは合衆国、州というのが国というような意識が大変強くあります。そういうことのよしあしは当然あるわけですから、そういうことも調べていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望というより質問というのはできるんでしょうか。そういう大ざっぱなことなんですけれども、要するに基礎的自治体の何を研究をされようとしているのか、その問題意識のところだけ聞きたいんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"桜井委員","kind":"質問・要望","question":"お答えいただけないというのは、それはそれでやむを得ないかなと思うんですけれども、せっかく何かございませんかという要望をいただいたわけですから、要望する前にどういうところを伊藤委員長が行かれるので、場合によればと思ったんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"土井委員","kind":"意見","question":"今、どうも選挙権というのか、その辺についても何となく違うようだと。民主主義というのは、これから考えていく上で参考になるんじゃないかなと考えていますので、あくまで個人的な意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"藤田委員","kind":"質問・要望","question":"アメリカの各州によって、行政のやり方がかなり違いがあると聞いているんですけれども、そうした中で議員の権限とか権能がそれぞれ違うと思いますけれども、どれだけの力を発揮しているのか、その辺を調査していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-04","title":"の特別区総務財政委員長会の要望事項","agenda":"の特別区総務財政委員長会の要望事項","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"今回の地方交付税の削減というのは、具体的にいえば都との関係というのは、影響度はあるんでしょうか。例えば、経常的経費にかかる国庫負担金の半減で３.２兆円程度と出されているんですけれども、そことの影響というのはあるのかどうか。","respondent":"市岡企画財政課長","answer":"その分一般財源化、不交付団体については間接的に、そういう意味では一般財源化の影響が出てくる可能性はあります。国が財政構造改革を進めれば、もう一方で一般財源化というものが出てくるという、全般的な問題だろうと思います。","id":"exchange-013"},{"speaker":"桜井委員","kind":"提案","question":"文面はおいておいて、その辺のことと、あとは特にこの前生活保護の問題とか就学援助の点というのは、こうした情勢ですから結構影響が来ていますね。個別名は挙げるかどうかは別としても、一定程度意見を上げていくというところをしたらいいんじゃないかと提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"桜井委員","kind":"提案","question":"この間、住民参加のところで提案したんですけれども、宝塚市の社会福祉ということで住民参加をやっているんです。そこは調べていただいたんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1590#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":16128,"voices":59}},{"id":"h14-20020724-13","meetingId":"h14-cm07","date":"2002年7月24日","dateIso":"2002-07-24","committee":"清掃・リサイクル特別委員会","time":"午後１時０８分～午後２時４６分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"番の報告事項、そのうちの１番、中防灰溶融施設","agenda":"番の報告事項、そのうちの１番、中防灰溶融施設","exchanges":[{"speaker":"上山委員","kind":"質問","question":"基本的なところでちょっとお尋ねしたいんですけれども、容積ですか、もしわかれば。活用の実際の方法というんですか、方法があれば、その３点ばかりちょっとお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"先に３点目の活用の状況からご説明したいと思いますが、北工場、それぞれ清掃工場の舗道のインターロッキングブロックという形で使われております。","id":"exchange-001"},{"speaker":"上山委員","kind":"質問","question":"規模というんですか、体積というんですかね、そういうことはないんでしょうかね。考え方というんですか、補足していただけないかなと思うんですが、そこら辺どうか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"清掃一部事務組合で、これは１４年２月の段階ですけども、焼却灰の溶融スラグの利用に関する方針というのを決めました。並行して安全性を確認し、それが広がっていく中で、おそらくそういうコストとしても下がってくるというふうに考えられます。","id":"exchange-002"},{"speaker":"上山委員","kind":"質問","question":"今出されている大体焼却の関係でそれをスラグにして、４００ｔですか、これで間に合うというような方法だと思います。そういう方法でもあれば、いろいろ区民の皆さんと一緒に取り組むというんですかね、それは結構大事かなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"川西委員","kind":"意見","question":"若干続いておりますが、新しい技術革新ということに対してなんですけれども、２月に法律ができたという今の説明がありました。これは補助金というのはちゃんと出しているのかどうかということと、企業なのかどうか、その辺についてちょっと聞いておきたいと思いますとの意見を述べました。","respondent":"中山清掃リサイクル課長","answer":"先ほど２月に策定した基準と申し上げたのは、あくまでもこれは一部事務組合の方針ということでございまして、法律ということではございません。約７０億円、４分の１程度は国庫補助の対象になるものということで、当然国庫補助申請を行うというふうに計画しているものです。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"スラグの関係なんですけれども、新しい研究段階、技術的にも研究段階ということですよね。処分するところが短期間のうちになくなったというのは困った問題ですから、どういうふうにされてきているのか、その辺の考え方を伺いたいと思います。","respondent":"中山清掃リサイクル課長","answer":"ある程度資質の、今後の灰溶融施設から出てくる溶融スラグについては、質も上がってくるというふうに言われております。まだまだ稼働させながら、これは随時品物、品質のチェックというものは当然毎年のようにそれぞれの工場でやっていくという形にはなっております。","id":"exchange-005"}]},{"id":"topic-02","title":"続きまして、２番目の東京二十三区清掃協議会","agenda":"続きまして、２番目の東京二十三区清掃協議会","exchanges":[{"speaker":"南委員","kind":"質問","question":"一部事務組合は１７年度をもって解散というか、そういう方向で進んでいるわけですよね。２３区で、組織として存続をしていくというふうに考えていいのかなというふうに思っているんですけど、ご説明ください。","respondent":"中山清掃リサイクル課長","answer":"どこまでが許容なのか、そうじゃないのかという話になると、必ずやはりそれは関係機関で調整する部分があるかと思います。こういう協議会組織なりで調整していく部分というのは、少なくとも当面続いていく、１７年度以降も続いていくというふうに考えられます。","id":"exchange-006"}]},{"id":"topic-03","title":"続きまして、３番目の品川区リサイクル推進行動計画","agenda":"続きまして、３番目の品川区リサイクル推進行動計画","exchanges":[{"speaker":"嶋委員","kind":"質問","question":"今の６ページのところなんですが、そういう中で、環境的なものをどうこの中に入れていくかお聞きをしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"環境基本計画の検討というのを課長、体系の検討をしているわけですが、先ほどご説明申し上げたように。ただ、冒頭の考え方の中にも入れたように、背景としては入れてあります。","id":"exchange-007"},{"speaker":"嶋委員","kind":"質問","question":"文教委員会になるのかどうかわからないのでお聞きをしたいんですが、この中での子どもたちのそういう実践教育の現場の視察みたいなものは、どれぐらい今進んでいらっしゃるかお聞きをしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"若干ですけども、集められたものがどのように処理されていくのかというものを見るようなケースも、昨年度はまだ２校ぐらいですけど出てきております。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"今回出てきたのはリサイクル推進行動計画を平成１４年度から改定する、時間というものを使うんではないかとか。区が一体となりということですから、前回と同趣旨の質問になってしまうので、整合性をとった説明なりがされるものなのかどうか。","respondent":"中山清掃リサイクル課長","answer":"それと、検討というのは、ほかの本来やるべきことがおろそかになるということがないようにつくっていっているというふうには理解しております。","id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"ぜひそれをお願いしたい。区民の方の協力が大きな前提になってくると思いますので、ぜひその点、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"川西委員","kind":"質問","question":"廃棄物減量等推進協議会というんですかね、これは各町会から何人出ているのか。ですから、さっきの第１番目のことのこれからの働き、今までの役割、それから町会から出ている、３人から５人出ていますよね。","respondent":"中山清掃リサイクル課長","answer":"基本的に既にこれまで条例だとかに基づいてそれぞれ設置がうたわれているものですけれども、当初委嘱状をお渡しして、地区ごとに連絡会を行ったり。","id":"exchange-011"},{"speaker":"川西委員","kind":"質問・要望","question":"この３年間ということが、そういう記録を皆さんの前に発表する機会を設けてほしいと求めました。終わりにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"どう力を入れていこうとしているのか、ちょっと大きなところなんですけれども、その辺をまずお伺いしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"それについてはこういう行動が考えられるというような具体的な事例を最近は入れるようにしております。基本的にはまずそういうごみ減量の意識の必要性を認識してもらいながら、今までのものをより踏まえて、仕組みをつくっていくという考えでおります。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ出てきてくださいというような、そういう働きかけというのが望まれるんじゃないかなと私は思うんですけど、その辺はいかがでしょうか。あるんですけども、その辺の参加をさらに促すようなアイデアというか何というか。","respondent":"中山清掃リサイクル課長","answer":"さりとて、そういう手段というものを一定の限界の中でやっていくという部分があります。今後どうやっていくかを考えているところですので、そういう区民の方の意見をもらえる場面も広げながらやっていきたいというふうに思っております。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"発生抑制のところで、現状は今どのくらい話が進んでいて、どのくらいの期待ができるのかなというところをちょっと聞かせていただきたい。この辺がどう進むのかも、もし具体的なものがあったら説明を求めました。","respondent":"中山清掃リサイクル課長、金井環境課長","answer":"先に質問２点目の生ごみの状況ですけれども、１カ所に集約された住宅から大量に出てくるというのは事実ですので、何か工夫ができないか。生ごみ処理機を本来セットで住宅に設置できないか、これはまだ研究段階ですけども… まだ具体的なお話にはもうちょっと時間が必要でございまして、一応予定では、８月２０日の区民委員会で報告したいと考えております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区の場合なんかは、すごく生ごみ減量に役立つであろうなと思うので、ぜひ研究を進めていって実現していただきたいなと思います。期待しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"嶋委員","kind":"質問・要望","question":"どういったところに置かれているのか教えていただきたいことと、衣類のことについてお聞きをしたいんですが、区のほうに要望が来ているのかどうか。ごみの場所を通るたびに思うことが多々あるので、区のほうに、要望があるのかもちょっとお聞きをしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"八潮地域センターを含めて小学校１８カ所で第２・第４土曜日の午前１０時から正午までの時間限定なんですけど、ここで古着をお受けしております。そちらにお持ちいただければ、リサイクルに基本的に回るようになっておりますので、よろしくお願いします。","id":"exchange-017"},{"speaker":"嶋委員","kind":"質問","question":"２,０００部と年何回かの配布まではいかないまでも、これをちょっと大きくしていくお考えなのか、お聞きをしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"それで、あとはインターネットホームページでは、それぞれの場所、図を入れてご説明しています。八潮は地域センター１カ所というわけです。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"２年間の任期の中で、区民への報告もしながら、新しい分野への広がりというのは大事なんじゃないかなという気がすごくするんです。できるだけ広く区民の意見と意識を啓発するという角度からの区民の参加型というのをもう一回ちょっと伺いたいというふうに思います。","respondent":"中山清掃リサイクル課長","answer":"模範を示していただくと、これを実のあるものにするために、そういう役割が推進員と審議会に違いがあるということはご理解いただきたいと思います。一つ考えているのは、そういったものの成果の発表というものを、広報なんかも使いながら周知していきたいなというふうに思います。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私がちょっとこの質問で区のほうの考え方をきちんと伺いたかった、もっと機会を広げていく必要があるんじゃないかなと思って質問したんです。ですから、推進員が２年ごとに成果を発表される、推進員以外の方たちの区民の意見を聞くチャンスをできるだけ多くとってほしいという趣旨なんです。","respondent":"松本環境清掃事業部長","answer":"そういう役割だということをご認識いただきたい。そういう意味での働きかけはしていきたいと思います。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"あるいは区に対する要望だとか、参加型という、そういう質問をしたところなんです。ですから、推進員云々かんぬんでは全然ないということで、広めることが必要だと思うので、その辺の見解を改めてちょっと伺いたいと思います。","respondent":"松本環境清掃事業部長","answer":"いわゆる区民の参加、実践、これをどうするかというのが私どもの最大のテーマでもあるわけです。あらゆるチャンネルを通じてこの辺は意見を吸い上げていきたいし、参加も呼びかけていきたいと考えていますので、よろしくお願いいたします。","id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"だけど、今品川区がとっている体制では、私はちょっと不十分じゃないかなというふうに思ったので、あえて聞いたわけです。二人の方の委員からも、もう少し参加を広げるべきじゃないかという発言があったわけですから、ぜひそこは受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"川西委員","kind":"質問・要望","question":"せっかくの機会ですから、１分ください。ですから、推進員の役割の重さというものを今後もっと構築していただきたいということで、ご答弁要りません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"辻委員","kind":"確認","question":"曜日は間違いないか、夜間持ってくるか、カラスの状況はどうかというのを書くようになっているわけじゃないですか。それはどうなっているのかということから言うと、現状はどうなんか尋ねました。","respondent":"中山清掃リサイクル課長","answer":"ただ、２年間という任期がありますから、次回にはより公募の仕方も充実させて、より多くの参加をいただきたいというふうに考えております。個別具体な話としては、清掃事務所等が個別に対応する材料としていただく、こういうことです。","id":"exchange-024"},{"speaker":"辻委員","kind":"質問","question":"現状としては、活動費というのが年額２,０００円出ているわけですから、やっぱり最初スタートの間はきちっとしていかないといけないと思うんですね。集積箇所は何百あるか、すぐわかるんですか、集積箇所、幾つあるか。","respondent":"中山清掃リサイクル課長","answer":"集積所というのは、今大きく言って１万カ所ぐらいから収集を区内ではやっているです。","id":"exchange-025"},{"speaker":"田中委員","kind":"提案","question":"ちょっと提案をさせていただきたいんですが、新たにいろいろ調査・研究というんでしょうか、することも委員会の中で必要なのかなということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"品川区の今の説明の中で、生ごみの処理について資源ごみとしてやっていく体制が一歩進んだなと私はそういうふうに感じたんですね。ですから、私としてはこういう分野も近場のところでいいですから、ぜひ機会があったら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5670#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":30885,"voices":66}},{"id":"h14-20020724-16","meetingId":"h14-cm07","date":"2002年7月24日","dateIso":"2002-07-24","committee":"街づくり特別委員会","time":"午後１時０９分～午後４時１０分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"都市計画審議会に出されて、都から意見を求められたことについて、品川区はどういうふうな意見を出しているのかというのが知りたいんです。床面積は超高層新宿三井ビル５０棟分に匹敵するということですけれども、どのぐらいの内容なのかというのが分かれば知らせてほしいと求めました。","respondent":"伊佐都市計画課長","answer":"区市町村の意見照会として、区がどういう回答をしたのかですが、区長意見を申し述べる際に、２月１９日の区の都市計画審議会に諮りました。８９２haといった数字がどこから出てきたものか私は存じておりませんし、お答えできませんが、ご理解いただければと思います。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"ヒートアイランドについてはいかがでしょうかとか、緑の状態がどうですとか、大半の方が問題だという意見を出しています。第３地区もそうですし、総床面積がどのくらいかとか、そういうのを教えていただきたいと思うんです。","respondent":"伊佐都市計画課長","answer":"かつ厳格な規制を実施する一方、効果的に都市づくりを進めていく必要がある」、市街地見直し等とも全く一致するものであると考えております。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"後段の、大崎の６０haと申し上げましたので、次回の委員会の中で、私の質問の回答をほしいと求めました。住民の生活のあり方、仕事の状態というところに心を寄せて、残念ながらそこの点についてはちょっと見えにくいと指摘せざるを得ないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"船波委員","kind":"質問","question":"その他まちづくりにおいてどういったことができるのかとか、どういった地区計画だとか、分かりやすい情報提供がされることが大切と思います。そういった意味で、これから先、そういった計画はないんか尋ねました。","respondent":"伊佐都市計画課長","answer":"１年の中で作業をする中で、前回もたしかご説明したと思うんですが、大規模な変更というのは今の段階では考えておりません。どこまでできるかということは検討をしますが、私どもとしては、これが今回の土地利用の基本方針の上位計画というふうに考えてありますが。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"最後のところが聞き取れなかったんですけれども、これは土地利用計画の上位計画と位置付けるというんですか、位置付けないというんですか。前も聞いたらば、品川区独自の判断が作用するんだということとの関係と、これはどう見たらいいのかというあたりを教えてほしいんです。","respondent":"伊佐都市計画課長","answer":"それを区主体で見直しを検討するということで、調整して、都が決定するという立場です。示された指定基準の範囲内でどういう考えをとっていくかというのは、これは区の主体性がはっきり出てくる部分があるというふうに考えてあります。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"すごい環境負荷がかかるじゃないですか。環境をというのであれば、本来なら違う方向に進むべきじゃないのかなというふうに思うんですけれども、その辺はいかがか尋ねました。","respondent":"伊佐都市計画課長","answer":"国、今回の基本方針だけでなくて、それについて今回の土地利用基本方針の段階で区として差しつかえないという意見としては。大崎、これはそういったところではそういった他の選択がされているという考え方に合った形での開発を誘導していきたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"４０年の将来を、２月２３日の中間方針から１カ月の間に意見を上げろ、上から見たまちづくりプランだという問題が一つ。都市計画審議会でやったから気の毒だというふうには思うんですけれども、多くの問題をはらんでいるということだけ述べておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問・要望","question":"今日はいいんですけれども、さっき私が質問をしました、センター・コアの中の大崎の関係はお示しいただきたいというふうに申し上げたんですけれども、それは。","respondent":"南雲都市開発課長","answer":"大崎の床のボリュームですよね。現状である程度確定しているものは集計して、お出しするようにいたします。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":21504,"voices":24}},{"id":"h14-20020725-14","meetingId":"h14-cm07","date":"2002年7月25日","dateIso":"2002-07-25","committee":"行財政改革特別委員会","time":"午後１時０５分～午後４時１６分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5714#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":4114,"voices":7}},{"id":"h14-20020820-6","meetingId":"h14-cm08","date":"2002年8月20日","dateIso":"2002-08-20","committee":"区民委員会","time":"午後１時０８分～午後４時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"郵送されて、各区でいろんな情報が出ていますけれども、その中で、番号が見えているとか見えていないとかいうのも出ていますし、それから番号で変更とかというのもありますが、品川区に対してはそういうクレームとか、現実にどの程度あったのか、数字的なものを教えていただけますか尋ねました。","respondent":"冨田戸籍住民課長","answer":"８月１日に臨時電話を設置しております。一番多いのが、番号変更ができるのか、できないのかというようなお問い合わせが８４１件のうちの６８件あります。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今条例をつくるというふうに、それはまだ正式な条例ではないのであれですけれども、品川区としての対応をできる形のものをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、ここらあたり特段の努力をしていただきたいなと、よろしくやってほしいと求めました。〔「要望ということで」と呼ぶ者あり〕結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７６％が延期を求めているという、こういうふうなところだというふうに受けとめる必要があるんじゃないかなというふうに思うんですね。いかがか尋ねました。","respondent":"冨田戸籍住民課長","answer":"１点目のほうの件数が多かったという部分なんですけれども、先ほど申し上げましたように、もう少し説明をというようなご意見もございました。障害対応編、そういった原因を究明してできる限り早く復旧をするという、その連絡方法等が定められているものです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうふうなところで、この延期を求めるとか、そういうところではどういうふうに考えられているのかということが一つ。ＩＣカードというんですか、そこら辺のところの職員の人数と、その研修が実際にどういうふうになっているのか。","respondent":"冨田戸籍住民課長","answer":"その事務研のメンバーに対しては、３回ほど制度の概要、事務手続についての説明をしています。８月に１回、説明会、テスト等を行っております。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それに対してどう対応するかというふうなところで、検討していただきたいなというふうに思うんですけれども、それが一つちょっとお聞きしたい。そういうふうなところでの個人情報保護法案が通らないうちに稼働するというようなことに対しては、品川区としてどう考えているんか尋ねました。","respondent":"太川区民生活事業部長","answer":"いい形で実質上使えるような、それから非常に安全性を十分考慮したような形で実施するというのが自治体の役割というふうに認識していますので。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"凍結延期すべきであるという、そういう声が９５.７％というふうなことでしたので、訂正します。今度の条例ですか、３定に提案がされるという条例についてなんですけれども、そこら辺のところもちょっと説明を求めました。","respondent":"太川区民生活事業部長","answer":"先ほど補足のところで説明させていただきましたが、通常ですと、これは情報公開・個人情報保護条例でクリアできる部分だと思います。やはりそこの部分を配慮して、そういう趣旨で条例につきまして準備がなされている、そういうことです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"何か問題があったときには区長が送信を切るというか、そういうことも含めてすることができるというふうな内容だと思うんで、そういうふうなことも含めての条例というふうなことなんか尋ねました。","respondent":"太川区民生活事業部長","answer":"現在、まだ本当の検討、いろいろな部分で、部署で検討を重ねているところですけれども、基本的な考え方といたしましては、緊急時の対応の部分では、場合によってはそういうこともあるという、そういうことも含めたものになろうかと考えています。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"お話をお伺いしたところでも、先ほど職員が地域センターで１２３人、あと庁内でもありますよね。そこら辺のところで、区としてメリットとデメリットの部分について、どういうふうに考えられているのか。","respondent":"太川区民生活事業部長、冨田戸籍住民課長","answer":"これはもう導入に当たってのご説明の中でもさせていただいてありますが、今後いろいろな行政需要に対応する、そういう行財政改革の中にでも。プライバシー保護というのは、私どもの一番課せられた責務ですので… ２４名と３名で２７名です。情報システム課のほうは３名だそうです。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"今回９３の事務から、１７１プラスして２６４ですか、今回の国会の中で提案されましたよね。本当にまだ９３が出発してもいない段階から、またプラスで提案されるというふうなことも余りにもちょっと安易じゃないかと思いますしとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"本田委員","kind":"質問・要望","question":"東京２３区では全体としてどうなっているのか。内容的には私も罰則規定を明確にすべきだし、部長の答弁ですが、もう一度お聞かせいただきたいなと思います。","respondent":"太川区民生活事業部長","answer":"３定に向けて今いろいろな各セクションが集まりまして検討していますので、そういうような形の条例を目指していきたいというふうに考えてあります。今各セクションの中での検討を重ねているところですので、そういうことでご理解いただきたいと思います。","id":"exchange-011"},{"speaker":"本田委員","kind":"提案","question":"東京２３区や他の自治体、国のレベルで約束が守られない格好で出発をしたというふうなことに対する国民のちょっと批判的な世論が多いわけですから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"先ほど鈴木ひろ子委員の質問の中でちょっと気になったので、事業部長がおっしゃったのはそのとおりだと思うんです。不安だ、不安だって、じゃあ職員組合でこのことについては反対か尋ねました。","respondent":"太川区民生活事業部長","answer":"この件に関しまして、私は「さけび」等の中で判断していますけれども、職員組合につきまして、表立って反対という形はちょっと聞いたことはないですね、そのように認識しています。","id":"exchange-013"},{"speaker":"三上委員","kind":"意見","question":"やはりそういう区民から不安だという、そういう電話等があれば、それを解消していく仕組みというのをやはりやっていってもらいたい。ぜひ条例化も含めて、そういう安心できるようなものにしていってもらいたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから区の職員がどうのこうのというだけではなくて、だって今までだって流出事件というのがさまざま起こっているわけですから、そんなところも。ここのところについてちょっと説明していただきたいんですけれども、委託管理というふうなところはどういうところが考えられるのか尋ねました。","respondent":"冨田戸籍住民課長","answer":"ネットワークのシステムを動かすのは区職員だけでは到底できませんので、外部委託によります。仕様等の中でセキュリティ確保を盛り込んで、十分に遵守するようにという、そういう意味合いの規定です。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的にどういうふうなところが出されるかというふうなところというのはあるんでしょうか。どういう部署が委託する。","respondent":"冨田戸籍住民課長","answer":"機器類を操作する部分、それからシステムの中身ですけれども、相当部分外部委託をしておりますので、その部分ということになりますけれども。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"というところの、委託もされるし、また職員も全国で、もう本当にたくさんの方がかかわるというふうなところでは、そこのところをきちんと担保していくというふうなところもやはり、ただ信用するということではなく必要なんじゃないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"南委員長","kind":"提案","question":"ですから、品川区としてはどういうことを考えていくのか、それをちょっともう少し具体的に説明をしていただきたいというのが一つです。条例化は今度の３定で区のほうから提案するというお話なんですが、２定、その辺を説明をしていただきたいというのが一つですとの意見を述べました。","respondent":"太川区民生活事業部長","answer":"基本的にこのセキュリティの部分は住基法の中で、それから当私どもの中の情報公開・個人情報保護条例の中でこれは対応できるものと考えています。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"委員会でやらなくても、逆に我々の中で、各会派でできるんじゃないですか。理事者の予定ということなんでしょうけれども、なぜそこに入れなきゃいけないのかなという、その委員長の意見はちょっと理解できない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問","question":"委員会の仕切り方なんですけれども、住基の報告はいただいているんですけれども、この条例は区民委員会の条例になっているんですか。運用じゃないんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"例えばスポーツ施設のトータル的な話なんですけれども、現行の予約システムが全くなくなってしまうという意味でいいわけか尋ねました。","respondent":"宮地区民課長","answer":"この間検討を進めまして、今のところはというご理解でお願いしたいんですけれども、今現在は従来のと並行して進めていく形になります。いずれ整理になると思いますけれども、従来のと並行ということで、ご理解いただきたいと思います。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その出しているのと、当日申し込み、インターネットでやるのとは同じ抽せんになるのかなとか、そこら辺がわからなかったので。インターネットでやるのとはがきとはどういうスタイルでやるのかなというのがとの意見を述べました。","respondent":"宮地区民課長","answer":"それは全く同じで、同じ抽せんの対象になります。その後、抽せんになりまして、ご連絡が行くということです。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、空きがあるからインターネットで予約するんだよというふうに何か、そうとったんですよね。そこら辺が、完全にシステムが変わるんだということが。","respondent":"宮地区民課長","answer":"実際には抽せんを行っている施設と、それから本当に早い順番で受け付けるのと、２種類あるんです。抽せんが全くない施設もありますので、その場合は空いているところから押さえていく、そういう形になります。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"意見","question":"品川区は天王洲に２面ありますけれども、２面を申し込みするときに、そこで抽せんですよね。空いているときと空いていないときとが何かすごく引っかかるんだよねとの意見を述べました。","respondent":"宮地区民課長","answer":"大変申しわけありませんが、不公平が生じないように、エントリーはいろんな方法でする方法ができてくる。抽せんは同じような形で抽せんをして決定をするということですので、手段が一つ増えたというふうにご理解いただければよろしいかと思います。","id":"exchange-024"},{"speaker":"三上委員","kind":"意見","question":"１年に１遍自分たちが何かやりたいと思っても、それがなかなかもう借りる場所がないなんていう、そういう苦情もあったわけです。そこらあたりをどういうふうに感じていますかとの意見を述べました。","respondent":"宮地区民課長","answer":"いろんな団体によって３カ月前だったり２カ月前だったり、社会教育施設ですとわりと早めに３カ月前、免除になるかわりに１カ月前になってしまう。","id":"exchange-025"},{"speaker":"三上委員","kind":"質問","question":"ですから、そういうふうな、この同じ利用する人たちが、どういう形でそういう利用料金の部分の公平性が図れるかを考えていかなきゃ。そこのところを期待していきたいと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺の管理はどこの部分できちんとやっていくのか、銀行だって、暗証番号を適当にやって落ちちゃう可能性はあるんですよね。銀行口座で落とすというのをやっているんですから、その辺の管理というのはどういうふうにつくられるのかなというのを１点説明を求めました。","respondent":"宮地区民課長","answer":"これから１０月２１日からスタートしてみて、やってみて、事後でどういう問題が出てくるかというのは検討の一つの課題になろうかと思います。やはりここまで来た以上、しっかりとやっていきたいなというふうに考えておりますので、ご理解いただきたいと思います。","id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"やっぱり今までは事前でやっていたけれども、事前で考えるべきじゃないかなと思うんですよね。還付は今まで予約した人が事前に払って還付できていたわけですから、きちっと検討をしていただきたいなという、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"三上委員","kind":"意見","question":"料金がまた利用料、１回３００円なら３００円なりのプラスになるとかという、そういう仕組みにしておけばいいわけでしょう。そこら辺をもう少し工夫してもらいたいと思うんですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"松澤委員","kind":"確認","question":"確認なんですけれども、第二立会川幹線ができても、この状態ではだめなんでしょう。確認をちょっとしておきたい。","respondent":"久保田防災課長","answer":"所管が違いますので、ちょっと大丈夫かどうかということについては、正確な回答はできませんけれども、かなりのそういう雨水、降雨量に対しての対応は第二幹線でできるということで、軽減できるということで、今下水道局のほうでやっているという状況じゃないかと思います。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"詳しいことを質問したいんですけれども、どういう意味で書いたのかちょっとわからないんですけれども、上流を書くべきじゃないかと思うんですね。目黒川流域だったら、品川区役所より上流の雨量を書くべきかなというふうに思うんだけれども、これはどういう書き方なんか尋ねました。","respondent":"久保田防災課長","answer":"先ほどの時間ごとで言えば、ほとんどこの４７ミリが２１時２０分から２２時２０分ぐらいの１時間換算になるんじゃないかというふうに思っております。それから、蛇崩川につきましては、これも同じような考え方ですが、５１ミリということで観測しております。","id":"exchange-031"},{"speaker":"松澤委員","kind":"質問","question":"私は地元の下水道の戸越幹線があふれたものですから、その状況を見たいなと思ったら書いていないんですよね。書かれていないとわからないんですよ。","respondent":"久保田防災課長","answer":"今回は時間がないということで、大まかに４地区に分けた形での被害状況というのを累積したです。戸越幹線周辺について何件あったかということは、私どももこれは集約するつもりですので、そういうことでご理解いただきたいと思います。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"３００円、そのぐらいで１キロ、これは効率的なのかどうなのかなというのがちょっと思ったのが１点。当初５円で予定していたので、予算的には大分変わってくるのかなというのが、どのくらい変更になるんか尋ねました。","respondent":"金井環境課長、中山清掃リサイクル課長","answer":"先ほどちょっと説明が不足いたしました、１日にたくさん集まれば、中の使用しているものを取りかえてストックヤードも必要になってまいります。これから１０月からやりますと、半年で３,０００万円余の予算があるわけですが… 今回の仕組みの検討に当たって独自の回収ということを考えたわけですけれども、先ほど環境課長がご説明申し上げたとおり。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"本来は５分の１になるのかなという意味でちょっとお聞きしたんですけれども。どこがこれを負担するのかなというのが、それがご説明なかったと思ったので、それもちょっと説明を求めました。","respondent":"金井環境課長","answer":"内容としては新しいもので、３分の２が区が補助する予定で、３分の１は区商連が負担をしていただくというような形で調整をしています。基本は２分の１負担、区商連と私どもの２分の１の負担という考え方です。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後に要望です。各商店街に一つは増やしていっていただいて、効果のあるレジ袋の運動にしていただきたいなということで、それを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３地区というふうな、二、三台ということですよね。そういうふうな参加する商店街すべてに使わないということなんでしょうか、そこのところを一つ教えていただきたいのと、それについてちょっと。","respondent":"金井環境課長","answer":"今回、ノーレジ袋運動だけは参加したいというのは７から１０と考えていただければよろしいかなと思うんですけれども、そういう内容になっているです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この８４トンが０.０１％というのは、レジ袋が使われているところの０.０１％というものですか。結局そういうふうな形で集まってくるわけですから、およそ８４トンが減るんじゃないかという、そういうことなんか尋ねました。","respondent":"金井環境課長","answer":"５グラムとか、１枚をカウントして計算すれば出ますけれども、その枚数だけで。できるだけ出していきたいというふうには思っておりますけれども。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"商店街で配るわけですから、実際に区商連から何枚と、何枚配ったかというふうなところではわかるのかなというふうに思うんですけれども。これが平成１６年までの３カ年として、また続けて実施するということで考えているのか、そのところをお願いします。","respondent":"金井環境課長","answer":"助成がずっと助成をすべてを続けていかなきゃいけないということは、それは本当の助成ではありませんので、そうしたことも含めて考えていきたい。事業的にはだめな方向ではなくて、前向きに発展的に考えていきたいというふうに思っております。","id":"exchange-038"},{"speaker":"松澤委員","kind":"質問","question":"今日の明日ということけれども、委員長、副委員長からこういうものはというのはないですか。今急に示されたものですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"５ページに出ていますけれども、当然今まで要望しているでしょうけれども、その辺のところをどういうふうに要望していくのか。その辺、中小企業対策という意味で載せていただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"三上委員","kind":"質問・要望","question":"内容を伺いたいんですけれども、９ページにある戸籍事務のコンピュータ化に関する要望書の中で、品川区の見解はどういうことなんでしょうか。そこらあたりどうか尋ねました。","respondent":"冨田戸籍住民課長","answer":"戸籍のコンピュータ化は平成６年からの法律改正でできているんですけれども、それ以外の補助金という形ではございません。国も推進している事務ですので、従来から戸籍事務のコンピュータ化についての財源措置をするように、国等へ要望は出してきているところです。","id":"exchange-041"},{"speaker":"三上委員","kind":"質問・要望","question":"コンピュータ管理というのはどの程度までコンピュータ化、具体的に言って、今の求めている１００％こういう形だということについての、今品川区はどこのくらいまでいっているのかという、そこらあたり。","respondent":"冨田戸籍住民課長","answer":"平成１４年度につきましては、それを業者のほうで機械にできるように入力作業をするわけですけれども、それを１０月ごろを予定しております。住基ネットにつきましては、開発経費ですけれども、大体５,０００万円ほどを予定しておりました。","id":"exchange-042"},{"speaker":"三上委員","kind":"質問","question":"緊急地域雇用特別交付金、これは平成１４年度ということになっていたんですけれども、これは区民委員会所管のほうで関係することはありますか。産業振興課長のほうか尋ねました。","respondent":"市川産業振興課長","answer":"ご案内のとおり、適用される事業が幾つかあります。今年度に例えばＩＴ講座関係のものがある程度事業を継続するという見込みは立ちますが、私どもが所管している事業にしても、継続性のあるものと。","id":"exchange-043"},{"speaker":"三上委員","kind":"質問・要望","question":"そうすると、あまりこれは、これは何か平成１５年度に継続してくれという要望だったらいいんだけれども、単年度でやってきているものだったらね。","respondent":"宮地区民課長","answer":"向こう３年間はやはりぜひつけていただきたいというふうな姿勢でおりますので、できることでしたら、そういった要望を出していただくと助かります。","id":"exchange-044"},{"speaker":"三上委員","kind":"質問・要望","question":"では、それなりに、これから２３区の委員長会でも要望していくということで。","respondent":"南委員長","answer":"ちょっとほかになければ、後で正副で整理をさせていただきたいと考えていますが、それでいいですか。","id":"exchange-045"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ちょっと一つだけいいですか。そこからうだつに行くときに時間が慌ただしかったら、電車の中で食事でもいいんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2338#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":54535,"voices":125}},{"id":"h14-20020820-7","meetingId":"h14-cm08","date":"2002年8月20日","dateIso":"2002-08-20","committee":"厚生委員会","time":"午後１時０５分～午後２時４８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"２点お伺いしたいんですけれども、カリキュラムという意味でお答えをしていただきたいのと、この２点についてお伺いします。","respondent":"金子保育課長","answer":"昨年度から内部的な検討を始めていまして、指導課、そういったところと協議を重ねながら現在に至っております。現在保育士ならびに幼稚園教諭と協議しながらカリキュラムの最終的な詰めを行っているというふうに聞いているところです。","id":"exchange-001"},{"speaker":"築舘委員","kind":"質問","question":"そうすると、ほかの保育園で減ったところが出ているんじゃないかと思うんですが、その辺の状況はどうなのかということ。それから、０歳児はやっぱり相変わらず多いですけれども、ほかの０歳児でもこんなに申込者が多いのかどうかという点について質問します。","respondent":"金子保育課長","answer":"１歳児が２人、私立も含めまして約３,7００人の在園児がおりますが、転園は予想したよりも若干少なかったかなというふうに考えております。４番目ですけれども、現在８月１日現在ですと、なお待機児の方が増えつつあるという状況にあるというふうに認識しておるところです。","id":"exchange-002"},{"speaker":"築舘委員","kind":"意見","question":"幼稚園のほうですけど、これは学務課の担当ということで、ここには出ていないわけですけども、数がわかったら、４歳児、５歳児が従来と比べて増えたかどうかというところをお聞かせいただければというふうに思いますとの意見を述べました。","respondent":"金子保育課長","answer":"幼稚園のほうの新たな申し込みというのは私どもで聞いてございませんが、それとストレートな答えではないんですけれども、幼稚園のほうで預かり保育を実施するようになりますが、それについての問い合わせが今何件か来ているというふうなことを聞いております。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと、さっき築舘委員の質問のところでの答弁で聞き漏らしたんですけども、ほかの園からの転園の人数をちょっと改めて聞かせてほしいと求めました。","respondent":"金子保育課長","answer":"転園のご希望ですけれども、全体で４名、０歳児が１名、１歳児が２名、２歳児が１名です。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問・要望","question":"要望との関係でスタートしたばかりですけども、どういうふうな評価をされておられるのか、お聞きしたいと思います。","respondent":"金子保育課長","answer":"モデル的な実施というふうな位置づけをしていまして、４月から入園希望者も定数には埋まる、４月からは本格的な実施に向けて現在は助走段階というふうに位置づけているというふうに聞いております。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"２歳児、３歳児と、はっきり出すということはならないんか尋ねました。","respondent":"金子保育課長","answer":"ほかの園は０歳児から２歳児、３歳児から５歳児という括りになっていまして、先ほども説明申し上げたとおり従来からの括りで表現したです。","id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"そうすると、ちょっとよくわからないのは、職員の配置がここには出ていないんですけれども、子どもの数と職員の配置というのは、こういうふうな括りにすると、今までとはどういうふうに変わってくるのか、そこら辺のところはどういうふうになりますかとの意見を述べました。","respondent":"金子保育課長","answer":"実際の運営を園長のほうで運営がしやすく、なおかつ保育もしやすい格好でそれぞれのクラスないしはグループ単位で配置しているところです。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"質問","question":"やるということじゃないんですか、そこのところも含めて教育委員会と相談して決めるということなんですか。例えば、０歳児から２歳児のところもほかの園とここの二葉つぼみ保育園ではどういうふうに変わってくるのか、そこのところがちょっとよく見えない。","respondent":"金子保育課長","answer":"国の設置基準についてはそれを守らなければいろいろな指導検査の段階で引っかかって指導を受けるというふうな状態になります。国の設置基準を守りながら、そういう姿勢で私どもとしては協議してきましたし、そういう配置になっております。","id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問","question":"私が質問しているのは、ほかの園とここでは０歳児から２歳児というふうに括っていますけど、ほかの園とこの園では配置が変わってくるんですか。変わるんであれば、どういうふうに変わるんですかということを聞いているんですけど。","respondent":"金子保育課長","answer":"説明がちょっと足りないかと思いますけれど、例えば、あるいはその園によって預かる時間が短かったり長かったりする子どもの数が違ってきます。","id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"まだスタートしたばかりですから私もよくわからないんですけども、通称満足度調査というふうに私も聞いていたんですが、中でも。３２名新たに入園されるということで、今後のそういうところも含めた見通しはどういうふうになっておられるのか、お伺いしたいと思います。","respondent":"金子保育課長","answer":"昨年８月１日が１９５人、本年の８月１日が１９１人ということで、減っております。全国的にも待機児が増えている中で、今後ともこの待機児の動向に関しては、分析して調査しながら対応策を考えていきたいというふうに考えております。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"かなりいろんな就業形態も出てきて、やはりかなりそういう実態に、願いに沿えるようなところで増やしていただければなというふうに思います。今、課長の努力の方向でぜひ頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"意見","question":"この老人医療、医療全体は今回の内閣の重要４法案の一つだったんですけれども、こうやって改めて見ると大変だなというふうに実感をします。ニュース等では全体で国民の負担が１兆５,０００億円というふうに言われておりましたけども、そういうのは試算されておりますかとの意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"まだ区民の方が具体的にどの程度の影響が出るかというのは今試算をしているところで、まだ具体的に金額は出てございません。ただ、高齢者につきましては、年８,０００円の増になるというのが新聞報道によります変化です。","id":"exchange-012"},{"speaker":"宮崎委員","kind":"質問・要望","question":"お願いしたいと思います。これがどういうふうになるかというのは、こっちのほうはどうですか、試算はされていますか。","respondent":"蓼沼高齢事業課長","answer":"区のほうの医療費の支出については大体５,０００万円ぐらい、ごく粗い試算ですけども、マイナスになるのではないか。全般には国民健康保険あるいは乳幼児等も関係してきますので、ちょっと全体としてはまだ承知しかねております。","id":"exchange-013"},{"speaker":"宮崎委員","kind":"質問","question":"ほんとうは全体をちょっと聞きたいなというふうに思っていたんですけど、そうすると、老人医療だけで５,０００万円負担が減ると。それを逆に言うと、今のこの分が、負担が区民の方というか、区民のお年寄りにかかってくるのかなというふうに単純に言うとそうなるか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"先ほど申し上げましたけれど、まだ区民の方への負担については、今のところ数字をつかみかねている状況ですので、今歳出の規模で言いますと、あらあら今申し上げたような金額の動きがあるです。","id":"exchange-014"},{"speaker":"宮崎委員","kind":"意見","question":"これは今試算中ということなので、わかりました。低所得Ｉのほうは、低所得IIというのは１５％というふうな括りは出ているんですけど、具体的にどんな感じになりそうかというのはわかりますかとの意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"まだ検討中であるですので、これにつきましても、今のところ具体的な明確な数字は出ていないです。その主たる生計維持者が非課税というのが従来のIIのほうの考え方、これが制度が新しくなりますと、世帯全員の方が非課税ということになります。","id":"exchange-015"},{"speaker":"宮崎委員","kind":"質問","question":"低所得IIというのは、非課税世帯ですか。私どもはかなり受診も減るとか、そこら辺のところの区の見解というのはどんなものか、ちょっとお聞かせいただければというふうに思います。","respondent":"蓼沼高齢事業課長","answer":"今回の医療制度改革は、国全体で今の保険制度を維持しようということで取り組まれたものです。","id":"exchange-016"},{"speaker":"山路委員","kind":"提案","question":"高齢者福祉の行事に関しまして、お祝い事業の中のシルバー成年式が第１０回と書いてありますけど、２階の後ろの部分が大体いつもあいているんですね。非常に積極的で品川区から声がかかったら早川町の方も行きたいというような旨のご提案を申し上げましたけど、今年可能かどうかとの意見を述べました。","respondent":"新美保健高齢事業部長","answer":"早川町との交流、今後も従来のやり方を見直しつつ検討していくというご答弁をさせていただいたかと思いますが、ということで。引き続きの検討課題です。","id":"exchange-017"},{"speaker":"山路委員","kind":"提案","question":"約１年たちますので、反面期待をして今日お伺いしたんですが、検討していないということですよね。もっといろんな意味で友好が深まるという視点からご提案申し上げたんですけど、ぜひ検討してほしいと求めましたが、もう一度ご決意のほどをとの意見を述べました。","respondent":"蓼沼高齢事業課長","answer":"早川町との交流というご趣旨ですけれども、今年度につきましては、１０周年ということで少し趣向を凝らしまして企画をしています。それらを含めまして、今後成年式が実りあるイベントになるように検討してまいりたいというふうに考えております。","id":"exchange-018"},{"speaker":"山路委員","kind":"質問・要望","question":"今年は１０周年ということですので、その一環として品川区の７０歳の方に限られていますので、さらに検討してほしいと求めました。どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"築舘委員","kind":"質問・要望","question":"商品券ですか、数字がわかればそれぞれ教えていただきたいということと、それから区と社会福祉協議会が共催になっていますね。社会福祉協議会なら社会福祉協議会でもいいのではないかなという気も私はしたものですから、こういうふうになっているのかということですね。","respondent":"蓼沼高齢事業課長","answer":"すみません、年齢で対象者を選定したということで、介護保険で受給しているか否かについては把握をしてございません。一緒にやりましょうということで１００歳と白寿に高齢の方のほうになったんではないかなというふうに、ちょっと詳しいことはわかりかねてあります。","id":"exchange-020"},{"speaker":"築舘委員","kind":"質問・要望","question":"社会福祉協議会から２万円出していますというのは、受け取る側はわからないんですかね、そうじゃない。そこを少しはっきりさせておかないと、ちょっとまずいんじゃないかなと思ったものですから、その質問をしたんです。","respondent":"新美保健高齢事業部長","answer":"ここにありますような形で、行政はこの部分を、現時点でこのような形で役割分担と共同実施を整理したということでご理解いただければと思います。今後どういう形が一番ふさわしいのか、いろいろ検討してまいりたいと考えています。","id":"exchange-021"},{"speaker":"築舘委員","kind":"意見","question":"百歳訪問ということになっているわけですけど、ほかの９９歳の方以下８０歳までの方にしても、訪問していることは訪問しているわけですよね。ここだけ取り上げて訪問事業というふうにするのがいいのかどうかというようなこととか、まとめていただいて、ご意見を申し上げましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"金高委員","kind":"質問","question":"これが同じ日に重なっているのがちょっとどうかなという感じがしたんですけど、その日でなければいけないような何か理由があったのかどうか１点。もしあれば、留意点などを含めてのどういう体験発表の仕方をしているか、その辺をちょっとお聞かせ願いたいんですが。","respondent":"蓼沼高齢事業課長、早津高齢福祉課長","answer":"年齢的にはもちろん重複する７０歳のところもあろうかと思いますけれども、年齢によって分かれているというふうに考えてあります。敬老の日の集い、これらはシルバーセンターの利用者が自主的に実施をするものですので… どういう機会から介護が始まって、どういうようなサービスを受けているかというようなお話を体験に沿って発表していただいているものです。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと細かいこと２点なんですけども、確認しておきたいんですけど、１点は、百歳訪問は区長および社会福祉協議会会長等が訪問となっています。ざっとこれを足すと４,０００近くになるのかなと思うんですけど、ちなみに、民生委員一人当たりで何軒ぐらい訪問するようになるんか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"ざっとの数字ですけれども、約４,０００人に対しまして、民生委員が３００人弱ということで、割返しますと、大体１２名ぐらいの方にお配りしていただくということになります。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問","question":"社会福祉協議会なんですか、区長になるんですか、どっちになるんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"民生委員につきましては、これは区のほうの推薦等がありますけれども、これを任命するのは国の厚生労働大臣が任命すると、そういうことです。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"それぞれ民生委員が、ちょっと言葉は適当でないかもしれないですけど、民生委員が駆り出されるということになるんですよね。そういうことが可能な、そういうラインになっているのか、そこら辺のところはどういうふうになっているんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"それから、特に品川区につきましては、高齢者相談員ということで、民生委員と兼務をしていただいております。それぞれ区の立場、社会福祉協議会の立場、それぞれの立場からいろいろお願いを申し上げているです。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"質問","question":"区のほうは区のほうでいっぱい来ると。そこら辺の、どういうふうに仕事が行くのかというのがちょっとイメージがわからないものですから、基本的なところを聞いているんですけど。","respondent":"日下部障害者福祉課長","answer":"協議をした上でいろいろな活動の従事について具体的に進めていくということでお願いを申し上げているというのが１点です。区のほうといたしましても、定員の拡大ということで、できるだけ労力について軽減するということで努力を進めてきているという状況です。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問・要望","question":"２人の上司を持っているような、そういう感じになるのかなというふうに思ったものですから、そこのところでちょっと基本的なところを聞いたんです。これは通常は３時、４時の間ですよね、この日は営業を拡大するとかということなんか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"営業の時間を拡大するということではございません。そのような事業を実施していますけども、提示していただくことで、その営業時間内については営業時間終了まで２００円で入浴ができるというものです。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問","question":"今、この資料で１５日の日はこういう２００円で入浴という、これ自身はこの２００円で入浴できるというのが浴場組合の自主事業ですよね。そうすると、そういうところに浴場組合というのが普通入るんじゃないのかなと思うんですけど、この辺のところはどういうふうな関係なんか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"この敬老の日につきましては、あくまでも浴場組合の自主事業ということで、ここの表の表記の仕方の問題かもしれませんけれども、一応こういうような高齢者に対するサービスが区主催ではございませんけれども、ありますということで、参考までにお知らせをするというものです。","id":"exchange-029"},{"speaker":"金高委員","kind":"確認","question":"先ほど商品券のことが出ておりましたけど、この商品券の内容なんですが、いわゆる一般商品券なのか、デパートの一般商品券なのか、あるいは区内で出ております、要するに区内共通商品券なのか、その違いだけ確認しておきたいんですけど。","respondent":"蓼沼高齢事業課長","answer":"この商品券につきましては、区内共通商品券です。","id":"exchange-030"},{"speaker":"横山委員長","kind":"質問・要望","question":"前回の委員会で、今年度は品川区議会厚生委員会といたしまして、本年で３年目に入りました介護保険についての要望を出させていただきました。要望事項といたしましては、低所得者に対する介護保険料の軽減措置を求めるということで、国ならびに東京都に要望していくという結論に達し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":27218,"voices":86}},{"id":"h14-20020820-8","meetingId":"h14-cm08","date":"2002年8月20日","dateIso":"2002-08-20","committee":"建設委員会","time":"午後１時０５分～午後４時２６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"これは、どういうことでこれだけ台数が増えたのか、その辺の内容を教えてください。２１日に広報しながわに受付の開始をお知らせするということなんですけれども、私、広報の仕方についてお尋ねしたいと思います。","respondent":"奈良交通安全担当課長","answer":"そこでいろいろ検討した結果、定期利用と当日利用を一緒にしますと、非常に台数が不足します。これは６月２１日号で既にお知らせをしてありますし、あるいは現地でいろいろな看板、これで十分区民の方への周知は徹底されるものと考えています。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"意見","question":"私、今日ちょっと五反田駅に用事があったので、自転車で駐輪場を利用してきたんですけれども、夏休みにもかかわらず満杯状態だったんです。","respondent":"奈良交通安全担当課長","answer":"そうです、変わりありません。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"既存の収容台数の出し方というのは、どういう算定の仕方をしているのか、その辺も教えていただきたい。利用者の皆さんの意見を聞いてほしいという要望を出したわけですけれども、期日的なものも当然やるんですけれども、開設が１０月１日ですよね。","respondent":"奈良交通安全担当課長","answer":"そうしますと幅が３８センチということで、１台逆分がとられるということで、今回そういうことでさせていただきました。説明が一緒になると思いますけれども、現地でのいろいろ看板とかチラシ、区民の方には十分周知徹底が図られるというふうに考えております。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"意見","question":"既存の収容台数の算定のところが、どういう基準かなというがわからなかったんです。その辺をお願いしますとの意見を述べました。","respondent":"奈良交通安全担当課長","answer":"これは利用される方がきれいにとめていただければ、例えば五反田駅ですと３８０台まで収容は可能ですということなんです。それが、いわゆるそういった機械の設備を入れますと、５４２台まで増やすことができますということです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"現実に今置かれている台数よりも少ない台数、その点では今よりもなおあふれてしまう台数が多いのではないかという心配をしています。その辺はいかがなんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"五反田駅につきましてはマイナス３７台ということで、十分とは言えませんけれども、それなりに台数は確保できたと考えています。それから、今回有料化することによってそういった方たちが自粛していただければ、そのマイナス４６７台が大分解消されるというふうに考えております。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"今、本当に自転車の利用が増えているので、有料化によって自粛するということですが、現にもう有料化になっているところが何カ所かありましたが、それでその辺の効果というのはあらわれているのか尋ねました。","respondent":"奈良交通安全担当課長","answer":"昨年の９月から大井町と大崎について有料化を実施しておりますけれども、そういった有料化した場所については、私も時々まいりますけれども、歩道上にとめている自転車がゼロとは言いませんけれども、大分効果は出ているというふうには認識しております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう１点、今シルバー人材センターの職員が配置されていて、大変一生懸命並べていただいているんですが、これが有料になって、委託になるんですよね。その管理の仕方についてと、今のシルバー人材センターの職員が今後どういうふうになるのか、その辺を教えてほしいと求めました。","respondent":"奈良交通安全担当課長、中谷まちづくり事業部長","answer":"今回１０月から実施します５駅については、どこに管理委託するかはまだ決まっておりませんけれども、昨年度実施しました大井町と大崎につきましては。大井町、今回の５駅につきましても… 広報はもう既に配布になっていてごらんになっている方もおられると思うんですが、実は８月４日の浸水の関係で、その広報が臨時で上に載りました。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ＪＲとか東京急行とか京浜急行とか、鉄道事業者にもうちょっと求めてもいいんじゃないか、その辺はかなわないものなのでしょうか。初歩的な質問なんですが、お答えほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"学生の学割利用の件につきましては、大体皆さん方１０分以内で通学ができるような状態ですので、現在のところでは学割については考えておりません。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっとずつの積み重ねが結構生活に響くというところもありますので、利用料を本当に極力安く抑える方向を追求してほしいと求めました。以前に要望を出したということで、第３駐輪場の月極めのところが、その辺どうなっているか答えてほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"それに対しまして、当日利用される自転車の方、あるいはバイク利用をされる方に第３駐輪場を何とかならないかというお話がございました。今、私どものほうも事務局を通じて何とか試験的に運用してみようかなと検討しています。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"あるいは違法駐輪の撤去の頻度を高めるというんでしょうか、それらの対応は今回を含めて変わるのかどうか、その辺の考え方をお聞かせほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"今、委員のご指摘のございました駐輪禁止区域の拡大等につきましては、現在、私道部分、いわゆる民有地にとまっている自転車も結構あります。１０月１日に整備を図りますけれども、今検討しておりますので、よろしくお願いしたいと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"区域の拡大とともに、その対応というんでしょうか、ぜひ強化をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"この辺の区分けというか、どういうものを整備センターにやらせて、どういうものを民間にという区分けがあるのであれば教えていただきたい。昨年度有料化された大崎と大井町ですけれども、最初の時点での申し込みで外れた方というか、抽選から漏れた方の台数がわかれば教えていただきたい。","respondent":"奈良交通安全担当課長","answer":"１点目の、来年度をもって一応この事業は終了する予定ですけれども、いわゆる５カ年計画の期限が切れて区のほうに返還される予定になっております。それから、昨年度実施しました大崎駅の抽選漏れの関係ですが。","id":"exchange-012"},{"speaker":"菊地委員","kind":"意見","question":"現在、この５駅を除きますと、無料の駐輪場がまだ十幾つありますよね。３カ年計画の中で来年度、あと十幾つはすべて区で整備して有料化するのかどうかとの意見を述べました。","respondent":"奈良交通安全担当課長","answer":"来年度実施する駅は、予定ですけれども、平成１５年度は新馬場、それから大井競馬場、この２つの駅を予定しております。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問・要望","question":"大井町、当然通勤・通学に利用するということで申し込まれたんでしょうから、その辺の数字というのは後ほどでも結構ですので教えていただきたい。要望ですけれども、私は実際に抽選に漏れる方がいらっしゃるのかどうかというのは、その辺の見解があれば教えていただきたい。","respondent":"奈良交通安全担当課長、中谷まちづくり事業部長","answer":"それから、大崎駅の抽選漏れした方の数字は把握しておりませんので、今後お持ちしたいと思います。若干まだスペースがありますので、そういったところを利用すれば十分賄えると思いますので… 抽選のことを私のほうからちょっとご説明しますと、抽選に漏れた方があります。そういうことで、区内も対策を順次とってまいりたいと考えております。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"３,３００円、定期利用の場合は２,０００円ということですけれども、そういう措置というのはできないものなんでしょうか。最寄りの駅まで１０分ぐらいだとはいえ、実際に自転車は皆さん使っているわけですから、その辺はどうか尋ねました。","respondent":"岩田管理工事課長","answer":"１つは、議会にもよくご説明申し上げましたけれども、鉄道駅の状況から少ないという判断が大前提です。確かに、朝の１０分は貴重ですけれども、我々の検討課題の前提です。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問・要望","question":"皆さん、現実の問題として至るところであふれ返っているわけですから、対策としてもう一回り利用者のことを考えるようなものが必要なのではないかと。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"来年が２カ所ということですから、あるいは建設委員会だったでしょうか、あそこはシルバー人材センターの方でしょうか。ですから、あえてつけ加えさせていただければ、できるだけ早い時期に何とかしてほしいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"船波委員","kind":"質問","question":"三ツ木保育園ほか、西品川地域でも被害が出ていることになっていますけれども、西品川地域は、水害対策ということでつい最近まで工事をしていたと思いますけれども、その水害対策の地下につくった大きな池の効果というか、運用はどうなっているんか尋ねました。","respondent":"矢部下水道河川課長","answer":"西品川の西品川公園雨水調整池なんですけれども、８月４日の降雨の後確認しましたら、満杯に入っておりました。それがいい効果を発揮しているというふうに考えております。","id":"exchange-018"},{"speaker":"船波委員","kind":"質問","question":"８月４日のこれだけ被害が出たときのあの雨が雨水調整池に流れ込んでいっぱいだったということで、でもこれだけ被害が出たということは、地下につくった大きな池に水がたまり、なおかつもっと雨が降ったから、これはしようがなかったということなんか尋ねました。","respondent":"矢部下水道河川課長","answer":"それで、雨水調整池につきましては、２,４００トンの貯留容量があります。さらに１００ミリという豪雨の中で、浸水被害が起きてしまったというふうに考えております。","id":"exchange-019"},{"speaker":"船波委員","kind":"質問","question":"降っている間でも川にどんどん流して、西品川のあたりの水がたまりやすい部分の水をもっと吸収できるようにするとか、そういう運用面で何とかならない部分はないんか尋ねました。","respondent":"矢部下水道河川課長","answer":"その中で、平成１１年８月に豪雨がございまして、被害が出ました。なので、雨が降っている間につきましては、たまった水は、それ以上は入れられないというような状況になってしまいます。","id":"exchange-020"},{"speaker":"船波委員","kind":"質問","question":"そうすると、西品川の地域でこの雨水調整池に２,４００トン入っていっぱいになってしまうというのは、どれくらいの雨量なんでしょうか。１時間６０ミリを超えたりとか、あるいは最大瞬間雨量で１０分間１７ミリというか、もう防ぎようがないということなんか尋ねました。","respondent":"矢部下水道河川課長","answer":"それを上回る豪雨に対しても雨水調整池があったはずだというふうに私のほうでは考えているんですが、結果的に浸水被害は起きてございません。ですから、やっぱり１００ミリを超える豪雨というのは、どうしても低地のほうに集まってしまうのではないかというふうに考えております。","id":"exchange-021"},{"speaker":"船波委員","kind":"質問","question":"８月２日の金曜日の雨で、その５００トンは８月４日の夜に雨が降るまでの間、どれくらい流せていたのでしょうか。流せていなかったのか尋ねました。","respondent":"矢部下水道河川課長","answer":"先ほど申し上げましたように、戸越幹線にポンプアップして流さなければいけないものですから、戸越幹線の水位が下がらないと排水できないんです。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"水位のこともあるでしょうけれども、土曜日にお休みだったからポンプをあけたりすることができなかったので流せなかったということもあるんですか。１回目の雨が降った次の日にでも、次の雨に備えてもっと調整池の容量を大きくあけておくことはできるということなんか尋ねました。","respondent":"矢部下水道河川課長","answer":"確かに委員おっしゃるとおり、下水道局も夜勤体制とか休日出勤体制をとっておりませんので、結果としてそういうふうになったと考えております。","id":"exchange-023"},{"speaker":"船波委員","kind":"質問","question":"これ以上工事をするということはできないでしょうから、もしできれば、そういう運用をしていただけたらと思います。そうじゃないと、何かみんな疲れ切っていると思うので、そういう運用の面で何とかできるものがあればお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"堺委員","kind":"質問・要望","question":"ですから、あそこで出てきた要望をぜひ、おれたちで何とかするぐらいの話になりましたよね。あのときできれば今後の対策としてこういうふうに対応していきますというようなことを書面で回答してほしいというような要望もありましたよね。","respondent":"矢部下水道河川課長","answer":"１つ、そのほかの対策がないかということで説明会の中で言われた経緯もありますけれども。その辺のことも踏まえまして、今後下水道局のほうと協議してまいりたいというふうに考えております。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"そういうものがないのかどうかというのを１つお聞きしたいのと、あそこは土地として一段低くなっているような感じになっているんですか。今第２立会川幹線の工事が始まっていますけれども、実際問題としてできるのかどうか、ちょっとその辺をお聞きしたいです。","respondent":"矢部下水道河川課長、田村住宅課長","answer":"それで、桟橋工事、仮駐車場の工事ですが、それが今年度いっぱいで終わる予定になってあります。その後、シールド２.７キロありますので、どうしても３年、４年とかかってしまうというふうになっております。 数件ということで、最大フローリング２センチから５センチぐらい床が浸水したというような状況がありました。基本的にはないとは考えておりますが、原因、あるいは改善策について現在調査を進めている状況です。","id":"exchange-026"},{"speaker":"菊地委員","kind":"質問・要望","question":"どうやればこの工事を１日も早く、１年でも早く進められるのかという東京都との交渉というのは現実にやっていただきたいし、その辺での見解があれば教えていただけますか。","respondent":"矢部下水道河川課長","answer":"第２立会川幹線なんですけれども、下水道局のほうから説明を受ける範囲内では七、八年程度かかってしまうのかなというふうに聞いてあります。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"その７年、８年の間はどうしていくのかというのは、その辺の対策があるとすればお願いできますか。","respondent":"矢部下水道河川課長","answer":"例えば、そういう形の対応も考えるかと思うんですけれども、やはり立会川幹線の上流部分から一気にバイパスを伝わって海まで持っていってしまうと。そういう形で下水道局のほうとは抜本対策ということで工事をお願いして、今回工事に着手したという経緯があります。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問・要望","question":"なかなか私も、何が当面の有効な手段なんだというのはよく考えつかないところですけれども、ぜひ努力をしてほしいと求めました。最後にもう１点だけ、先ほど言っていた逆止弁ですか、そういうあれはありますか。","respondent":"矢部下水道河川課長","answer":"それについての補助というのは今はないんですけれども、排水管渠の改造とか、新築をするときにそういう設備をつけるとか、そういう形になってしまうというふうに考えております。","id":"exchange-029"},{"speaker":"本間委員","kind":"質問・要望","question":"５０年に１回とか、その後東京都へ直接陳情に伺って、着々を善処と進められているというふうに思います。そのかわり、私たち役所のほうに連絡をとれば役所のほうでやりますというのと薬品の中身は同じなんでしょうか、どうなんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ教えてください。あれ以降の入館者数というのはどれぐらいなんか尋ねました。","respondent":"松代道路公園課長","answer":"ただ、４月以降、周辺の水族館等もすべて同様なんですが、少し落ち込みを見せております。そういった中で、今回の１,０００万人を達成しましたことをもって、さらにＰＲをして来ていただければというふうに努めているところです。","id":"exchange-031"},{"speaker":"堺委員","kind":"質問","question":"それぞれ、教えてほしいというふうに投げて、そして当日そのことについて教えてもらったというふうなことだったと思うんです。その前提になるのは、今回計画されている中でも、そのように、限られた時間の中での効率的な委員会の運営というんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"本間委員","kind":"質問","question":"質問するには、ちょっとこのようにして事前研究していかないと、いざというのはあります。この資料の件で、姫路と神戸はあるんですけれども、大阪に関しての資料はありましたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"本間委員","kind":"質問","question":"そうですか。どこの委員会もやっていると思いますけれども、そのほうがいいんじゃないか尋ねました。","respondent":"北野委員長","answer":"次回の９月の委員会で、よろしくお願いしたいと思います。次回の委員会では、宿泊先など細かい日程が出されますので、よろしくお願いしたいと思います。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3732#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":29988,"voices":94}},{"id":"h14-20020820-9","meetingId":"h14-cm08","date":"2002年8月20日","dateIso":"2002-08-20","committee":"文教委員会","time":"午後１時０５分～午後３時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"の施設予約システムの導入","agenda":"の施設予約システムの導入","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"パソコン、携帯電話なんかも全然ない方との整合性というのは、どういうふうに考えてられていらっしゃるのかということが一つ。ものによっては従来どおり事前にお金を払うとか、なかなかの飲み込みにくいものですから、もう一度わかりやすく説明してほしいと求めました。","respondent":"上川内生涯学習課長","answer":"白書では、人口の３７％がパソコン、インターネットを利用していると出ています。二度、三度と足を運んでもらわなきゃなりませんので、口座引き落としにしたものです。","id":"exchange-001"},{"speaker":"中島委員","kind":"確認","question":"でも、パスワードだけだと、どこのだれかわからないということもあるんじゃないかと思うんです。パスワードを登録するときに、相手の身分はどうやって確認するんか尋ねました。","respondent":"上川内生涯学習課長","answer":"登録団体には、ボランティア登録団体とかいろいろありますから、その番号とパスワードが一致することというのは滅多にない言われているんです。ですから、どこかの団体のだれかと一緒になるということはほとんどないと考えています。","id":"exchange-002"},{"speaker":"中島委員","kind":"質問","question":"くじの場合も、同じですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"確認をさせていただきたいんですけれども、今まで、ホール系なんかで、くじ引きをやっていましたよね。そういう措置は、今度は、到着順になるとか、そういう形になるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"それと同じように、２１日から月末までの間に、インターネットなり、窓口なりで予約をしてもらいます。抽選は同じです。","id":"exchange-004"},{"speaker":"石田委員","kind":"質問","question":"ちょっとお伺いをしたいんですが、１週間ぐらいのスパンを逆に切って、来週１週間の平日の空き情報を出す。これだけ情報を公開するんであれば、モデル的でもいいけれども、せっかくここまでやるんなら、そういうことをやってみたらいかがかなという質問です。","respondent":"上川内生涯学習課長","answer":"まだ空いているところは、使用前の１カ月後に、今度、一般利用の予約をします。ですから、委員おっしゃるような使い方も可能だということです。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"その次の１週間は、きょうのきょうという形で予約を取らない。こういう教育的な配慮の中で、１週間前に切るようなことをモデルケースとして、考えられたらどうですかということです。","respondent":"上川内生涯学習課長","answer":"わかりました。それはまた、違う検討課題なので、今後、検討します。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"それぞれの施設から、その施設以外の申し込みというのは、端末を置いて窓口でできるようになるのかどうか。ちょっとそこら辺を教えてほしいんです。","respondent":"上川内生涯学習課長、指田教育次長","answer":"本格稼働は４月からなんですが、４月実施からは、詰めております。これから、今後、そこら辺の集会場系の仕組みは検討して……。 今、お話があったような形は、基本的にはないとお考えいただければと思っています。そして、一つのチームが二つも三つも取ろうという機会均等を逸脱するような形を取るとすれば、これは罰則をもって対応していきたいと考えています。","id":"exchange-007"},{"speaker":"沢田委員","kind":"確認","question":"現実に、そういうことをちょっと聞いたんですけれども、ほんとうにないんでしょうかということ。もう一度確認なんですけれども、来年の４月以降は、すべて申し込みが可能だと判断していいかどうか。","respondent":"指田教育次長","answer":"基本の考え方は、今、私が言ったような考え方で一つを整理をしておいていただければ結構だと思います。それから、二つ目の、各窓口でのインターネットの取り扱いについては、当然のことながら、どこの施設でも置いてあるとお考えいただきたいと思います。","id":"exchange-008"},{"speaker":"原委員","kind":"確認","question":"もう一つ確認したいんですが、今のつながりで、目的を一つにする団体の中に、いろいろな団体が入ってくる場合がありますよね。それはまた、今回、インターネットでも可能な形になりますか。","respondent":"指田教育次長","answer":"言われている話というのは、一つのものを、幾つかの目的を同じにする団体があって、そこが取って、その後、肩代わりするというものですか。","id":"exchange-009"},{"speaker":"原委員","kind":"意見","question":"肩代わりというかどうかわからないけれども、目的を一つにする団体がありますよね。窓口のサービスからいったらどうなのかという部分もありますけれども、今回も可能になるかどうかということだけ、ちょっとの意見を述べました。","respondent":"指田教育次長","answer":"やはりきちんとした団体なら、そして、あとはほかの人たちを呼ぶなら呼ぶという形のきちっとしたルールを団体の中で整理をしていかなければいけない。もしそういうところが見つかれば、当然のことながら、是正の方向に持っていきたいと思っています。","id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ聞いていいですか。数字だけ教えていただきたいんですが、グラウンドを取るチーム名というか、登録をされているチームの数というのは幾つぐらいあるんか尋ねました。","respondent":"上川内生涯学習課長","answer":"野球だけでカウントした数字はちょっとわからないんですが、公園運動施設利用団体は３,７００あります。テニスと、野球と。","id":"exchange-011"},{"speaker":"高星委員","kind":"質問","question":"そういうふうにやっておられるんだと思うんですけれども、現実問題、そこでくじ引きをやっているんですか。最初に、それをお聞きしたいと思います。","respondent":"上川内生涯学習課長","answer":"ここの中の中小企業センターが施設でくじ引きをやっているということです。","id":"exchange-012"},{"speaker":"高星委員","kind":"質問","question":"中小企業センターだけがやっているということか尋ねました。","respondent":"上川内生涯学習課長","answer":"すみません、中小企業センターは全部貸し施設なので、集中するので、そこに集まっていただいて、くじ引き抽選をしているということです。","id":"exchange-013"},{"speaker":"高星委員","kind":"質問","question":"２４時間だとするなら、時計が夜中の１２時を打つのを待っていて、そういうことも可能なのかどうか。要するにシステムがよくわからないからあれなんですけれども、その辺、混乱が生じないものなのか、どうなのか、ちょっと説明を求めました。","respondent":"上川内生涯学習課長","answer":"本格実施の４月に向けて、空き情報につきましては２４時間対応で進めて、システムの安定を確認しながら進めていきたいと思っています。２４時間対応というのは、いつの時点で２４時間対応にするのかも、２４時間は対応するように。","id":"exchange-014"},{"speaker":"高星委員","kind":"質問","question":"機械がどういう対応になっているのか、みんな用意どんで来るわけですから、アクセスはたくさん来ると思うんです。機械が耐えられるのかどうかも含めて、逆に混乱するようなことがないのかどうか、ちょっとお聞いておきたいと思います。","respondent":"上川内生涯学習課長","answer":"何カ月前の何日という対応する日ということに。３,７００団体の中で２０件程度ですから、ワールドカップのときなんかは数十万件でパンクしたというので、大丈夫だろうと思います。","id":"exchange-015"},{"speaker":"高星委員","kind":"質問","question":"要するに、土日、休日もそういう形になってくるというと、窓口はどういうふうに対応するんだろうということが出てくるんじゃないですか。こんなに広がった話になっちゃうと思うんですけれども、そういったことがないように十分にされているなら、自信と確信を持って言ってもらいたい。","respondent":"上川内生涯学習課長","answer":"土日対応の件ですが、基本的に、今までは、当該の施設の窓口でほとんどがやられていた。土日対応の体育館等、窓口の数も広がる、土日対応の施設もいけるというふうになります。","id":"exchange-016"},{"speaker":"中島委員","kind":"質問・要望","question":"今、地域センターのお話が出たので、関連してお伺いしたいんですが、地域センターというのは１カ月前に予約をすることができるんです。ですから、それは、ぜひ、事前に区民の人にわかるようにしていただきたいなと、これは要望なんですけど、お願いします。","respondent":"上川内生涯学習課長","answer":"それは、まさにインターネットの利点で、空き情報の確認に利用できる、それから休館日も入りますから、むだ足を運ばなくてもいいようになると思います。","id":"exchange-017"},{"speaker":"中島委員","kind":"意見","question":"例えば１カ月前だと、その以前にお知らせをしてくださるということですね、特別の場合は。わかりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問","question":"このシステムの導入のコストがどれぐらいかかるか教えていただけますか。それと同時に、ランニングコストがどうかということも含めて。","respondent":"上川内生涯学習課長","answer":"平成１４年度、開発と、１０月２１日からの初期経費を含めまして約７,２８４万円です。平成１５年度からのランニングコストは、これは見積もりなんですが、約２,５００万円。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"例えば、今申し込んだら、コンピュータ上の空き情報に、すぐに減１だとかいうふうにリアルタイムでいくわけですよね。実際には、どこかの業者か何かに委託するんじゃないかと思うんですが、そこら辺をもう少し詳しく教えていただけますか。","respondent":"上川内生涯学習課長","answer":"それで、情報システム課でできないときは、業者のほうに依頼をします。夜間とか、閉庁時間には、業者のほうに直接お願いするような方法をとりたいと思います。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"抽選をやってもいいし、早いもの順で決まったとすると、それを今度、受付け処理をする流れと、空き情報のほうを動かしていく流れとありますよね。２,５００万円と言いましたか、ちょっとよくわからないけれども、どうなんか尋ねました。","respondent":"上川内生涯学習課長","answer":"いろいろな細かい作業の管理は、情報システム課が行います。トラブルが発生したときには、それが本体なのかどこなのかわからないときには、業者に依頼していく形です。","id":"exchange-021"},{"speaker":"沢田委員","kind":"意見","question":"そうすると、問題が起きたときだけ業者に頼む、あとは情報システム課のほうで動かしていくということでよろしいんですね。わかりました、ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]},{"id":"topic-02","title":"の図書館インターネットサービス","agenda":"の図書館インターネットサービス","exchanges":[{"speaker":"高星委員","kind":"意見","question":"１時間以内に取りに来なきゃだめというのか、翌日でいいのか、その辺はどうなんだろうかということが一つ。その二つだけとの意見を述べました。","respondent":"志村品川図書館長","answer":"ご質問の１番目ですけれども、私が雑な説明で申しわけございませんでしたが、今はもう電話等で予約を受け付けてあります。システムをちょっとご説明しますと、その予約は、実は大井図書館に入ります。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"そうすると、予約をした方には、何か連絡が行くわけですか。何も来ないと、その人が来ちゃうかもしれないわけですよ。","respondent":"志村品川図書館長","answer":"私がさっき言いましたのは、たまたま今日の３時に予約を入れましたけれども、それの処理をしますのが翌日の朝を考えています。そうじゃありませんと、１日何回か開けようと思っていますけれども、今のところ様子を見てみようかと思っています。","id":"exchange-024"},{"speaker":"原委員","kind":"確認","question":"その確認する前にその本が出てしまうと、現場が優先するということになるわけか尋ねました。","respondent":"志村品川図書館長","answer":"例えば、リクエストにこたえるられる状態になったときに初めてインターネット上に、例えば「明日の９時からお貸しできます」という表示を出します。それで、１週間以内に取りに来ていただくということをお願いするということです。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"ですから、そのときに、「承りましたが、翌日にでも回答します」ということをそこに一言書いておかないと、行ってしまうと思うんです。その辺のところまで配慮していただけたらと思うんですが、どうか尋ねました。","respondent":"志村品川図書館長","answer":"ですので、逆に言いますと、３０の予約が入っていましても、翌日、全部貸し出しするという対応ができるとも限りません。お答えしたとおり、お手数ですが、もう一度インターネット上で確認していただくということになります。","id":"exchange-026"},{"speaker":"石田委員","kind":"質問","question":"１点お聞きしたいのは、臨時休館の期間ですが、１３日間だと思うんですが、結構長いなと簡単に思います。先ほどお伺いしたら、本の準備はある程度できているというお話だったんですけれども、その工事内容を教えてほしいと求めました。","respondent":"志村品川図書館長","answer":"５年間のリースが終わりまして、インターネット対応のシステムに変えていきますので、全部撤去いたします。それと、新しいシステムに対応できるような配線工事もこのときにやるつもりです。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ教えていただきたいんですが、１０月３日から９日まで、これは具体的にどういうことをするのか。７日間あるわけなんですが、どういう形のものにするのかとちょっと思うんです。","respondent":"志村品川図書館長","answer":"実は、７月だけデータを取らせていただいたんですけれども、今まで図書館でデータを取っていたのは、本の貸し出し件数をカウントしてございました。本の貸し出しの１.５倍の方が来館されていましたので、そういう意味では、この期間はこのようにさせていただきたいと思います。","id":"exchange-028"},{"speaker":"石田委員","kind":"質問・要望","question":"これで最後にしますけれども、ちょっと私が不勉強であったら教えていただきたいんですが、今まで、整理期間って休館してやっていたと思うんですよ。ということは、閲覧にしても、開けながらやれるということは、今までの整理期間も開けながらやれたということで考えちゃっていいのか、逆に言えば。","respondent":"志村品川図書館長","answer":"ご指摘にもありましたように、今回はちょっと長期間にもなりますので、この期間を最大限利用してやっていこうです。お客様がいますとなかなかできづらい作業もありますので、すみませんが、今回の場合は特例措置と考えています。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問・要望","question":"こちらも、ちょっと導入コストと、ランニングコストがわかったら教えていただきたい。その辺はどうなんか尋ねました。","respondent":"志村品川図書館長","answer":"今回の図書館のシステムの変更についてのコストですけれども、１４年度にかけて、およそ２,０００万円の経費でございました。平年度化いたしますと、まだ契約が終わってないんですけれども、今のところ予定しています金額が４,３００万円となります。","id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"今までのＯＰＡＣでも蔵書リストというのはあるわけですよね。ないんか尋ねました。","respondent":"志村品川図書館長","answer":"情報そのものはパソコンの本体に入っています。ですので、その本体そのものの情報を、今度、新しいシステムに移しかえるわけです。","id":"exchange-031"}]},{"id":"topic-03","title":"２の行政施設","agenda":"２の行政施設","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"そこら辺はどうなんですか。知っていたけれども出していないみたいなニュアンスにもとれるんですけれども、そこら辺はどうなのか、ちょっとお答え願いたいんです。","respondent":"鷹倉庶務課長","answer":"予算特別委員会は３月ごろで、今の時点までいっているわけですけれども、当時から、いろいろ下準備的なものが進捗していたような状況にありました。まだ具体的なスケジュールについては伏せておくのが妥当だと、当時も、そのように判断したです。","id":"exchange-032"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは未確認ですから、不正確だったら申しわけないんですが、その後に大林組が土地を持っているという話も、ちょっと耳にしたことがあるんです。それはもう１００％わかりますから、私は答弁をそれ以上求めないけれども、私はやっぱりまずいなと思わざるを得ません。","respondent":"鷹倉庶務課長","answer":"第２回定例会の一般質問でお答えしていますとおり、ボーリング計算をした後に、全体としては１万m2程度必要だという答弁を申し上げました。ただ、まちづくり事業部サイドとしては、その部分は当然入っていたわけですから、話が出たと、私どもは認識しています。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問・要望","question":"あそこは三井不動産が開発のコーディネート役をずっとやっているわけですから、また別の不安、そこはきちっとしておいてほしいということを。別にあえて答弁を求めるものではありませんけれども、これがあったんで、ちょっと触れてみました。","respondent":"鷹倉庶務課長","answer":"さらにそこからどういう形で全体像をえがいていくかという話は、当時、まだ進めていた段階です。その当時の状況を踏まえながらお話しされたのは、それはそれで適切であったと、このように判断しています。","id":"exchange-034"},{"speaker":"沢田委員","kind":"意見","question":"そんなのはないですよ。教育委員会は問題がなくて、事業部が問題だったというふうに聞こえて来ちゃいますよ、私にしてみればとの意見を述べました。","respondent":"鷹倉庶務課長","answer":"それぞれ役割分担の中でやっているわけですから。ということを、今、申し上げたわけです。","id":"exchange-035"},{"speaker":"沢田委員","kind":"質問・要望","question":"どれぐらい面積があるのか答えていただきたい」と言ったら、課長の答弁は、「個別の名称は出していないと思います」と。私が何かないものを空耳で言っているみたいになっちゃうじゃないですか、私のほうにしてみれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"沢田委員","kind":"質問・要望","question":"実態では、そうでなかったですね。その辺は反省をしていただきたいということを言って、これで終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高星委員","kind":"質問","question":"その土地の問題の見通しがない段階でも、開発研究校ということでの申請、許可というのは出てくるものなんですか。そういうものなのか、ちょっとその辺がわからないので、教えてもらいたいんですけれども。","respondent":"青木指導課長","answer":"第二日野小学校と日野中学校がそれぞれこの３年間、それが実際にどのような形で建つかということを前提に研究するものではございません。まさに純粋に研究のための開発ですから、それは条件になりませんので、関係ないと考えて構わないと思います。","id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"別のことでいいですか。従来のブロック別の学校選択にゆだねるという話、その方式でいくと言ったんじゃないか、違ったら指摘してほしいんですが。","respondent":"谷田部学務課長","answer":"検討をしてございまして、その後、９月の教育委員会のほうでご決定いただくという準備作業をしているです。ですから、それがはっきりするのは、９月１０日開催予定の教育委員会で、その辺の方向制についてご決定いただくです。","id":"exchange-039"},{"speaker":"沢田委員","kind":"質問","question":"それが事実だとすると、中学校の受入枠だけが全区的に募集で、一貫校には全区的に募集しないということになっちゃう。だけど、日野中学校の４０人の枠の中に受入枠をつくって、これについては全区募集をすることも考えているんだというふうにとらえていいんか尋ねました。","respondent":"谷田部学務課長","answer":"基本的には、従来からある通学区域のお子さんは、そちらのほうに希望すれば優先的に行かれます。それを超えた場合については抽選とか、そういう形で、ある程度制限せざるを得ないというような仕組みで考えているです。","id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"間違いなんですか。もう一度、すみません。","respondent":"谷田部学務課長","answer":"第二日野小学校の学区域の、来年、小学校に入学する予定の住民基本台帳上のお子さんというのは、現在、２５人つかんです。転入者の見込み等も含めますと、１０人前後ぐらいの受入枠を設ける必要があるだろうというふうなことで、作業をしているです。","id":"exchange-041"},{"speaker":"沢田委員","kind":"質問","question":"第二日野小学校だけ、日野中学校区の学校選択ブロックから外して、受入枠をつくると。今で言うと１０人前後ですから、３０人までは、学校選択の枠をつくるけれども、残る１０人については、別枠で全区募集するよという話でしょ。","respondent":"谷田部学務課長","answer":"そうしますと、それは希望選択じゃなくて、指定校変更という、後でやっていただく制度が別にあります。現行の小学校の選択制の範囲内で、第二日野小学校については、プラス受入枠を設けて考えていきたいです。","id":"exchange-042"},{"speaker":"沢田委員","kind":"質問","question":"それが、前回の説明で、重要な変更があったと。今の１０名の受入枠というのは、小学校については、希望しても小中一貫校に入れる道はないということにならないか尋ねました。","respondent":"谷田部学務課長","answer":"それは、小学校の数で言えば、全部でたしか１２校だと思います。だけれども、先ほど言いましたように、受入枠がありますから、その中で抽選するということになります。","id":"exchange-043"},{"speaker":"高星委員","kind":"確認","question":"確認の意味でちょっとお聞きしたいんですけれども、１学年１クラスだということになると、今でも余裕がありますよね。そういうふうに私は理解していたんですけれども、それ以降に変わったのかどうかわからないけれども、それをもう一度確認したい。","respondent":"谷田部学務課長","answer":"小中一貫校ができるから、将来を見据えて今のうちに転校したいというような場合にどうなのかというお尋ねだと思いますので、お答え申し上げます。小中一貫校ができるからというような理由で、安易に転校を認めるというわけにはいかないと、私どもは思ってあります。","id":"exchange-044"},{"speaker":"高星委員","kind":"意見","question":"そうすると、途中での転校、転入というのは、先ほどのケースに該当する理由でしか認めないけれども、入学時には、先ほど言った、住民基本台帳による数が４０人に満たないときには、その部分については、ブロック内からは取りますということで、理解していいのかなとの意見を述べました。","respondent":"谷田部学務課長","answer":"そのとおりです。","id":"exchange-045"},{"speaker":"石田委員","kind":"質問・要望","question":"教育委員会もこれからあるわけですから、本来の学校のあるべき姿だし、そういう本来の姿に戻るべきかなというような気もあるんです。要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鶴委員長","kind":"質問・要望","question":"平成１４年度特別区文教委員長会の要望につきまして、席上配付させていただきました案件を正副委員長で調整を図り、提出したことをご報告いたします。１点目は、ご案内のとおり、要望項目は、「道徳教育の充実をさら図られたい」。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"沢田委員","kind":"質問・要望","question":"ないでいいんですけれども、おそらくこれを当然読んでいるんでしょうけれども、どうなんでしょうか。１０年と言わずに、前倒しでやるべきじゃないのかなと思うんですが、答弁をお願いしたいと思うんです。","respondent":"鷹倉庶務課長","answer":"区の問題につきましては、学校改築資金の中で説明したとおり、一つの方向性は持ってあります。さらに詰める中で、今後、検討を進めていきたいと考えています。","id":"exchange-048"},{"speaker":"沢田委員","kind":"質問・要望","question":"１０年と言わずに、議会側でもこういう要望を出しているわけですので、前倒しでやっていただきたい。これはまた別の機会で取り上げる予定ですけれども、要望だけさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"高星委員","kind":"質問","question":"というのは、この時期にサマースクールをやるのは、やっぱりほんとうに大変かなと思うんですけれども、ちょっとお聞きしたい。考え方だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"高星委員","kind":"質問","question":"今、何校でやっているのかわからないけれども、将来的にはもっと拡大されるんですかと聞いている。質問が増えちゃったけど、二つ聞かせてください。","respondent":"青木指導課長、谷田部学務課長、指田教育次長","answer":"やはりこれはそれぞれの学校がいろいろな形で取り組んでいただいておりますので、やはり充実した方向に持っていきたいと考えております。すべての学校で、コンピュータ教室にはクーラーを入れてあります。いわゆる熱源があるということもありますので、クーラーを設置しています。学校週５日制を含めて、学力低下の問題なんかがあるということも、私どものほうでは十分に認識しています。","id":"exchange-051"},{"speaker":"高星委員","kind":"質問・要望","question":"中は４０℃、５０℃近くになっちゃうじゃないだろうというときに、機械の基盤あたりなんかに支障がないものかどうなのか。その辺のことをどう考えているのか、聞きたいと思ったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"石田委員","kind":"質問・要望","question":"一言だけ要望しておきますが、どういう形でサマースクールに取り組んだいいのか、特色を出したらいいのかというのも含めて。休みは休みなんですから、そこら辺も含めて、よく考えていただくことを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"上山副委員長","kind":"質問","question":"なければいいんですけれども、そういう関係で、今、どんなような状況なのか、最初にちょっとお尋ねしたいんです。数字は持ってないと思いますので、改めてで構いません、そこら辺の概略がわかれば、ちょっと教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"あのときにお話した部分で、若干残っている部分があるというお話を申し上げたとおりです。診断していない部分について、どういう形でしていくのかというような調査は、全国的に来ているです。","id":"exchange-054"},{"speaker":"上山副委員長","kind":"質問・要望","question":"別な機会にお伺いできるんであれば、教えていただきたいと考えていますし、早めにやっていただきたいということ。それから、今後、どこかの機会で教えていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"中島委員","kind":"質問","question":"先ほど、沢田委員もおっしゃったんですが、私もこの新聞を読んだときに、わあ、すごいなと瞬間的に思いました。全国で３０万教室ってあるんですが、日本全体で３０万教室なんか尋ねました。","respondent":"指田教育次長","answer":"私どものほうと国とやり取りするというのは滅多にある話ではありませんので、あるいは、よくまだ話が出て来ない内容じゃないかと思っています。機会があれば、今度は聞いて、もしわかったら、ご連絡したいと思います。","id":"exchange-056"},{"speaker":"中島委員","kind":"質問・要望","question":"夏場の勉強の妨げになるということで、クーラーをという話は、随分要望は聞いているんです。空調全体でバランスを取っていくということが大事ではないかなと思うんですが、その辺のところはどういうふうにお考えか尋ねました。","respondent":"谷田部学務課長","answer":"手法、そういったところもやっぱり学校の中で取り組んでいくということが、子どもたちに対する環境教育にもつながっていくと考えております。","id":"exchange-057"},{"speaker":"中島委員","kind":"意見","question":"それは大変嬉しいことだなと、私も思っておりますし、国会でこれが通っていくのかと考えています。この役所の中でも２８℃の設定をするとか、そこまで考えていくべきではないかということを、申し上げたかったんですとの意見を述べました。","respondent":"指田教育次長","answer":"国のほうの考え方も、文部科学省としても、おそらくまだ細部まで固まっていないと思います。そういったことも含めて、十二分に環境面も配慮して考えていかなければいけないだろうと、このように考えています。","id":"exchange-058"},{"speaker":"中島委員","kind":"質問・要望","question":"これは一つ要望なんですが、全校にそういう設備をしてほしいというのは、要望なんです。品川区ではこれから考えていっていただきたいということで、これは要望したいと思うんですが、一言。","respondent":"指田教育次長","answer":"今、太陽光発電等も備えられるのかどうか、あるいは風力とかそういうものも十二分に考えていかなければいけないと思っています。当然そこにはそういったエコ対策や何かも当然考えていきますけれども、取り入れられるかどうかというのは十二分に考えていきたいと考えております。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4448#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":41067,"voices":142}}]);
